window.JLPT_META = {"title": "JLPT N3 — 直前対策 (文字・語彙・文法)", "subtitle": "Chokuzen Taisaku N3 — o'yin tarzidagi mashq", "levelsCount": 15, "levels": [{"id": 1, "file": "test01.json", "title_jp": "第1回", "title_uz": "1-bosqich", "minutes": 50, "ready": true}, {"id": 2, "file": "test02.json", "title_jp": "第2回", "title_uz": "2-bosqich", "minutes": 50, "ready": true}, {"id": 3, "file": "test03.json", "title_jp": "第3回", "title_uz": "3-bosqich", "minutes": 50, "ready": true}, {"id": 4, "file": "test04.json", "title_jp": "第4回", "title_uz": "4-bosqich", "minutes": 50, "ready": true}, {"id": 5, "file": "test05.json", "title_jp": "第5回", "title_uz": "5-bosqich", "minutes": 50, "ready": true}, {"id": 6, "file": "test06.json", "title_jp": "第6回", "title_uz": "6-bosqich", "minutes": 50, "ready": true}, {"id": 7, "file": "test07.json", "title_jp": "第7回", "title_uz": "7-bosqich", "minutes": 50, "ready": true}, {"id": 8, "file": "test08.json", "title_jp": "第8回", "title_uz": "8-bosqich", "minutes": 50, "ready": true}, {"id": 9, "file": "test09.json", "title_jp": "第9回", "title_uz": "9-bosqich", "minutes": 50, "ready": true}, {"id": 10, "file": "test10.json", "title_jp": "第10回", "title_uz": "10-bosqich", "minutes": 50, "ready": true}, {"id": 11, "file": "test11.json", "title_jp": "第11回", "title_uz": "11-bosqich", "minutes": 50, "ready": true}, {"id": 12, "file": "test12.json", "title_jp": "第12回", "title_uz": "12-bosqich", "minutes": 50, "ready": true}, {"id": 13, "file": "test13.json", "title_jp": "第13回", "title_uz": "13-bosqich", "minutes": 50, "ready": true}, {"id": 14, "file": "test14.json", "title_jp": "第14回", "title_uz": "14-bosqich", "minutes": 50, "ready": true}, {"id": 15, "file": "test15.json", "title_jp": "第15回", "title_uz": "15-bosqich", "minutes": 50, "ready": true}]};
window.JLPT_TESTS = {"1": {"id": 1, "title_jp": "第1回 模擬テスト", "title_uz": "1-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t1-v1-1", "stem": "りんごが箱の中に【並んで】いる。", "reading": "ならんで", "options": ["ついで", "ならんで", "つつんで", "しずんで"], "answer": 2, "explanation_uz": "並ぶ → ならぶ (saf tortmoq, terilmoq)", "tr": "Olmalar quti ichida terilib turibdi."}, {"id": "t1-v1-2", "stem": "あの人が【無事】で、本当に安心しました。", "reading": "ぶじ", "options": ["むし", "むじ", "ぶし", "ぶじ"], "answer": 4, "explanation_uz": "無事 → ぶじ (eson-omon, sog'-salomat)", "tr": "U odam eson-omon ekan, rostdan ham xotirjam bo'ldim."}, {"id": "t1-v1-3", "stem": "2つの事件が【同時】に起こった。", "reading": "どうじ", "options": ["とうじ", "どうじ", "とうき", "どうき"], "answer": 2, "explanation_uz": "同時 → どうじ (bir vaqtda)", "tr": "Ikki hodisa bir vaqtda yuz berdi."}, {"id": "t1-v1-4", "stem": "彼は、私の父に【似て】います。", "reading": "にて", "options": ["にて", "みて", "して", "きて"], "answer": 1, "explanation_uz": "似る → にる (o'xshamoq)", "tr": "U mening otamga o'xshaydi."}, {"id": "t1-v1-5", "stem": "友だちからコンサートの【券】をもらいました。", "reading": "けん", "options": ["かん", "がん", "けん", "げん"], "answer": 3, "explanation_uz": "券 → けん (chipta, talon)", "tr": "Do'stimdan konsert chiptasini oldim."}, {"id": "t1-v1-6", "stem": "彼女は【素直】な性格です。", "reading": "すなお", "options": ["そっちょく", "しょうじき", "すなお", "まっすぐ"], "answer": 3, "explanation_uz": "素直 → すなお (samimiy, itoatkor)", "tr": "Uning fe'l-atvori samimiy (soddadil)."}, {"id": "t1-v1-7", "stem": "ここに【机】を持ってきてください。", "reading": "つくえ", "options": ["だい", "つくえ", "たな", "はこ"], "answer": 2, "explanation_uz": "机 → つくえ (stol, parta)", "tr": "Bu yerga stolni olib keling."}, {"id": "t1-v1-8", "stem": "この店は、1年中休まないで【営業】している。", "reading": "えいぎょう", "options": ["こうぎょう", "えいぎょう", "そうぎょう", "かいぎょう"], "answer": 2, "explanation_uz": "営業 → えいぎょう (savdo, faoliyat yuritish)", "tr": "Bu do'kon yil bo'yi dam olmasdan ishlaydi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'ri variantni tanlang.", "questions": [{"id": "t1-v2-9", "stem": "彼女は、【こうふく】に生活していた。", "options": ["幸後", "広幸", "幸福", "広福"], "answer": 3, "explanation_uz": "こうふく = 幸福 (baxt)", "tr": "U baxtli hayot kechirardi."}, {"id": "t1-v2-10", "stem": "生活を【かいぜん】する。", "options": ["改正", "改造", "改良", "改善"], "answer": 4, "explanation_uz": "かいぜん = 改善 (yaxshilash)", "tr": "Hayotni yaxshilash."}, {"id": "t1-v2-11", "stem": "大きな川に【そって】歩く。", "options": ["添って", "沢って", "沿って", "沼って"], "answer": 3, "explanation_uz": "そう = 沿う (bo'ylab yurmoq)", "tr": "Katta daryo bo'ylab yuradi."}, {"id": "t1-v2-12", "stem": "家を買いたい人に、金を【かす】。", "options": ["買す", "貸す", "借す", "課す"], "answer": 2, "explanation_uz": "かす = 貸す (qarzga bermoq)", "tr": "Uy sotib olmoqchi bo'lganlarga pul qarz beradi."}, {"id": "t1-v2-13", "stem": "これを【きかい】に、たばこをやめようと思う。", "options": ["期回", "期会", "機回", "機会"], "answer": 4, "explanation_uz": "きかい = 機会 (imkoniyat, fursat)", "tr": "Shuni imkoniyat qilib, chekishni tashlamoqchiman."}, {"id": "t1-v2-14", "stem": "【ものごと】を深く考えることは大切だ。", "options": ["物事", "物質", "物語", "物価"], "answer": 1, "explanation_uz": "ものごと = 物事 (narsalar, ishlar)", "tr": "Narsalar haqida chuqur o'ylash muhim."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Qavs ichiga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t1-v3-15", "stem": "新しい仕事のために、みんなで（　）を出し合った。", "options": ["アプローチ", "シフト", "アイデア", "カルチャー"], "answer": 3, "explanation_uz": "アイデア = g'oya", "tr": "Yangi ish uchun hammamiz birga ( ) o'rtaga tashladik."}, {"id": "t1-v3-16", "stem": "大雨のため、大会の（　）が決まった。", "options": ["静止", "禁止", "停止", "中止"], "answer": 4, "explanation_uz": "中止 = bekor qilish", "tr": "Kuchli yomg'ir tufayli musobaqaning ( ) belgilandi."}, {"id": "t1-v3-17", "stem": "大きな家を（　）するのは、大変だ。", "options": ["故障", "管理", "指図", "構成"], "answer": 2, "explanation_uz": "管理 = boshqarish, parvarish qilish", "tr": "Katta uyni ( ) qilish juda mashaqqatli."}, {"id": "t1-v3-18", "stem": "魚を（　）、料理を作った。", "options": ["わかして", "やぶって", "やいて", "こいで"], "answer": 3, "explanation_uz": "焼く (やく) = qovurmoq, pishirmoq", "tr": "Baliqni ( ), taom tayyorladim."}, {"id": "t1-v3-19", "stem": "今日は家にいないので、連絡は明日（　）にお願いします。", "options": ["以来", "以上", "以下", "以降"], "answer": 4, "explanation_uz": "以降 (いこう) = ...dan boshlab/keyin", "tr": "Bugun uyda bo'lmayman, shuning uchun aloqani ertaga ( ) qiling."}, {"id": "t1-v3-20", "stem": "早く病気がなおるよう、（　）います。", "options": ["祈って", "信じて", "困って", "返って"], "answer": 1, "explanation_uz": "祈る (いのる) = duo qilmoq, tilamoq", "tr": "Kasallik tez tuzalishini ( )man."}, {"id": "t1-v3-21", "stem": "親子の（　）をとることは、大切だ。", "options": ["コントロール", "レクリエーション", "サークル", "コミュニケーション"], "answer": 4, "explanation_uz": "コミュニケーション = muloqot", "tr": "Ota-ona va bola o'rtasida ( ) o'rnatish muhim."}, {"id": "t1-v3-22", "stem": "新聞の（　）を読んで、びっくりした。", "options": ["見回し", "見落とし", "見出し", "見返し"], "answer": 3, "explanation_uz": "見出し (みだし) = sarlavha", "tr": "Gazetaning ( )ni o'qib, hayron bo'ldim."}, {"id": "t1-v3-23", "stem": "（　）しないで、たくさんお召し上がりください。", "options": ["辞退", "失礼", "先導", "遠慮"], "answer": 4, "explanation_uz": "遠慮する (えんりょ) = tortinmoq, andisha qilmoq", "tr": "( ) qilmasdan, ko'proq tanovul qiling."}, {"id": "t1-v3-24", "stem": "一生けん命仕事をしていたら、（　）昼になってしまった。", "options": ["いつまでも", "いつのまにか", "どこまでも", "どこか"], "answer": 2, "explanation_uz": "いつのまにか = sezmasdan, bilmagan holda", "tr": "Jon-jahdim bilan ishlayotgan edim, ( ) tush bo'lib qoldi."}, {"id": "t1-v3-25", "stem": "大きな（　）にあったものの、なんとか助かった。", "options": ["怪我", "病気", "事故", "殺人"], "answer": 3, "explanation_uz": "事故にあう (じこ) = baxtsiz hodisaga uchramoq", "tr": "Katta ( )ga uchragan bo'lsam-da, amallab omon qoldim."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t1-v4-26", "stem": "彼は、いつも女の人には【あまい】。", "options": ["情熱的だ", "積極的だ", "きびしい", "やさしい"], "answer": 4, "explanation_uz": "あまい ≈ やさしい (yumshoq, talabchan emas)", "tr": "U doim ayollarga yumshoq (kechirimli) munosabatda bo'ladi."}, {"id": "t1-v4-27", "stem": "たくさん運動したので、のどが【からからだ】。", "options": ["ぬれている", "乾いている", "楽だ", "痛い"], "answer": 2, "explanation_uz": "からから ≈ 乾いている (qurib qolgan)", "tr": "Ko'p mashq qildim, shuning uchun tomog'im qup-quruq."}, {"id": "t1-v4-28", "stem": "この辞書は【結構】便利だ。", "reading": "けっこう", "options": ["おどろくほど", "ちょうどよく", "ある程度は", "前よりもっと"], "answer": 3, "explanation_uz": "結構 (けっこう) ≈ ある程度 (ancha, anchayin)", "tr": "Bu lug'at ancha qulay."}, {"id": "t1-v4-29", "stem": "計画を【言い出した】のは、井上くんだ。", "options": ["一番先に言った", "一番最後に言った", "人から聞いて伝えた", "考えて発表した"], "answer": 1, "explanation_uz": "言い出す ≈ birinchi bo'lib aytmoq/taklif qilmoq", "tr": "Rejani birinchi bo'lib aytgan — Inoue."}, {"id": "t1-v4-30", "stem": "【よけいな】ことを言わないでください。", "options": ["言ったことがある", "言ったことがない", "言ったほうがよい", "言わなくてもよい"], "answer": 4, "explanation_uz": "よけいな = ortiqcha (aytmasa ham bo'ladigan)", "tr": "Ortiqcha gaplarni gapirmang."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、一つえらびなさい。", "instruction_uz": "Berilgan so'z eng to'g'ri ishlatilgan gapni tanlang.", "questions": [{"id": "t1-v5-31", "stem": "くり返す", "options": ["急いでいたので、テーブルといすをくり返してしまった。", "名前を呼ばれたので、後ろをくり返した。", "その人と別れてから、何度もその人のことをくり返した。", "練習のために、先生が言ったことを何度もくり返した。"], "answer": 4, "explanation_uz": "くり返す = takrorlamoq", "optsTr": ["Shoshayotgandim, shuning uchun stol va stulni ag'darib yubordim.", "Ismimni chaqirishdi, shuning uchun orqaga qaytib qaradim.", "U bilan ajrashganimdan keyin, u haqida ko'p marta takrorladim.", "Mashq uchun o'qituvchi aytgan narsalarni ko'p marta takrorladim."]}, {"id": "t1-v5-32", "stem": "生える", "options": ["新しい草木が地面から生えた。", "何時間も考えた後で、新しいアイデアが生えた。", "私の家のとなりに、新しい家が生えた。", "働きすぎたために、病気が生えました。"], "answer": 1, "explanation_uz": "生える (はえる) = o'simlik/tish/soch o'sib chiqmoq", "optsTr": ["Yangi o't-o'simliklar yerdan o'sib chiqdi.", "Soatlab o'ylagandan keyin yangi g'oya o'sib chiqdi.", "Uyim yonida yangi uy o'sib chiqdi.", "Haddan tashqari ishlaganim uchun kasallik o'sib chiqdi."]}, {"id": "t1-v5-33", "stem": "トレーニング", "options": ["わが国は、他の国とトレーニングしている。", "来年は、あの難しい試験にトレーニングしたい。", "朝と夜、体のためにかならずトレーニングしている。", "この車は、デザインだけではなくトレーニングがとてもよい。"], "answer": 3, "explanation_uz": "トレーニング = mashq, trenirovka", "optsTr": ["Bizning davlat boshqa davlatlar bilan trenirovka qilmoqda.", "Kelasi yili o'sha qiyin imtihonga trenirovka qilmoqchiman.", "Ertalab va kechqurun, salomatlik uchun albatta mashq qilaman.", "Bu mashinaning nafaqat dizayni, balki trenirovkasi ham juda yaxshi."]}, {"id": "t1-v5-34", "stem": "努力", "options": ["あの人には、すばらしい努力がある。", "努力して、希望の大学に合格できた。", "病院に入院して、努力を回復した。", "ぜひとも努力のよい社員がほしい。"], "answer": 2, "explanation_uz": "努力 (どりょく) = harakat, mehnat", "optsTr": ["U odamda ajoyib harakat (qobiliyat) bor.", "Harakat qilib, orzu qilgan universitetimga kira oldim.", "Kasalxonaga yotib, harakatni tikladim.", "Albatta harakati yaxshi xodim kerak."]}, {"id": "t1-v5-35", "stem": "なつかしい", "options": ["私のペットの犬と猫は、とても私になつかしい。", "日本へ来て何年たっても、やはり国の家族はなつかしいものだ。", "私は友だちが少ないので、友だちの多い人がなつかしい。", "みんなの前で失敗して、とてもなつかしかった。"], "answer": 2, "explanation_uz": "なつかしい = sog'inchli, qo'msaladigan", "optsTr": ["Uy hayvonlarim — it va mushuk menga juda sog'inchli.", "Yaponiyaga kelganimga necha yil bo'lsa ham, baribir vatandagi oilam sog'iniladi.", "Do'stim kam, shuning uchun do'sti ko'p odam menga sog'inchli.", "Hammaning oldida xato qilib, juda sog'inchli bo'ldim."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを一つえらびなさい。", "instruction_uz": "Gapdagi qavs ichiga eng mos grammatik shaklni tanlang.", "questions": [{"id": "t1-g1-1", "stem": "黒い雲が出ていて、（　）雨が降りそうです。", "options": ["いまが", "いまで", "いまにも", "いまをも"], "answer": 3, "explanation_uz": "いまにも = hozir-hozir, mana-mana", "tr": "Qora bulutlar chiqqan, ( ) yomg'ir yog'adiganga o'xshaydi."}, {"id": "t1-g1-2", "stem": "肉がきらいなら、魚（　）はどうですか。", "options": ["ならでは", "なんか", "にしろ", "こそ"], "answer": 2, "explanation_uz": "〜なんか = ...kabi narsa (taklif/misol)", "tr": "Go'shtni yoqtirmasangiz, baliq ( ) qanday bo'ladi?"}, {"id": "t1-g1-3", "stem": "私は、林さんに会う（　）、すてきな人だと思います。", "options": ["だけに", "たびに", "ばかりに", "ところに"], "answer": 2, "explanation_uz": "〜たびに = har safar ...ganda", "tr": "Men Hayashi-san bilan ( ) uchrashganimda, uni ajoyib inson deb o'ylayman."}, {"id": "t1-g1-4", "stem": "昼ごはんを食べた（　）、おいしいコーヒーを飲みました。", "options": ["後しか", "後へと", "後を", "後で"], "answer": 4, "explanation_uz": "〜た後で = ...gandan keyin", "tr": "Tushlik yegan ( ), mazali qahva ichdim."}, {"id": "t1-g1-5", "stem": "無駄づかいをしてしまい、給料を（　）ばかりなのに、もうお金がない。", "options": ["もらう", "もらって", "もらった", "もらえる"], "answer": 3, "explanation_uz": "〜たばかり = endigina ...gan", "tr": "Isrofgarchilik qilib, oyligimni endigina ( ) bo'lsam-da, allaqachon pulim yo'q."}, {"id": "t1-g1-6", "stem": "私は、友だちがだれもいないところへ（　）はいやです。", "options": ["行くの", "行きの", "行ったの", "行こうの"], "answer": 1, "explanation_uz": "行くの = borish (の bilan otlashtirish)", "tr": "Hech qanday do'stim yo'q joyga ( ) yoqmaydi."}, {"id": "t1-g1-7", "stem": "私の息子は、勉強をしないので、テストの点数が（　）一方だ。", "options": ["下がり", "下がる", "下がった", "下がって"], "answer": 2, "explanation_uz": "〜一方だ = tobora ...laveradi (lug'aviy shakl + 一方だ)", "tr": "O'g'lim o'qimaydi, shuning uchun test ballari ( ) (pasayaveradi)."}, {"id": "t1-g1-8", "stem": "人から借りたお金は、かならず（　）べきだと思います。", "options": ["返し", "返さ", "返す", "返して"], "answer": 3, "explanation_uz": "〜べきだ = ...ishi kerak (lug'aviy shakl + べき)", "tr": "Boshqalardan qarz olgan pulni albatta ( ) kerak deb o'ylayman."}, {"id": "t1-g1-9", "stem": "この仕事を終わらせた（　）、次の仕事を始めよう。", "options": ["上に", "上で", "上はを", "上から"], "answer": 2, "explanation_uz": "〜た上で = ...gandan so'ng, ...gach", "tr": "Bu ishni tugatgan ( ), keyingi ishni boshlaylik."}, {"id": "t1-g1-10", "stem": "客「これは、どこの服ですか。」店員「この服は、フランスのもので（　）。」", "options": ["おります", "います", "いらっしゃいます", "ございます"], "answer": 4, "explanation_uz": "〜でございます = ...dir (muloyim/xushmuomala shakl)", "tr": "Mijoz: «Bu qayerning kiyimi?» Sotuvchi: «Bu kiyim Fransiyaniki ( ).»"}, {"id": "t1-g1-11", "stem": "田中さんが若いころアメリカに住んでいたと（　）が、本当ですか。", "options": ["お聞きました", "お聞きになりました", "うかがわれました", "うかがいました"], "answer": 4, "explanation_uz": "うかがう = 聞く ning kamtarona shakli (eshitdim)", "tr": "Tanaka-san yoshligida Amerikada yashagan deb ( ), bu rostmi?"}, {"id": "t1-g1-12", "stem": "せっかく遠くまで（　）、彼女に会えなかった。", "options": ["会いに行ったので", "会いに行ったから", "会いに行ったのに", "会いに行ったため"], "answer": 3, "explanation_uz": "〜のに = ...ga qaramay", "tr": "Atayin uzoqqacha ( ), lekin u qiz bilan ko'risha olmadim."}, {"id": "t1-g1-13", "stem": "飲酒運転をして事故を起こしてしまい、これからは決して（　）と誓った。", "options": ["酒は飲まない", "酒を飲めない", "酒を飲むこともあるだろう", "酒を飲まないこともないだろう"], "answer": 1, "explanation_uz": "決して〜ない = hech qachon ...emas", "tr": "Mast holda mashina haydab avariya qildim, bundan keyin hech qachon ( ) deb qasam ichdim."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gap bo'laklarini to'g'ri tartibda joylashtiring; ★ o'rniga tushadigan bo'lakni tanlang.", "questions": [{"id": "t1-g2-14", "prefix": "大木「午前中は用があるので、", "suffix": "。」", "starPos": 3, "options": ["いただけませんか", "午後に", "して", "待ち合わせは"], "answer": 3, "order": [4, 2, 3, 1], "explanation_uz": "To'g'ri tartib: 待ち合わせは午後にしていただけませんか", "tr": "To'g'ri tartib: «Uchrashuvni tushdan keyinga belgilab bera olmaysizmi?»"}, {"id": "t1-g2-15", "prefix": "部屋に入り、目の前の大きな", "suffix": "広がっていた。", "starPos": 2, "options": ["海が", "窓を", "輝く", "開けると"], "answer": 4, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: 窓を開けると輝く海が (輝く = かがやく)", "tr": "To'g'ri tartib: «Katta derazani ochsam, yarqirab turgan dengiz yoyilib yotardi.»"}, {"id": "t1-g2-16", "prefix": "あなたが", "suffix": "助かるのですが。", "starPos": 3, "options": ["くれれば", "大変", "引き受けて", "この仕事を"], "answer": 1, "order": [4, 3, 1, 2], "explanation_uz": "To'g'ri tartib: この仕事を引き受けてくれれば大変", "tr": "To'g'ri tartib: «Bu ishni zimmangizga olsangiz, juda katta yordam bo'ladi.»"}, {"id": "t1-g2-17", "prefix": "とてもおなかがすいていたので、注文した料理を食べ", "suffix": "、次の料理を注文した。", "starPos": 2, "options": ["終わったか", "終わらないか", "うちに", "の"], "answer": 2, "order": [1, 2, 4, 3], "explanation_uz": "Ibora: 〜か〜ないかのうちに (食べ終わったか終わらないかのうちに)", "tr": "To'g'ri tartib: «...ovqatni yeb bo'lar-bo'lmas...» (idiom: endigina tugatishi bilan)."}, {"id": "t1-g2-18", "prefix": "私の人生に", "suffix": "娘が生まれた日だ。", "starPos": 3, "options": ["おける", "日とは", "今までで", "最高の"], "answer": 4, "order": [1, 3, 4, 2], "explanation_uz": "To'g'ri tartib: 人生における今までで最高の日とは", "tr": "To'g'ri tartib: «Hayotimdagi shu paytgacha bo'lgan eng zo'r kun deganim...»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、文章全体の内容を考えて、＿＿の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qing va umumiy mazmunga ko'ra bo'sh joylarga eng mos variantni tanlang.", "passage_title": "紙の手帳", "passage": "パソコンや携帯電話などが広く使われるようになってから、自分の予定を管理するため、それらを手帳の代わりに使う人が多くなっている。それでも紙の手帳を使いたいという人も多いのではないだろうか。私もそうである。\n{{19}}商店の手帳売り場へは、夏の終わりごろから来年用の手帳を売りはじめる。\n{{20}}、手帳というと、黒い表紙のシンプルなものが多かったのだが、お店の人に聞いてみると、最近は、特に若い女性向けの商品が{{21}}。女性向けの手帳は以前から売っているが、今年は種類がたくさんあるようだ。{{22a}}、ピンクなど明るくきれいな色のものや、かわいいデザインのもの、自分の好きなペンを取り付けられるタイプ、手帳を止めるバンドやリボンが付いたもの{{22b}}、若い女性が好みそうなものがそろっている。\n私も仕事で手帳をよく使うので、このように選ぶ楽しみが増えたことはうれしい。だが、売り場で選ぼうとしてみても、商品がいろいろたくさんあって、{{23}}。どのような手帳がほしいか考えてから、売り場へ向かおうと思う。", "questions": [{"id": "t1-g3-19", "blankNo": "19", "options": ["あんな", "あのような", "あった", "ある"], "answer": 4, "explanation_uz": "ある商店 = bir(or) do'kon", "tr": "( ) do'konning daftar bo'limida..."}, {"id": "t1-g3-20", "blankNo": "20", "options": ["今からは", "今までは", "次からは", "次までは"], "answer": 2, "explanation_uz": "今までは = shu paytgacha", "tr": "( ), daftar deganda qora muqovali oddiy daftarlar ko'p edi..."}, {"id": "t1-g3-21", "blankNo": "21", "options": ["増えていそうだ", "増えているそうだ", "増えてありそうだ", "増えてあるそうだ"], "answer": 2, "explanation_uz": "増えているそうだ = ko'payayotgan emish (eshitilgan)", "tr": "...yosh ayollarga mo'ljallangan mahsulotlar ( )."}, {"id": "t1-g3-22", "blankNo": "22", "options": ["a なぜなら / b だから", "a ところが / b がないので", "a たとえば / b など", "a たぶん / b であれば"], "answer": 3, "explanation_uz": "a たとえば (masalan) ... b など (va hokazo)", "tr": "( a ) ... ( b ) ... (yosh ayollar yoqtiradigan narsalar muhayyo)."}, {"id": "t1-g3-23", "blankNo": "23", "options": ["急に決めた", "急に決まるだろう", "すぐに決められなかった", "すぐに決められないだろう"], "answer": 4, "explanation_uz": "すぐに決められないだろう = tezda tanlay olmasam kerak", "tr": "...mahsulotlar juda ko'p bo'lib, ( )."}], "passage_tr": "Kompyuter va mobil telefonlar keng qo'llanila boshlaganidan beri, o'z rejalarini boshqarish uchun ularni daftar o'rniga ishlatadiganlar ko'paygan. Shunga qaramay, qog'oz daftar ishlatmoqchi bo'lganlar ham ko'p-ku. Men ham shundayman. Bir do'konning daftar bo'limida yoz oxiridan kelasi yilgi daftarlar sotila boshlaydi. Shu paytgacha daftar deganda qora muqovali oddiy daftarlar ko'p edi, ammo do'kon xodimi aytishicha, so'nggi paytda, ayniqsa yosh ayollarga mo'ljallangan mahsulotlar ko'payayotgan emish. Ayollar uchun daftarlar ilgaridan sotilgan, lekin bu yil turlari juda ko'p ekan. Masalan, pushti kabi yorqin chiroyli ranglilar, chiroyli dizayndagilar, o'zi yoqtirgan ruchkani biriktirsa bo'ladigan turi, daftarni bog'lab turadigan tasma yoki lentasi borlari va hokazo — yosh ayollar yoqtiradigan narsalar muhayyo. Men ham ishda daftardan ko'p foydalanaman, shuning uchun bunday tanlash zavqi ko'payganidan xursandman. Ammo do'konda tanlamoqchi bo'lsam ham, mahsulot juda ko'p bo'lgani uchun tezda tanlay olmasam kerak. Qanday daftar xohlashimni o'ylab olgach, do'konga boraman deb o'ylayman."}]}]}, "2": {"id": 2, "title_jp": "第2回 模擬テスト", "title_uz": "2-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t2-v1-1", "stem": "家の前に、きれいな花が【咲いて】います。", "options": ["まいて", "おいて", "ついて", "さいて"], "answer": 4, "tr": "Uy oldida chiroyli gul ochilib turibdi.", "reading": "さいて", "explanation_uz": "咲く → さく (ochilmoq, gullamoq)"}, {"id": "t2-v1-2", "stem": "父は、【普通】の会社員です。", "options": ["ふつう", "ふうつう", "ふづう", "ふうづう"], "answer": 1, "tr": "Otam oddiy kompaniya xodimi.", "reading": "ふつう", "explanation_uz": "普通 → ふつう (oddiy)"}, {"id": "t2-v1-3", "stem": "【借金】して車を買った。", "options": ["かりきん", "かしきん", "しゃっきん", "しゃくきん"], "answer": 3, "tr": "Qarz olib mashina sotib oldim.", "reading": "しゃっきん", "explanation_uz": "借金 → しゃっきん (qarz)"}, {"id": "t2-v1-4", "stem": "部屋に何人か【残って】いる。", "options": ["あまって", "かえって", "そろって", "のこって"], "answer": 4, "tr": "Xonada bir necha kishi qolyapti.", "reading": "のこって", "explanation_uz": "残る → のこる (qolmoq)"}, {"id": "t2-v1-5", "stem": "仕事のことを考えると、【胃】が痛い。", "options": ["おなか", "い", "ちょう", "はら"], "answer": 2, "tr": "Ish haqida o'ylasam, oshqozonim og'riydi.", "reading": "い", "explanation_uz": "胃 → い (oshqozon)"}, {"id": "t2-v1-6", "stem": "アルバイトで遅くなり、午前1時に【帰宅】しました。", "options": ["きてく", "きでく", "きたく", "きだく"], "answer": 3, "tr": "Ish (albatta) tufayli kechikib, tungi soat 1 da uyga qaytdim.", "reading": "きたく", "explanation_uz": "帰宅 → きたく (uyga qaytish)"}, {"id": "t2-v1-7", "stem": "私は、【乱暴】な人はきらいです。", "options": ["ぼうりょく", "おうぼう", "らんぼう", "らんざつ"], "answer": 3, "tr": "Men qo'pol odamlarni yoqtirmayman.", "reading": "らんぼう", "explanation_uz": "乱暴 → らんぼう (qo'pol, dag'al)"}, {"id": "t2-v1-8", "stem": "有名な俳優がステージに【登場】した。", "options": ["とじょう", "とうじょう", "とじょ", "とうじょ"], "answer": 2, "tr": "Mashhur aktyor sahnaga chiqdi.", "reading": "とうじょう", "explanation_uz": "登場 → とうじょう (sahnaga chiqish, paydo bo'lish)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t2-v2-9", "stem": "【じゆう】に生きたいと思っている。", "options": ["自由", "時由", "治由", "事由"], "answer": 1, "tr": "Erkin yashashni xohlayman.", "explanation_uz": "じゆう → 自由 (erkinlik)"}, {"id": "t2-v2-10", "stem": "その映画を見て、深く【かんどう】した。", "options": ["感情", "感動", "感働", "感激"], "answer": 2, "tr": "O'sha filmni ko'rib, qattiq ta'sirlandim.", "explanation_uz": "かんどう → 感動 (ta'sirlanish, hayajonlanish)"}, {"id": "t2-v2-11", "stem": "敵から【にげて】、ここまで来た。", "options": ["込げて", "退げて", "迫げて", "逃げて"], "answer": 4, "tr": "Dushmandan qochib, shu yergacha keldim.", "explanation_uz": "にげる → 逃げる (qochmoq)"}, {"id": "t2-v2-12", "stem": "できるだけ早い返事を【もとめる】。", "options": ["許める", "求める", "元める", "基める"], "answer": 2, "tr": "Iloji boricha tezroq javob talab qilaman.", "explanation_uz": "もとめる → 求める (talab qilmoq, izlamoq)"}, {"id": "t2-v2-13", "stem": "地図が【ふくざつ】すぎて、よくわからない。", "options": ["乱雑", "混雑", "複雑", "服雑"], "answer": 3, "tr": "Xarita juda murakkab, yaxshi tushunmayapman.", "explanation_uz": "ふくざつ → 複雑 (murakkab)"}, {"id": "t2-v2-14", "stem": "彼のやり方について、【もんく】を言う。", "options": ["文苦", "文口", "文句", "文言"], "answer": 3, "tr": "Uning uslubiga e'tiroz (norozilik) bildiraman.", "explanation_uz": "もんく → 文句 (e'tiroz, norozilik)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t2-v3-15", "stem": "駅で、電車が遅れるという（　）があった。", "options": ["インタビュー", "アナウンス", "コーラス", "スピーチ"], "answer": 2, "tr": "Bekatda poyezd kechikishi haqida e'lon (anons) bo'ldi.", "explanation_uz": "アナウンス = e'lon, ovozli xabar"}, {"id": "t2-v3-16", "stem": "買い物するときに、クレジットカードで（　）した。", "options": ["代用", "作用", "利用", "応用"], "answer": 3, "tr": "Xarid qilganda kredit kartadan foydalandim.", "explanation_uz": "利用 = foydalanish"}, {"id": "t2-v3-17", "stem": "仕事をやめて、外国に住むことを（　）した。", "options": ["決意", "感覚", "感想", "意志"], "answer": 1, "tr": "Ishni tashlab, chet elda yashashga qat'iy qaror qildim.", "explanation_uz": "決意 = qat'iy qaror"}, {"id": "t2-v3-18", "stem": "友だちの肩を（　）、名前を呼んだ。", "options": ["曲げて", "たたいて", "攻めて", "守って"], "answer": 2, "tr": "Do'stimning yelkasiga sekin urib, ismini chaqirdim.", "explanation_uz": "たたく = urmoq, taqillatmoq"}, {"id": "t2-v3-19", "stem": "今年も、去年と（　）のイベントが開かれる。", "options": ["同意", "同点", "同様", "同級"], "answer": 3, "tr": "Bu yil ham o'tgan yildagi kabi (xuddi shunday) tadbir o'tkaziladi.", "explanation_uz": "同様 = xuddi shunday, bir xil"}, {"id": "t2-v3-20", "stem": "誕生日にプレゼントを（　）つもりです。", "options": ["つかむ", "つまむ", "投げる", "贈る"], "answer": 4, "tr": "Tug'ilgan kunda sovg'a qilmoqchiman.", "explanation_uz": "贈る = sovg'a qilmoq (taqdim etmoq)"}, {"id": "t2-v3-21", "stem": "家の前で、道が大きく（　）している。", "options": ["アウト", "レール", "カーブ", "ドロップ"], "answer": 3, "tr": "Uy oldida yo'l keskin buriladi.", "explanation_uz": "カーブ = burilish, egrilik"}, {"id": "t2-v3-22", "stem": "きのう、大学入学の（　）が終わりました。", "options": ["手分け", "手直し", "手回し", "手続き"], "answer": 4, "tr": "Kecha universitetga kirish rasmiylashtiruvi tugadi.", "explanation_uz": "手続き = rasmiylashtirish, jarayon"}, {"id": "t2-v3-23", "stem": "おなかがすいたが、何も食べないで（　）した。", "options": ["我慢", "通用", "飲食", "許可"], "answer": 1, "tr": "Qornim ochdi, lekin hech narsa yemay chidadim (sabr qildim).", "explanation_uz": "我慢 = sabr, chidam"}, {"id": "t2-v3-24", "stem": "伊藤「山田さんは、大学の先生なんですって。」清水「へえ、（　）、田中さんも大学に勤めているそうですよ。」", "options": ["そうしたら", "それとも", "そうすれば", "そういえば"], "answer": 4, "tr": "Ito: «Yamada-san universitet o'qituvchisi emish.» Shimizu: «Voy, aytgancha, Tanaka-san ham universitetda ishlarmish.»", "explanation_uz": "そういえば = aytgancha, shu esimga tushdi"}, {"id": "t2-v3-25", "stem": "国と国との関係が悪くなって、（　）が起こった。", "options": ["競走", "和平", "戦争", "平和"], "answer": 3, "tr": "Davlatlararo munosabat yomonlashib, urush boshlandi.", "explanation_uz": "戦争 = urush"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t2-v4-26", "stem": "この店は、いつも【そうぞうしい】。", "options": ["安い", "高い", "静かだ", "うるさい"], "answer": 4, "tr": "Bu do'kon doim shovqinli.", "explanation_uz": "騒々しい (そうぞうしい) = うるさい (shovqinli)"}, {"id": "t2-v4-27", "stem": "彼はとても【がんこだ】。", "options": ["考えを変える", "考えを変えない", "気が強い", "気が弱い"], "answer": 2, "tr": "U juda o'jar.", "explanation_uz": "頑固 (がんこ) = o'jar (fikrini o'zgartirmaydigan)"}, {"id": "t2-v4-28", "stem": "私は山を【ながめる】ことが好きです。", "options": ["見る", "登る", "文章にする", "絵を描く"], "answer": 1, "tr": "Men tog'ga (uzoq) tikilib qarashni yaxshi ko'raman.", "explanation_uz": "眺める (ながめる) = 見る (tikilib qaramoq)"}, {"id": "t2-v4-29", "stem": "彼は、いつも時間に【だらしない】。", "options": ["時間を守らない", "時間通りに行動する", "時間を気にしている", "時間に正確だ"], "answer": 1, "tr": "U doim vaqtga beparvo (vaqtni saqlamaydi).", "explanation_uz": "だらしない = tartibsiz; vaqtni saqlamaydi"}, {"id": "t2-v4-30", "stem": "このパンは【ふわふわ】している。", "options": ["軽くなっている", "古くなっている", "やわらかい", "かたい"], "answer": 3, "tr": "Bu non yumshoq (g'ovak).", "explanation_uz": "ふわふわ = yumshoq, g'ovak"}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t2-v5-31", "stem": "思い出す", "options": ["全員で会議をして、新しいアイデアを思い出した。", "何度も書き順の練習をして、難しい漢字を思い出した。", "長い時間考えて、知り合いの名前をやっと思い出した。", "心配なことがあると、いつもカフェで1人、思い出した。"], "answer": 3, "tr": "思い出す = (esga) eslamoq, yodga tushirmoq.", "optsTr": ["Hammamiz yig'ilish qilib, yangi g'oyani 'esladik'.", "Ko'p marta yozuv tartibini mashq qilib, qiyin kanjini 'esladim'.", "Uzoq o'ylab, tanishimning ismini nihoyat esladim.", "Xavotirim bo'lsa, doim kafeda yolg'iz 'eslardim'."]}, {"id": "t2-v5-32", "stem": "こめる", "options": ["燃えないごみを、ごみ箱にこめてください。", "スカートをこめて、短くしなければなりません。", "今日は早めにおふろに水をこめてください。", "手紙に、気持ちをこめて書きなさい。"], "answer": 4, "tr": "こめる (込める) = (his-tuyg'u, kuch) singdirmoq, jamlamoq.", "optsTr": ["Yonmaydigan chiqindini axlat qutisiga 'singdiring' (noto'g'ri).", "Yubkani 'singdirib' qisqartirish kerak (noto'g'ri).", "Bugun erta vannaga suvni 'singdiring' (noto'g'ri).", "Xatga his-tuyg'uni singdirib yozing. (to'g'ri)"]}, {"id": "t2-v5-33", "stem": "ルート", "options": ["外国では、その国のルートの通りにしなければならない。", "駅から会社まで、いちばん近いルートを教えてください。", "彼女の顔にはよいルートが出ていた。", "ルートをしたまま、おふろに入らないでください。"], "answer": 2, "tr": "ルート = yo'nalish, marshrut.", "optsTr": ["Chet elda o'sha mamlakatning 'marshruti' bo'yicha qilish kerak (noto'g'ri).", "Bekatdan kompaniyagacha eng yaqin yo'lni (marshrutni) ayting. (to'g'ri)", "Uning yuzida yaxshi 'marshrut' chiqqan edi (noto'g'ri).", "'Marshrut' qilgan holda vannaga kirmang (noto'g'ri)."]}, {"id": "t2-v5-34", "stem": "得意", "options": ["やり方を教えてもらって、得意をしました。", "私は、子どものころからピアノを得意でした。", "彼女の電話番号が得意だったら、教えてください。", "私は、そうじより料理のほうが得意です。"], "answer": 4, "tr": "得意 = mohir, ustasi; (biror ishni) yaxshi eplaydigan.", "optsTr": ["Uslubni o'rganib, 'mohirlik' qildim (noto'g'ri).", "Men bolaligimdan pianino 'mohir edim' (noto'g'ri).", "Uning telefon raqami 'mohir' bo'lsa, ayting (noto'g'ri).", "Men tozalashdan ko'ra ovqat pishirishni yaxshiroq eplayman. (to'g'ri)"]}, {"id": "t2-v5-35", "stem": "うらやましい", "options": ["スポーツも勉強もできる友人がうらやましい。", "悪い人にだまされて、とてもうらやましい。", "外国で1人で生活していたら、うらやましくなった。", "母の作った料理がうらやましくて、たくさん食べた。"], "answer": 1, "tr": "うらやましい = havasi keladigan, rashk qiladigan.", "optsTr": ["Sport ham, o'qish ham qo'lidan keladigan do'stimga havasim keladi. (to'g'ri)", "Yomon odam aldab ketdi, juda 'havasim keladi' (noto'g'ri).", "Chet elda yolg'iz yashasam, 'havasim keldi' (noto'g'ri).", "Onam pishirgan ovqatga 'havasim kelib', ko'p yedim (noto'g'ri)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t2-g1-1", "stem": "確か先輩が、今日の授業はない（　）言っていました。", "options": ["だと", "と", "を", "に"], "answer": 2, "tr": "Aniq esimda, sempay bugun dars yo'q deб aytgan edi.", "explanation_uz": "〜と言う = deб aytmoq (iqtibos)"}, {"id": "t2-g1-2", "stem": "私が元気でいる（　）家族に伝えてください。", "options": ["を", "ものを", "ことを", "あいだを"], "answer": 3, "tr": "Men sog'-salomat ekanimni oilamga yetkazing.", "explanation_uz": "〜ことを伝える = ...ekanini yetkazmoq"}, {"id": "t2-g1-3", "stem": "走れる（　）、マラソンを続けるつもりだ。", "options": ["までは", "限りは", "ばかりは", "中は"], "answer": 2, "tr": "Yugura olganimcha, marafonni davom ettirmoqchiman.", "explanation_uz": "〜限り(は) = ...gancha, ...gan ekan"}, {"id": "t2-g1-4", "stem": "このまま夜遅くまで働く毎日が続くと、病気になる（　）。", "options": ["おそれがある", "気がある", "ところがある", "ものがある"], "answer": 1, "tr": "Shu zaylda har kuni kechgacha ishlash davom etsa, kasal bo'lib qolish xavfi bor.", "explanation_uz": "〜おそれがある = ...xavfi bor"}, {"id": "t2-g1-5", "stem": "彼は大学で英語を勉強し、（　）自分でフランス語も学習している。", "options": ["むしろ", "または", "さらに", "上に"], "answer": 3, "tr": "U universitetda ingliz tilini o'qigan, bundan tashqari o'zicha fransuz tilini ham o'rganmoqda.", "explanation_uz": "さらに = bundan tashqari, yana"}, {"id": "t2-g1-6", "stem": "ジョギングを始める（　）、体の調子がよくありませんでした。", "options": ["前に", "前で", "前と", "前は"], "answer": 4, "tr": "Yugurishni boshlashdan oldin, sog'lig'im yaxshi emas edi.", "explanation_uz": "〜前は = ...dan oldin (avvalgi holat)"}, {"id": "t2-g1-7", "stem": "寒くならない（　）、家へ帰りましょう。", "options": ["うちで", "うちに", "うちは", "うちまでに"], "answer": 2, "tr": "Sovuq bo'lib qolmasdan (sovimasdan) turib, uyga qaytaylik.", "explanation_uz": "〜ないうちに = ...magunicha, ...masdan turib"}, {"id": "t2-g1-8", "stem": "寒い季節には風邪を（　）ので、気をつけてください。", "options": ["ひき気味", "ひきがち", "ひききり", "ひきかけ"], "answer": 2, "tr": "Sovuq faslda tez-tez shamollab qolasiz, shuning uchun ehtiyot bo'ling.", "explanation_uz": "〜がち = tez-tez ...adigan, moyil"}, {"id": "t2-g1-9", "stem": "学生なのだから、宿題は（　）なりません。", "options": ["しないでは", "しなくても", "しなくて", "しなくては"], "answer": 4, "tr": "Talaba ekansiz, uy vazifasini bajarmasangiz bo'lmaydi.", "explanation_uz": "〜なくてはならない = ...masa bo'lmaydi (shart)"}, {"id": "t2-g1-10", "stem": "店長「明日から、もうバイトに来ないでください。」店員「えっ、（　）ことですか。理由を教えてください。」", "options": ["あのくらいの", "どのくらいの", "ああいう", "どういう"], "answer": 4, "tr": "Boshliq: «Ertadan ishga kelmang.» Xodim: «A, bu qanaqasi (nima degani)? Sababini ayting.»", "explanation_uz": "どういうことですか = bu nima degani / qanday gap"}, {"id": "t2-g1-11", "stem": "いくらチョコレートが好きでも、一度に（　）体によくないだろう。", "options": ["あんなに食べたら", "こんなに食べてみて", "あれほどに食べたいなら", "これくらい食べても"], "answer": 1, "tr": "Shokoladni qancha yaxshi ko'rsang ham, bir vaqtda 'shuncha' yesang, salomatlikka yomon-da.", "explanation_uz": "あんなに〜たら = shuncha ...sa (haddan ortiq)"}, {"id": "t2-g1-12", "stem": "加藤「週末、一緒に映画を見に行きませんか。」高田「すみません。仕事がいそがしくて、映画を（　）のです。」", "options": ["見に行くことがない", "見に行くことではない", "見に行くところがない", "見に行くどころではない"], "answer": 4, "tr": "Kato: «Dam olishda birga kinoga bormaymizmi?» Takada: «Kechirasiz, ishim band, kino ko'rishga vaqt yo'q (bunaqa holatda emasman).»", "explanation_uz": "〜どころではない = ...ga vaqt/hol yo'q"}, {"id": "t2-g1-13", "stem": "姉はある歌手の大ファンで、「彼くらい歌が（　）」と、必ずライブに行く。", "options": ["上手な人がいるだろう", "上手な人はいない", "上手な人もいた", "上手な人になりえない"], "answer": 2, "tr": "Opam bir qo'shiqchining katta muxlisi, «undan ko'ra yaxshi kuylaydigan odam yo'q» deб, albatta konsertga boradi.", "explanation_uz": "〜くらい〜はいない = ...chalik (yaxshi) yana yo'q"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t2-g2-14", "options": ["じゃありませんか", "動いている", "ばかり", "私"], "answer": 3, "tr": "To'g'ri tartib: «Anchadan beri faqat men ishlayapman-ku!»", "explanation_uz": "To'g'ri tartib: 私ばかり動いているじゃありませんか", "prefix": "小池「さっきから、", "suffix": "。」", "starPos": 2, "order": [4, 3, 2, 1]}, {"id": "t2-g2-15", "options": ["して", "ことが", "いる", "過ごして"], "answer": 3, "tr": "To'g'ri tartib: «Odatda golf o'ynab vaqt o'tkazaman.»", "explanation_uz": "To'g'ri tartib: ゴルフをして過ごしていることが多い", "prefix": "山本「だいたいゴルフを", "suffix": "多いですね。」", "starPos": 3, "order": [1, 4, 3, 2]}, {"id": "t2-g2-16", "options": ["ご予定", "いらっしゃる", "なのか", "何時ごろ"], "answer": 1, "tr": "To'g'ri tartib: «Ertangi yig'ilishga soat nechada kelishingizni aytib bera olasizmi?»", "explanation_uz": "To'g'ri tartib: 何時ごろいらっしゃるご予定なのか", "prefix": "社員「社長、明日の会議に、", "suffix": "教えていただけますか。」", "starPos": 3, "order": [4, 2, 1, 3]}, {"id": "t2-g2-17", "options": ["あって", "こと", "いろいろな", "だけ"], "answer": 3, "tr": "To'g'ri tartib: «Morikava-san olim bo'lgani uchun turli narsani biladi.»", "explanation_uz": "To'g'ri tartib: 学者だけあっていろいろなことを (知っている)", "prefix": "さすが森川さんは、学者", "suffix": "を知っている。", "starPos": 3, "order": [4, 1, 3, 2]}, {"id": "t2-g2-18", "options": ["仕事が", "ロボットが", "する", "かわって"], "answer": 2, "tr": "To'g'ri tartib: «Bir maqolaga ko'ra, kelajakda inson o'rniga robot bajaradigan ishlar ko'payarmish.»", "explanation_uz": "To'g'ri tartib: 人間にかわってロボットがする仕事が (増える)", "prefix": "ある論文によると、今後は、人間に", "suffix": "増えるそうだ。", "starPos": 2, "order": [4, 2, 3, 1]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "大人になれば", "passage": "子どものころ、自分の親と同じ年齢になれば、立派な大人になれるのだろうと思っていた。だが、自分が「大人」であると思っていた年齢に{{19}}、成長できていない自分に驚く。\nたとえば、朝はいつまでも寝ていたいと思うのも、子どものころと同じだ。さらに、仕事が大変なときに、何度も会社を休みたくなったりする。「熱が出たから」とうそをついて、本当に会社を休んだことも{{20}}。子どものころは、本当に熱があっても、学校へきちんと通っていたのに。また、にんじんやピーマンなど、子どものころきらいだった食べ物は、今でも{{21a}}、料理に入っていると{{21b}}。それなのに、自分の子どもには「好ききらいをせずに、なんでも食べなさい」と言ったりする。\n{{22}}いばったり、うまくうそがつけるような大人になった今の自分は、子どものころより成長するどころか、悪くなっているのかもしれない。{{23}}、自分の父や母も、昔は今の自分のように考え、「大人」になろうとがんばっていたのかと思うと、なんだかあたたかい気持ちになるのだ。", "passage_tr": "Bolaligimda, ota-onam bilan teng yoshga yetsam, yetuk katta odam bo'laman deb o'ylardim. Ammo o'zim «katta odam» deb hisoblagan yoshga yetib qarasam, hali ulg'aymaganimdan hayron bo'laman. Masalan, ertalab uzoq uxlagim kelishi ham bolalikdagidek. Bundan tashqari, ish og'ir bo'lganda necha marta ishni qoldirgim keladi. «Isitmam chiqdi» deb yolg'on aytib, rostdan ishga bormagan paytlarim ham bo'lgan. Holbuki bolaligimda rost isitmam bo'lsa ham, maktabga muntazam borardim. Yana, sabzi va qalampir kabi bolaligimda yoqtirmagan taomlarni hozir ham yoqtirmayman, shuning uchun ovqatga solingan bo'lsa, yemaslikka harakat qilaman. Shunga qaramay, o'z bolamga «tanlamasdan, hamma narsani ye» deb aytaman. Shunday kekkayadigan, ustalik bilan yolg'on aytadigan katta odamga aylangan hozirgi o'zim — bolaligimdagidan o'sish o'rniga, balki yomonlashgandirman. Shunday ekan, ota-onam ham ilgari xuddi hozirgi men kabi o'ylab, «katta odam» bo'lishga harakat qilgan ekan-da deb o'ylasam, allaqanday iliq tuyg'u paydo bo'ladi.", "questions": [{"id": "t2-g3-19", "options": ["なるところに", "なったように", "なってみると", "なるとしたら"], "answer": 3, "tr": "「大人」だと思っていた年齢に[なってみると]、成長できていない自分に驚く。", "explanation_uz": "〜てみると = ...sam/qilib ko'rsam (natija)", "blankNo": "19"}, {"id": "t2-g3-20", "options": ["あるかないかわからない", "めったにない", "あるくらいだ", "あるはずがないのだ"], "answer": 3, "tr": "会社を休んだことも[あるくらいだ] = hatto ishni qoldirgan paytlarim ham bor.", "explanation_uz": "〜くらいだ = hatto ... darajada", "blankNo": "20"}, {"id": "t2-g3-21", "options": ["きらいだから ／ 食べるようにしている", "きらいだから ／ 食べないようにしている", "好きだから ／ 食べるようにしている", "好きだから ／ 食べないようにしている"], "answer": 2, "tr": "今でも[a きらいだから]、料理に入っていると[b 食べないようにしている].", "explanation_uz": "a きらいだから (yoqtirmayman) / b 食べないようにしている (yemaslikka harakat)", "blankNo": "21"}, {"id": "t2-g3-22", "options": ["そんなふうに", "どんなふうに", "あんなふうに", "どんなような"], "answer": 1, "tr": "[そんなふうに]いばったり… = o'shanday kekkayib…", "explanation_uz": "そんなふうに = o'shanday, shu tarzda", "blankNo": "22"}, {"id": "t2-g3-23", "options": ["ところが", "つまり", "または", "そして"], "answer": 4, "tr": "[そして]、自分の父や母も… = Va, ota-onam ham…", "explanation_uz": "そして = va, shundan keyin (qo'shimcha)", "blankNo": "23"}]}]}]}, "3": {"id": 3, "title_jp": "第3回 模擬テスト", "title_uz": "3-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t3-v1-1", "stem": "桜の花は、もう【散って】しまった。", "options": ["いって", "まって", "さって", "ちって"], "answer": 4, "reading": "ちって", "explanation_uz": "散る → ちる (to'kilmoq, sochilmoq)", "tr": "Sakura gullari allaqachon to'kilib bo'ldi."}, {"id": "t3-v1-2", "stem": "今の生活に【満足】ですか。", "options": ["まんそく", "まんぞく", "まんそぐ", "まんぞぐ"], "answer": 2, "reading": "まんぞく", "explanation_uz": "満足 → まんぞく (mamnunlik, qoniqish)", "tr": "Hozirgi hayotingizdan mamnunmisiz?"}, {"id": "t3-v1-3", "stem": "この駅から【急行】に乗るつもりだ。", "options": ["くこう", "くうこう", "きゅこう", "きゅうこう"], "answer": 4, "reading": "きゅうこう", "explanation_uz": "急行 → きゅうこう (tezyurar (poyezd))", "tr": "Shu bekatdan tezyurar poyezdga chiqmoqchiman."}, {"id": "t3-v1-4", "stem": "彼女は川に落ち、【意識】がなくなった。", "options": ["ちしき", "にんしき", "けんしき", "いしき"], "answer": 4, "reading": "いしき", "explanation_uz": "意識 → いしき (hush, ong)", "tr": "U daryoga yiqilib, hushini yo'qotdi."}, {"id": "t3-v1-5", "stem": "あの人と私の能力の【差】は大きい。", "options": ["さ", "ざ", "さい", "ざい"], "answer": 1, "reading": "さ", "explanation_uz": "差 → さ (farq, tafovut)", "tr": "U bilan mening qobiliyatim o'rtasidagi farq katta."}, {"id": "t3-v1-6", "stem": "新聞に【広告】をのせる。", "options": ["ここく", "こうく", "こうこく", "こうくう"], "answer": 3, "reading": "こうこく", "explanation_uz": "広告 → こうこく (reklama, e'lon)", "tr": "Gazetaga reklama joylashtiraman."}, {"id": "t3-v1-7", "stem": "運動をして、【汗】をたくさんかいた。", "options": ["なみだ", "あせ", "いき", "みず"], "answer": 2, "reading": "あせ", "explanation_uz": "汗 → あせ (ter)", "tr": "Sport bilan shug'ullanib, ko'p terladim."}, {"id": "t3-v1-8", "stem": "夜中の外出を【禁止】する。", "options": ["きんし", "きんじ", "ぎんし", "ぎんじ"], "answer": 1, "reading": "きんし", "explanation_uz": "禁止 → きんし (taqiq)", "tr": "Tunda tashqariga chiqish taqiqlanadi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t3-v2-9", "stem": "この国は、天然資源が【ほうふ】だ。", "options": ["盛富", "宝富", "豊富", "広富"], "answer": 3, "explanation_uz": "ほうふ → 豊富 (mo'l-ko'l, boy)", "tr": "Bu mamlakatda tabiiy resurslar mo'l-ko'l."}, {"id": "t3-v2-10", "stem": "テストの前に、単語を【あんき】した。", "options": ["案記", "明記", "安記", "暗記"], "answer": 4, "explanation_uz": "あんき → 暗記 (yod olish)", "tr": "Test oldidan so'zlarni yodladim."}, {"id": "t3-v2-11", "stem": "地震に【そなえて】、水と食べ物を買う。", "options": ["準えて", "備えて", "供えて", "背えて"], "answer": 2, "explanation_uz": "そなえる → 備える (tayyorgarlik ko'rmoq)", "tr": "Zilzilaga tayyorgarlik ko'rib, suv va oziq-ovqat sotib olaman."}, {"id": "t3-v2-12", "stem": "大きなミスをして、仕事を【うしなう】ことになった。", "options": ["失う", "夫う", "矢う", "央う"], "answer": 1, "explanation_uz": "うしなう → 失う (yo'qotmoq, ayrilmoq)", "tr": "Katta xato qilib, ishimdan ayriladigan bo'ldim."}, {"id": "t3-v2-13", "stem": "日本のマンガに【きょうみ】があります。", "options": ["教味", "教見", "興味", "興見"], "answer": 3, "explanation_uz": "きょうみ → 興味 (qiziqish)", "tr": "Yapon mangasiga qiziqaman."}, {"id": "t3-v2-14", "stem": "結婚して、2人は【ふうふ】になった。", "options": ["夫妻", "妻夫", "夫婦", "婦夫"], "answer": 3, "explanation_uz": "ふうふ → 夫婦 (er-xotin)", "tr": "Turmush qurib, ikkovi er-xotin bo'lishdi."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t3-v3-15", "stem": "高校生のとき、初めて海外で（　）した。", "options": ["パスポート", "クラスメート", "ホームページ", "ホームステイ"], "answer": 4, "explanation_uz": "ホームステイ = mahalliy oilada yashash", "tr": "O'rta maktabda ilk bor chet elda oilada (homestay) yashadim."}, {"id": "t3-v3-16", "stem": "今日は、晴れて空気が（　）している。", "options": ["燃焼", "点火", "乾燥", "熱中"], "answer": 3, "explanation_uz": "乾燥 = quruqlik, qurish", "tr": "Bugun ochiq, havo quruq."}, {"id": "t3-v3-17", "stem": "その日は、風が強く（　）いました。", "options": ["空いて", "巻いて", "開いて", "吹いて"], "answer": 4, "explanation_uz": "吹く = esmoq (shamol)", "tr": "O'sha kuni shamol kuchli esardi."}, {"id": "t3-v3-18", "stem": "彼は、エンジニアの仕事でたくさん（　）いる。", "options": ["かせいで", "得て", "あげて", "受けて"], "answer": 1, "explanation_uz": "稼ぐ (かせぐ) = pul topmoq", "tr": "U muhandislik ishida ko'p pul topadi."}, {"id": "t3-v3-19", "stem": "うそを言わず、（　）で話し合いたい。", "options": ["意見", "本音", "解答", "正解"], "answer": 2, "explanation_uz": "本音 = chin dildagi fikr", "tr": "Yolg'on aytmasdan, ochiq dildan (samimiy) gaplashmoqchiman."}, {"id": "t3-v3-20", "stem": "この車は、まだ新しいので（　）だ。", "options": ["ぴかぴか", "ふらふら", "ぺこぺこ", "くるくる"], "answer": 1, "explanation_uz": "ぴかぴか = yaltiroq, charaqlagan", "tr": "Bu mashina hali yangi, shuning uchun yaltirab turibdi."}, {"id": "t3-v3-21", "stem": "その問題については、よくわからないので（　）できません。", "options": ["コート", "コンセント", "コンクール", "コメント"], "answer": 4, "explanation_uz": "コメント = izoh, sharh", "tr": "Bu masala bo'yicha yaxshi bilmaganim uchun izoh bera olmayman."}, {"id": "t3-v3-22", "stem": "毎日、校庭の木の（　）をするのは、大変だ。", "options": ["手入れ", "手引き", "手出し", "手抜き"], "answer": 1, "explanation_uz": "手入れ = parvarish, qarov", "tr": "Har kuni maktab hovlisidagi daraxtlarni parvarish qilish og'ir."}, {"id": "t3-v3-23", "stem": "留学させてくれた両親に、（　）しています。", "options": ["成功", "要望", "救助", "感謝"], "answer": 4, "explanation_uz": "感謝 = minnatdorchilik", "tr": "Chet elda o'qishimga imkon bergan ota-onamga minnatdorman."}, {"id": "t3-v3-24", "stem": "いただいた本を（　）読もうと思います。", "options": ["やがて", "いきなり", "さっそく", "はっきり"], "answer": 3, "explanation_uz": "さっそく = darrov, zudlik bilan", "tr": "Bergan kitobingizni darrov o'qiyman deb o'ylayapman."}, {"id": "t3-v3-25", "stem": "散歩やジョギングなど、軽い運動は（　）によい。", "options": ["体重", "元気", "体温", "健康"], "answer": 4, "explanation_uz": "健康 = salomatlik", "tr": "Sayr va yugurish kabi yengil mashqlar salomatlikka foydali."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t3-v4-26", "stem": "彼の考え方は、いつも【ネガティブ】だ。", "options": ["まじめ", "ふまじめ", "肯定的", "否定的"], "answer": 4, "explanation_uz": "ネガティブ = 否定的 (salbiy)", "tr": "Uning fikrlash tarzi doim salbiy."}, {"id": "t3-v4-27", "stem": "2本のロープを【つないで】ください。", "options": ["関係して", "接続して", "注意して", "切断して"], "answer": 2, "explanation_uz": "つなぐ = 接続する (ulamoq)", "tr": "Ikki arqonni bir-biriga ulang."}, {"id": "t3-v4-28", "stem": "彼は、自分の言ったことを【打ち消した】。", "options": ["忘れた", "途中でやめた", "否定した", "そのままにした"], "answer": 3, "explanation_uz": "打ち消す = 否定する (inkor qilmoq)", "tr": "U aytgan gapini inkor qildi."}, {"id": "t3-v4-29", "stem": "【さっさと】仕事を終わらせた。", "options": ["早く", "ゆっくりと", "正確に", "だいたい"], "answer": 1, "explanation_uz": "さっさと = 早く (tez, darrov)", "tr": "Ishni tez (darrov) tugatdi."}, {"id": "t3-v4-30", "stem": "彼女は、いつも【落ち着いて】いる。", "options": ["優秀だ", "有能だ", "冷静だ", "温厚だ"], "answer": 3, "explanation_uz": "落ち着いている = 冷静だ (xotirjam)", "tr": "U doim xotirjam."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t3-v5-31", "stem": "気に入る", "options": ["明日のテストが気に入って、とても心配だ。", "その店の服がとても気に入ったので、買うことにした。", "どうも午後は、よい天気になるような気に入る。", "会社に着いてから、さいふがないことに気に入った。"], "answer": 2, "optsTr": ["Ertangi test 'yoqib', juda xavotirdaman (noto'g'ri).", "Do'kondagi kiyim juda yoqqani uchun, sotib olishga qaror qildim. (to'g'ri)", "Tushdan keyin ob-havo yaxshi bo'ladiganga 'yoqaman' (noto'g'ri).", "Ishxonaga yetib, hamyonim yo'qligi 'yoqdi' (noto'g'ri)."], "tr": "気に入る = yoqmoq, ma'qul kelmoq."}, {"id": "t3-v5-32", "stem": "まぜる", "options": ["花びんに花をまぜようと思います。", "このシャツにボタンをまぜていただけませんか。", "たまごと牛乳をよくまぜてください。", "顔をよくまぜてから、外に出かけましょう。"], "answer": 3, "optsTr": ["Guldonga gulni 'aralashtirmoqchiman' (noto'g'ri).", "Bu ko'ylakka tugmani 'aralashtirib' bera olasizmi (noto'g'ri).", "Tuxum va sutni yaxshilab aralashtiring. (to'g'ri)", "Yuzni yaxshilab 'aralashtirib', tashqariga chiqaylik (noto'g'ri)."], "tr": "まぜる = aralashtirmoq."}, {"id": "t3-v5-33", "stem": "現実", "options": ["私はものを考えるより現実が得意だ。", "まだ試験に受かったという現実がわかる。", "昔にくらべて、現実はきびしい時代だと思います。", "とても現実とは思えないニュースを聞いた。"], "answer": 4, "optsTr": ["Men o'ylashdan ko'ra 'reallik'ni yaxshi eplayman (noto'g'ri).", "Hali imtihondan o'tganlik 'realligi' bilinadi (noto'g'ri).", "Ilgariga nisbatan, 'reallik' qattiq davr deb o'ylayman (noto'g'ri).", "Aslo haqiqat deb bo'lmaydigan yangilik eshitdim. (to'g'ri)"], "tr": "現実 = haqiqat, reallik."}, {"id": "t3-v5-34", "stem": "おかず", "options": ["昼食と夕食のあいだのおかずに、ケーキを食べた。", "今日の晩ごはんのおかずは、肉と野菜の料理です。", "おかずを沸かしてお茶を飲みます。", "私の好きなおかずは、ごはんよりもパンです。"], "answer": 2, "optsTr": ["Tushlik va kechki ovqat orasidagi 'garnir'ga tort yedim (noto'g'ri).", "Bugungi kechki ovqat garniri — go'sht va sabzavot taomi. (to'g'ri)", "'Garnir'ni qaynatib choy ichaman (noto'g'ri).", "Yoqtirgan 'garnirim' — guruchdan ko'ra non (noto'g'ri)."], "tr": "おかず = garnir, ovqatga qo'shimcha taom."}, {"id": "t3-v5-35", "stem": "できあがる", "options": ["私の夢は、先生にできあがることです。", "エレベーターで10階までできあがってください。", "階段をできあがると、私の家があります。", "料理ができあがったので、食べてください。"], "answer": 4, "optsTr": ["Orzuyim — o'qituvchiga 'tayyor bo'lish' (noto'g'ri).", "Lift bilan 10-qavatgacha 'tayyor bo'ling' (noto'g'ri).", "Zinadan 'tayyor bo'lsang', mening uyim bor (noto'g'ri).", "Ovqat tayyor bo'ldi, shuning uchun yeng. (to'g'ri)"], "tr": "できあがる = tayyor bo'lmoq, bitmoq."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t3-g1-1", "stem": "夏から秋（　）、いろいろな祭りがひらかれる。", "options": ["をかけて", "にかけて", "でかけて", "とかけて"], "answer": 2, "explanation_uz": "〜から〜にかけて = ...dan ...gacha (davr oralig'i)", "tr": "Yozdan kuzgacha bo'lgan davrda turli bayramlar o'tkaziladi."}, {"id": "t3-g1-2", "stem": "森さんはこの会社にエンジニア（　）採用された。", "options": ["として", "といって", "だと", "だとして"], "answer": 1, "explanation_uz": "〜として = ...sifatida", "tr": "Mori-san bu kompaniyaga muhandis sifatida ishga olindi."}, {"id": "t3-g1-3", "stem": "山田さんはアメリカに住んでいた（　）、英語の発音がきれいですね。", "options": ["だけは", "だけに", "ところは", "ところに"], "answer": 2, "explanation_uz": "〜だけに = aynan ...gani uchun", "tr": "Yamada-san Amerikada yashagani uchun, ingliz talaffuzi chiroyli ekan."}, {"id": "t3-g1-4", "stem": "家を出た（　）、大雨が降ってきた。", "options": ["たびに", "とたん", "ごとに", "からには"], "answer": 2, "explanation_uz": "〜たとたん = ...ishi bilanoq", "tr": "Uydan chiqishim bilanoq, kuchli yomg'ir yog'a boshladi."}, {"id": "t3-g1-5", "stem": "最近、そうじをしていないので、部屋がごみ（　）だ。", "options": ["しか", "気味", "きり", "だらけ"], "answer": 4, "explanation_uz": "〜だらけ = ...ga to'la, ...ga botgan", "tr": "Yaqinda tozalamaganim uchun, xona axlatga to'la."}, {"id": "t3-g1-6", "stem": "彼はしっかりしているので、（　）ことはないでしょう。", "options": ["心配し", "心配しよう", "心配しろ", "心配する"], "answer": 4, "explanation_uz": "〜することはない = ...ga hojat yo'q", "tr": "U ishonchli odam, shuning uchun xavotir olishga hojat yo'q."}, {"id": "t3-g1-7", "stem": "ラーメンを作ったので、（　）食べてください。", "options": ["熱いうちで", "熱いうちへ", "熱いうちに", "熱いうちが"], "answer": 3, "explanation_uz": "〜うちに = ...turib, ...gacha (holat o'zgarmasdan)", "tr": "Ramen pishirdim, issig'ida yeng."}, {"id": "t3-g1-8", "stem": "これは、2、3日前に先生から（　）本です。", "options": ["お借りした", "借りてあげた", "借りてくださった", "お借りになった"], "answer": 1, "explanation_uz": "お〜する = kamtarlik shakli (men oldim)", "tr": "Bu 2-3 kun oldin o'qituvchidan olgan kitobim."}, {"id": "t3-g1-9", "stem": "あの人は、まるで本当の家族（　）かのように、私に優しかった。", "options": ["だ", "だろう", "である", "だったら"], "answer": 3, "explanation_uz": "〜であるかのように = xuddi ...dek", "tr": "U xuddi haqiqiy oilamdek menga mehribon edi."}, {"id": "t3-g1-10", "stem": "そこに置いてあるパンは、私の（　）です。", "options": ["食べきり", "食べかけ", "食べたまま", "食べたばかり"], "answer": 2, "explanation_uz": "〜かけ = yarim ...gan, boshlab qo'yilgan", "tr": "U yerdagi non — mening yarim yeб qo'yganim."}, {"id": "t3-g1-11", "stem": "ご病気が（　）を聞いて、安心しました。", "options": ["治ったということ", "治ったというもの", "治るというところ", "治るというほど"], "answer": 1, "explanation_uz": "〜ということ = ...ganligi (faktni bildiradi)", "tr": "Kasalingiz tuzalganini eshitib, xotirjam bo'ldim."}, {"id": "t3-g1-12", "stem": "きのうは、大雨が（　）、一日じゅう外でサッカーをしました。", "options": ["降っていたからといって", "降っていたからには", "降っていたにもかかわらず", "降っていたにしては"], "answer": 3, "explanation_uz": "〜にもかかわらず = ...ga qaramay", "tr": "Kecha kuchli yomg'ir yog'ayotgan bo'lsa-da, kun bo'yi tashqarida futbol o'ynadik."}, {"id": "t3-g1-13", "stem": "社長「みなさん、今は大変なときですが、社員一同、会社のために（　）。」社員「はい、がんばります。」", "options": ["がんばるのではないですか", "がんばったではありませんか", "がんばらないのではないですか", "がんばろうではありませんか"], "answer": 4, "explanation_uz": "〜ようではありませんか = kelinglar, ...aylik", "tr": "Direktor: «Hozir og'ir payt, lekin xodimlar birgalashib kompaniya uchun harakat qilaylik-a.»"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t3-g2-14", "options": ["いい", "もらっても", "帰らせて", "もう"], "answer": 2, "prefix": "女の学生「悪いけど、頭が痛いから、今日は", "suffix": "？」", "starPos": 3, "order": [4, 3, 2, 1], "explanation_uz": "To'g'ri tartib: もう帰らせてもらってもいい", "tr": "To'g'ri tartib: «Kechirasiz, boshim og'riyapti, bugun endi (meni) qaytishimga ruxsat bersangiz bo'ladimi?»"}, {"id": "t3-g2-15", "options": ["ので", "お願い", "まいります", "よろしく"], "answer": 1, "prefix": "少し遅れましたが、今から会場に", "suffix": "いたします。", "starPos": 2, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: まいりますのでよろしくお願い (いたします)", "tr": "To'g'ri tartib: «Biroz kechikdim; hozir zalga boraman, iltimos, yaxshi munosabatda bo'lishingizni so'rayman.»"}, {"id": "t3-g2-16", "options": ["とても", "しても", "たとえ", "難しいと"], "answer": 4, "prefix": "この仕事をするのが、", "suffix": "努力を続ければ、いつかきっとできるようになると信じている。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: たとえとても難しいとしても", "tr": "To'g'ri tartib: «Bu ishni qilish juda qiyin bo'lsa ham, harakatni davom ettirsam, qachondir albatta uddalay olaman deb ishonaman.»"}, {"id": "t3-g2-17", "options": ["ない", "あやまる", "ほか", "より"], "answer": 3, "prefix": "私のミスで、計画が失敗してしまったのだから、", "suffix": "と思い、すぐにメールを送った。", "starPos": 3, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: あやまるよりほかない", "tr": "To'g'ri tartib: «Mening xatoyim tufayli reja barbod bo'ldi, shuning uchun kechirim so'rashdan boshqa chora yo'q deb o'ylab, darrov xat yubordim.»"}, {"id": "t3-g2-18", "options": ["ひどい", "ちょっと", "対する", "態度は"], "answer": 4, "prefix": "まわりから見ても、彼の彼女に", "suffix": "と思う。", "starPos": 2, "order": [3, 4, 2, 1], "explanation_uz": "To'g'ri tartib: 対する態度はちょっとひどい", "tr": "To'g'ri tartib: «Chetdan qaraganda ham, uning qiziga bo'lgan munosabati biroz qo'pol deb o'ylayman.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "新マーク発表", "passage": "A市の青木市長は、チューリップの花をモチーフにした新しい市のマークを発表した。A市市役所の広報課{{19a}}、この新しいマークは青木市長からのメッセージを{{19b}}。マークのまんなかに、A市の花であるチューリップをデザインし、まわりの小さい模様は市民が楽しく生活している様子を表しているという。このマークは、市長が親しみやすさとあたたかさを{{20}}ものにしたいと考えて、もとになるアイデアを出し、A市に住むデザイナーに頼んで作った。\nA市は、今日から市のホームページ{{21}}、この新しいマークを公開する。また、近日中にこのマークをもとにしてキャラクターを作り、その名前を市民から広く募集する予定だ。\n日本では、各市町村にいろいろなキャラクターがいて、人気者になっている。とても{{22}}、ハンカチなどの商品になったり、テレビで取り上げられることもある。A市のキャラクターにも、たくさんの人に愛される名前を考えて{{23}}と、市長は語っている。", "passage_tr": "A shahar meri Aoki tulpan gulini asos qilib olgan shaharning yangi belgisini (logotipini) e'lon qildi. A shahar hokimligi matbuot bo'limiga ko'ra, bu yangi belgi mer Aokining xabarini ifodalab turarmish. Belgining markazida A shaharning guli — tulpan tasvirlangan, atrofdagi mayda naqshlar esa fuqarolarning xushchaqchaq hayotini aks ettiradi. Bu belgini mer yaqinlik va iliqlikni his ettiradigan qilmoqchi bo'lib, asos g'oyani taklif etgan va A shaharda yashovchi dizaynerga buyurtma berib yasatgan. A shahar bugundan shaharning veb-saytida bu yangi belgini ommaga taqdim etadi. Shuningdek, yaqin kunlarda shu belgi asosida personaj yaratib, uning nomini fuqarolardan keng so'rab olish rejalashtirilgan. Yaponiyada har bir shahar va qishloqda turli personajlar bo'lib, ular mashhur. Juda mashhur personajlar ro'molcha kabi mahsulotlarga aylanadi yoki televideniyada namoyish etiladi. A shahar personajiga ham ko'p odamlar sevadigan nom o'ylab qo'yishlarini istayman, deb mer aytmoqda.", "questions": [{"id": "t3-g3-19", "options": ["からして ／ 表すことだ", "にしろ ／ 表すものだ", "によると ／ 表しているそうだ", "にかかわらず ／ 表したわけだ"], "answer": 3, "blankNo": "19", "explanation_uz": "〜によると = ...ga ko'ra; 〜そうだ = ...mish (eshitilgan)", "tr": "[a によると]…[b 表しているそうだ] = ...ga ko'ra ... ifodalarmish."}, {"id": "t3-g3-20", "options": ["感じさせる", "感じようとする", "感じないでもない", "感じがちな"], "answer": 1, "blankNo": "20", "explanation_uz": "〜させる = his ettirmoq (orttirma nisbat)", "tr": "親しみやすさとあたたかさを[感じさせる]ものに = yaqinlik va iliqlikni his ettiradigan qilib."}, {"id": "t3-g3-21", "options": ["にともなって", "において", "につれて", "に対して"], "answer": 2, "blankNo": "21", "explanation_uz": "〜において = ...da (joy/soha)", "tr": "ホームページ[において]公開する = veb-saytda e'lon qiladi."}, {"id": "t3-g3-22", "options": ["市町村のキャラクター", "このマークのキャラクター", "新しいキャラクター", "人気があるキャラクター"], "answer": 4, "blankNo": "22", "explanation_uz": "kontekstga ko'ra: mashhur personajlar haqida", "tr": "とても[人気があるキャラクター]は商品になる = juda mashhur personaj mahsulotga aylanadi."}, {"id": "t3-g3-23", "options": ["つけられてほしい", "つけてもいい", "つけてみたい", "つけてほしい"], "answer": 4, "blankNo": "23", "explanation_uz": "〜てほしい = ...ishlarini istayman", "tr": "名前を考えて[つけてほしい] = nom o'ylab qo'yishlarini istayman."}]}]}]}, "4": {"id": 4, "title_jp": "第4回 模擬テスト", "title_uz": "4-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t4-v1-1", "stem": "荷物は、もう【届いて】います。", "options": ["あいて", "ほどいて", "ついて", "とどいて"], "answer": 4, "reading": "とどいて", "explanation_uz": "届く → とどく (yetib bormoq, kelmoq)", "tr": "Yuk allaqachon yetib keldi."}, {"id": "t4-v1-2", "stem": "【適度】な運動は、体によい。", "options": ["てきと", "てきとう", "てきど", "てきどう"], "answer": 3, "reading": "てきど", "explanation_uz": "適度 → てきど (me'yor, mo'tadillik)", "tr": "Me'yoridagi sport tanaga foydali."}, {"id": "t4-v1-3", "stem": "部長は今、大阪へ【出張】しています。", "options": ["しゅちょう", "しゅっちょう", "でちょう", "でっちょう"], "answer": 2, "reading": "しゅっちょう", "explanation_uz": "出張 → しゅっちょう (xizmat safari)", "tr": "Bo'lim boshlig'i hozir Osakaga xizmat safarida."}, {"id": "t4-v1-4", "stem": "両親が子どもたちを【養う】。", "options": ["さそう", "やしなう", "ととのう", "うたがう"], "answer": 2, "reading": "やしなう", "explanation_uz": "養う → やしなう (boqmoq, ta'minlamoq)", "tr": "Ota-ona bolalarini boqadi (ta'minlaydi)."}, {"id": "t4-v1-5", "stem": "【勇気】がなくて、好きな人に話しかけられない。", "options": ["よき", "ようき", "ゆき", "ゆうき"], "answer": 4, "reading": "ゆうき", "explanation_uz": "勇気 → ゆうき (jasorat)", "tr": "Jasoratim yo'q, yoqtirgan odamim bilan gaplasha olmayman."}, {"id": "t4-v1-6", "stem": "空港で日本円をユーロに【両替】した。", "options": ["りょかえ", "りょがえ", "りょうかえ", "りょうがえ"], "answer": 4, "reading": "りょうがえ", "explanation_uz": "両替 → りょうがえ (pul almashtirish)", "tr": "Aeroportda yenni yevroga almashtirdim."}, {"id": "t4-v1-7", "stem": "遠くに白い【煙】が見えます。", "options": ["くも", "きり", "けむり", "はい"], "answer": 3, "reading": "けむり", "explanation_uz": "煙 → けむり (tutun)", "tr": "Uzoqda oq tutun ko'rinadi."}, {"id": "t4-v1-8", "stem": "家の前で車が【停止】した。", "options": ["ていし", "てんし", "ていじ", "てんじ"], "answer": 1, "reading": "ていし", "explanation_uz": "停止 → ていし (to'xtash)", "tr": "Uy oldida mashina to'xtadi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t4-v2-9", "stem": "【ぜんりょく】で課題に取り組む。", "options": ["戦力", "全力", "前力", "総力"], "answer": 2, "explanation_uz": "ぜんりょく → 全力 (bor kuch)", "tr": "Bor kuchim bilan vazifaga kirishaman."}, {"id": "t4-v2-10", "stem": "【しゅうだん】で旅行する。", "options": ["衆団", "集団", "衆段", "集段"], "answer": 2, "explanation_uz": "しゅうだん → 集団 (guruh, jamoa)", "tr": "Guruh bo'lib sayohat qilamiz."}, {"id": "t4-v2-11", "stem": "あるテーマについて、全員で【ぎろん】した。", "options": ["異論", "討論", "理論", "議論"], "answer": 4, "explanation_uz": "ぎろん → 議論 (bahs, munozara)", "tr": "Bir mavzu bo'yicha hammamiz bahslashdik."}, {"id": "t4-v2-12", "stem": "ホストファミリーが私をあたたかく【むかえて】くれた。", "options": ["拝えて", "待えて", "迎えて", "歓えて"], "answer": 3, "explanation_uz": "むかえる → 迎える (kutib olmoq)", "tr": "Mezbon oila meni iliq kutib oldi."}, {"id": "t4-v2-13", "stem": "来週の授業の【よしゅう】をしてきてください。", "options": ["余習", "復習", "予習", "複習"], "answer": 3, "explanation_uz": "よしゅう → 予習 (oldindan tayyorgarlik)", "tr": "Keyingi hafta darsiga oldindan tayyorgarlik qiling."}, {"id": "t4-v2-14", "stem": "【てま】のかかる料理を作る。", "options": ["手間", "手真", "手麻", "手試"], "answer": 1, "explanation_uz": "てま → 手間 (ovora, mashaqqat, sarflanadigan vaqt)", "tr": "Mashaqqat (vaqt) talab qiladigan taom tayyorlayman."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t4-v3-15", "stem": "あの人の、研究者としての（　）は長い。", "options": ["アイテム", "タイム", "キャリア", "スケジュール"], "answer": 3, "explanation_uz": "キャリア = karyera, ish tajribasi", "tr": "U odamning tadqiqotchi sifatidagi tajribasi (karyerasi) uzoq."}, {"id": "t4-v3-16", "stem": "お金を（　）、入場する。", "options": ["買って", "与えて", "贈って", "払って"], "answer": 4, "explanation_uz": "払う = to'lamoq (pul)", "tr": "Pul to'lab, ichkariga kiraman."}, {"id": "t4-v3-17", "stem": "このショッピングセンターは、去年より客が（　）している。", "options": ["加入", "増加", "成立", "流行"], "answer": 2, "explanation_uz": "増加 = ko'payish, ortish", "tr": "Bu savdo markazida mijozlar o'tgan yilga nisbatan ko'paygan."}, {"id": "t4-v3-18", "stem": "1日中歩いたので、とても（　）います。", "options": ["くたびれて", "迷って", "なやんで", "病んで"], "answer": 1, "explanation_uz": "くたびれる = charchamoq, holdan toymoq", "tr": "Kun bo'yi yurganim uchun juda charchadim."}, {"id": "t4-v3-19", "stem": "私もあなたの意見に（　）です。", "options": ["同等", "平等", "賛成", "賛同"], "answer": 3, "explanation_uz": "賛成 = qo'shilish, ma'qullash", "tr": "Men ham sizning fikringizga qo'shilaman."}, {"id": "t4-v3-20", "stem": "彼は、去年この町に（　）来た。", "options": ["引っ越して", "引き出して", "乗り越して", "乗り出して"], "answer": 1, "explanation_uz": "引っ越す = ko'chib o'tmoq", "tr": "U o'tgan yili bu shaharga ko'chib keldi."}, {"id": "t4-v3-21", "stem": "このお店はとても（　）がいい。", "options": ["チャンス", "サービス", "ルール", "ショッピング"], "answer": 2, "explanation_uz": "サービス = xizmat ko'rsatish", "tr": "Bu do'konning xizmati juda yaxshi."}, {"id": "t4-v3-22", "stem": "人を（　）で判断してはいけません。", "options": ["見合い", "見回り", "見立て", "見かけ"], "answer": 4, "explanation_uz": "見かけ = tashqi ko'rinish", "tr": "Odamni tashqi ko'rinishiga qarab baholamaslik kerak."}, {"id": "t4-v3-23", "stem": "明日何時に集まるか、電話で友だちに（　）した。", "options": ["理解", "納得", "確認", "調査"], "answer": 3, "explanation_uz": "確認 = tasdiqlash, aniqlashtirish", "tr": "Ertaga nechada yig'ilishni telefonda do'stim bilan aniqlashtirdim."}, {"id": "t4-v3-24", "stem": "12月に入って、（　）クリスマスが来るのを思い出した。", "options": ["さっき", "さきに", "もうすぐ", "きっと"], "answer": 3, "explanation_uz": "もうすぐ = tez orada, hademay", "tr": "Dekabr kirib, tez orada Rojdestvo kelishini esladim."}, {"id": "t4-v3-25", "stem": "彼は、パンクした自転車を（　）に直してくれた。", "options": ["単調", "器用", "得意", "上等"], "answer": 2, "explanation_uz": "器用 = epchil, qo'li gul", "tr": "U teshilgan velosipedni epchillik bilan tuzatib berdi."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t4-v4-26", "stem": "私の妹は、とても【おとなしい】。", "options": ["おとなっぽい", "子どもっぽい", "うるさい", "静かだ"], "answer": 4, "explanation_uz": "おとなしい = yuvosh, bosiq → 静かだ (sokin)", "tr": "Singlim juda bosiq (yuvosh)."}, {"id": "t4-v4-27", "stem": "日曜日は、いつも家で【ごろごろ】しています。", "options": ["休んで", "仕事して", "運動して", "そうじして"], "answer": 1, "explanation_uz": "ごろごろする = bekorchi yotmoq → 休む (dam olmoq)", "tr": "Yakshanba kuni doim uyda bekorchi yotaman (dam olaman)."}, {"id": "t4-v4-28", "stem": "彼女は、【いいかげん】な性格だ。", "options": ["すばらしい", "だれにでも優しい", "適当な", "素直な"], "answer": 3, "explanation_uz": "いいかげん = beparvo, qovushmagan → 適当 (beparvo)", "tr": "Uning fe'l-atvori beparvo (loqayd)."}, {"id": "t4-v4-29", "stem": "新しい【職】を探しています。", "options": ["住むところ", "働くところ", "食べるところ", "学ぶところ"], "answer": 2, "explanation_uz": "職 = ish, kasb → 働くところ (ish joyi)", "tr": "Yangi ish qidiryapman."}, {"id": "t4-v4-30", "stem": "私たちは【もともとの】知り合いです。", "options": ["仲のよい", "あまり仲のよくない", "前からの", "最近出会った"], "answer": 3, "explanation_uz": "もともとの = aslidan, dastlabki → 前からの (oldindan)", "tr": "Biz aslidan (oldindan) tanish odamlarmiz."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t4-v5-31", "stem": "申し込む", "options": ["きっぷを買うために、機械にお金を申し込んだ。", "自分はいつも正しいと申し込むほうがよい。", "電話で会への参加を申し込んだ。", "机の上に置いてある本を本棚に申し込んでください。"], "answer": 3, "optsTr": ["Chipta olish uchun mashinaga pulni 'ariza qildim' (noto'g'ri).", "O'zimni doim haq deb 'ariza qilgan' ma'qul (noto'g'ri).", "Telefon orqali tadbirda qatnashishga yozildim (ariza berdim). (to'g'ri)", "Stol ustidagi kitobni javonga 'ariza qiling' (noto'g'ri)."], "tr": "申し込む = ariza bermoq, yozilmoq, murojaat qilmoq."}, {"id": "t4-v5-32", "stem": "植える", "options": ["かばんに本とノートを植えました。", "家の前に1本の桜の木を植えた。", "地面をもっと深く植えてください。", "来年、新しい家を植えようと思います。"], "answer": 2, "optsTr": ["Sumkaga kitob va daftarni 'ekdim' (noto'g'ri).", "Uy oldiga bitta sakura daraxti ekdim. (to'g'ri)", "Yerni yanada chuqurroq 'eking' (noto'g'ri).", "Kelasi yil yangi uy 'ekmoqchiman' (noto'g'ri)."], "tr": "植える = ekmoq (o'simlik)."}, {"id": "t4-v5-33", "stem": "ユニーク", "options": ["この商品はどこにでも売っているユニークなものだ。", "後の文章には、ユニークがたくさんある。", "明日は1日中仕事なので、とてもユニークだ。", "彼女の考え方は、とてもユニークでおもしろい。"], "answer": 4, "optsTr": ["Bu mahsulot hamma joyda sotiladigan 'noyob' narsa (noto'g'ri).", "Keyingi matnda 'noyob' ko'p bor (noto'g'ri).", "Ertaga kun bo'yi ish, shuning uchun juda 'noyob' (noto'g'ri).", "Uning fikrlash tarzi juda o'ziga xos va qiziqarli. (to'g'ri)"], "tr": "ユニーク = o'ziga xos, noyob."}, {"id": "t4-v5-34", "stem": "技術", "options": ["この会社には、すばらしい技術がある。", "重い病気になって、病院で技術をした。", "絵や音楽など、技術がとても好きだ。", "1日で家を建てるなんて、まるで技術のようだ。"], "answer": 1, "optsTr": ["Bu kompaniyada ajoyib texnologiya bor. (to'g'ri)", "Og'ir kasal bo'lib, kasalxonada 'texnika' qildim (noto'g'ri — 手術 jarrohlik kerak).", "Rasm va musiqa kabilarning 'texnikasi'ni juda yaxshi ko'raman (noto'g'ri).", "Bir kunda uy qurish — xuddi 'texnika'dek (noto'g'ri)."], "tr": "技術 = texnologiya, mahorat, texnika."}, {"id": "t4-v5-35", "stem": "つらい", "options": ["かわいい服より、つらい服のほうが好きです。", "親しい友だちと別れなければならないのは、つらい。", "この料理はとてもつらいので、水を持ってきてください。", "彼女から、つらい声で電話がかかってきた。"], "answer": 2, "optsTr": ["Chiroyli kiyimdan ko'ra 'alamli' kiyimni yaxshi ko'raman (noto'g'ri).", "Yaqin do'st bilan xayrlashishga majbur bo'lish — og'ir (alamli). (to'g'ri)", "Bu taom juda 'alamli', suv olib keling (noto'g'ri — 辛い achchiq kerak).", "Undan 'alamli' ovozda qo'ng'iroq keldi (noto'g'ri)."], "tr": "つらい = og'ir, alamli, mashaqqatli."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t4-g1-1", "stem": "このレポートを、明日の夜（　）書き終えるつもりだ。", "options": ["までで", "までは", "までの", "までに"], "answer": 4, "explanation_uz": "〜までに = ...gacha (oxirgi muddat, bir martalik ish)", "tr": "Bu hisobotni ertaga kechgacha yozib tugatmoqchiman."}, {"id": "t4-g1-2", "stem": "高校生の妹は、毎日遊んで（　）いる。", "options": ["より", "しか", "から", "ばかり"], "answer": 4, "explanation_uz": "〜てばかりいる = faqat ...ish bilan band", "tr": "O'rta maktabda o'qiydigan singlim har kuni faqat o'ynaydi."}, {"id": "t4-g1-3", "stem": "日本はほとんどの食料を輸入する（　）、毎日多くの食べ物が捨てられている。", "options": ["一方で", "一方なら", "だけで", "だけなら"], "answer": 1, "explanation_uz": "〜一方で = bir tomondan ...; bir vaqtning o'zida (qarama-qarshilik)", "tr": "Yaponiya oziq-ovqatining ko'pini import qiladi, shu bilan birga har kuni ko'p ovqat tashlab yuboriladi."}, {"id": "t4-g1-4", "stem": "朝から体の調子が（　）、今日は遊びに行けません。", "options": ["悪かったり", "悪くて", "悪いことと", "悪さで"], "answer": 2, "explanation_uz": "〜くて = sabab (te-shakli)", "tr": "Ertalabdan beri o'zimni yomon his qilyapman, shuning uchun bugun sayrga chiqolmayman."}, {"id": "t4-g1-5", "stem": "この子ねこは、見れば（　）かわいい。", "options": ["見ようほど", "見ないほど", "見るほど", "見たほど"], "answer": 3, "explanation_uz": "〜ば〜ほど = qancha ...sa, shuncha ...", "tr": "Bu mushukcha qancha qarasang, shuncha yoqimli."}, {"id": "t4-g1-6", "stem": "来年の試験を受けるなら、今から勉強を（　）ほうがいい。", "options": ["始めて", "始めた", "始めよう", "始め"], "answer": 2, "explanation_uz": "〜たほうがいい = ...gani ma'qul (maslahat)", "tr": "Kelasi yilgi imtihonni topshiradigan bo'lsang, hozirdan o'qishni boshlaganing ma'qul."}, {"id": "t4-g1-7", "stem": "この店の料理は、多すぎて（　）。", "options": ["食べきってない", "食べきらない", "食べきれない", "食べきりがない"], "answer": 3, "explanation_uz": "〜きれない = oxirigacha ...ib bo'lolmaslik", "tr": "Bu restoranning taomi shunchalik ko'pki, yeb tugatib bo'lmaydi."}, {"id": "t4-g1-8", "stem": "先生は、4時ごろに（　）。", "options": ["帰ってまいりました", "お帰りになりました", "帰っておりました", "お帰りいたしました"], "answer": 2, "explanation_uz": "お〜になる = hurmat shakli (o'qituvchining harakati). 1·3·4 = kamtarlik shakllari (noto'g'ri)", "tr": "O'qituvchi soat 4 larda uyiga qaytdilar."}, {"id": "t4-g1-9", "stem": "1週間で外国語を話せるようになるなんて（　）。", "options": ["あり得よう", "あり得ない", "あり得る", "あり得た"], "answer": 2, "explanation_uz": "あり得ない = bo'lishi mumkin emas, aql bovar qilmaydi", "tr": "Bir haftada chet tilida gapira oladigan bo'lib qolish — bo'lishi mumkin emas."}, {"id": "t4-g1-10", "stem": "佐藤「高尾山に行ったんでしょ。込んでいなかった？」鈴木「うーん、（　）人が少なくて、ゆっくり観光できたよ。」", "options": ["思っていたよりも", "思わなかったより", "思っていたほど", "思うほどには"], "answer": 1, "explanation_uz": "〜よりも = ...dan ko'ra (taqqoslash). 思っていたよりも = o'ylaganimdan ko'ra", "tr": "Sato: «Takao tog'iga borgansiz-a. Gavjum emasmidi?» Suzuki: «Hmm, o'ylaganimdan kamroq odam edi, shoshmasdan sayr qildim.»"}, {"id": "t4-g1-11", "stem": "部長「もう時間が遅いので、仕事を終わりにして（　）。」部下「はい、わかりました。」", "options": ["帰ることもいいですよ", "帰るだけですよ", "帰ってもいいですよ", "帰ったところですよ"], "answer": 3, "explanation_uz": "〜てもいい = ...sa bo'ladi (ruxsat)", "tr": "Boshliq: «Vaqt kech bo'ldi, ishni tugatib uyga ketsangiz ham bo'ladi.» Xodim: «Xo'p, tushundim.»"}, {"id": "t4-g1-12", "stem": "彼は毎日遊んでいる。このままでは次の試験に（　）。", "options": ["落ちないかもしれない", "落ちかねない", "落ちたかもしれない", "落ちようがない"], "answer": 2, "explanation_uz": "〜かねない = ...ib qo'yishi mumkin (yomon natija ehtimoli)", "tr": "U har kuni o'ynaydi. Shu zayilda davom etsa, keyingi imtihondan yiqilib qolishi mumkin."}, {"id": "t4-g1-13", "stem": "今日はとても暑いので、冷たいジュースが（　）。", "options": ["飲むことにならない", "飲んでもしょうがない", "飲まなくはない", "飲みたくてたまらない"], "answer": 4, "explanation_uz": "〜たくてたまらない = ...gisi kelib, chiday olmaslik", "tr": "Bugun juda issiq, shuning uchun sovuq sharbat ichgim kelib chidab bo'lmayapti."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t4-g2-14", "options": ["ため", "延期に", "来週に", "台風の"], "answer": 3, "prefix": "今日予定されていた運動会は、", "suffix": "なりました。", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: 台風のため来週に延期に (なりました)", "tr": "To'g'ri tartib: «Bugunga rejalashtirilgan sport bayrami tayfun tufayli keyingi haftaga qoldirildi.»"}, {"id": "t4-g2-15", "options": ["教えて", "そこに", "いいか", "行けば"], "answer": 4, "prefix": "中山「いつ", "suffix": "くれない？」", "starPos": 2, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: そこに行けばいいか教えて (くれない)", "tr": "To'g'ri tartib: «Qachon u yerga borsam bo'lishini aytib bera olmaysanmi?» — «Keyingi juma kuni kela olasanmi?»"}, {"id": "t4-g2-16", "options": ["さえ", "1冊の", "あれば", "本"], "answer": 1, "prefix": "もし、友だちが1人もいなくても、私は", "suffix": "幸せを感じることができます。", "starPos": 3, "order": [2, 4, 1, 3], "explanation_uz": "To'g'ri tartib: 1冊の本さえあれば", "tr": "To'g'ri tartib: «Agar do'stim umuman bo'lmasa ham, bittagina kitobim bo'lsa, men baxtni his qila olaman.»"}, {"id": "t4-g2-17", "options": ["最中に", "調べている", "ついて", "くわしく"], "answer": 2, "prefix": "刑事がその事件に", "suffix": "別の事件が起こった。", "starPos": 3, "order": [3, 4, 2, 1], "explanation_uz": "To'g'ri tartib: ついてくわしく調べている (最中に)", "tr": "To'g'ri tartib: «Detektiv o'sha ish yuzasidan batafsil tergov qilib turgan paytida boshqa hodisa yuz berdi.»"}, {"id": "t4-g2-18", "options": ["大きく", "ともなう", "ますます", "環境問題も"], "answer": 4, "prefix": "この町は、工業都市として大きく発展したが、それに", "suffix": "なっている。", "starPos": 2, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: ともなう環境問題もますます (大きく)", "tr": "To'g'ri tartib: «Bu shahar sanoat shahri sifatida juda rivojlandi, biroq shunga hamroh atrof-muhit muammolari ham tobora kattalashib bormoqda.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "「時間がない」", "passage": "私たちは、「時間がない」とよく言う。しかし、本当に「時間がない」のだろうか。本当は「時間がある」のにいそがしいふりをしたり、自分をいそがしい状態にしていることも{{19}}。\nたとえば、こんなことがあった。何日か前、私は仕事へ行くために電車に乗った。急いでいたので、携帯電話も音楽プレーヤーも本もすべて忘れてしまった。いつもは、電車に{{20}}イヤフォンを耳に押し込み、かばんから本や新聞を取り出して、読むことにしている。携帯電話や携帯ゲームプレーヤーでゲームを始めることもある。{{21}}この日は何も持たずに電車に乗ってしまったので、何もすることがなくなってしまった。\n仕方がないので、電車に乗っているあいだ、何もしないで前の席に座る人の動作や窓の外をずっと見ていた。そうしたら、とてもリラックスができたのだ。{{22}}、私たちには何もしない時間が必要なのかもしれない。私たちは、わざわざ{{23}}用事を作り、生活をいそがしくしてしまっているような気がする。本当に「時間がない」のか考えてみるだけで、もっと充実した時間を取りもどすことができるのではないだろうか。", "passage_tr": "Biz tez-tez «vaqt yo'q» deymiz. Lekin haqiqatan ham «vaqt yo'q»mi? Aslida «vaqt bor» bo'la turib, band bo'lganga olishimiz yoki o'zimizni band holatga solib qo'yishimiz ham bordir. Masalan, mana bunday voqea bo'lgan. Bir necha kun oldin ishga borish uchun poyezdga chiqdim. Shoshib qolganim uchun telefon ham, musiqa pleyeri ham, kitob ham — hammasini unutib qoldirdim. Odatda poyezdga chiqishim bilanoq quloqchinni qulog'imga tiqaman, sumkamdan kitob yoki gazeta olib o'qiyman. Telefon yoki o'yin pleyerida o'yin boshlab yuborishim ham bor. Biroq bu kuni hech narsasiz poyezdga chiqib qolganim uchun qiladigan ishim qolmadi. Iloji yo'qligidan, poyezdda ketayotganimda hech narsa qilmay, ro'paramda o'tirgan odamning harakatlarini va deraza ortini uzoq tikilib kuzatib o'tirdim. Shunda juda yengil tortdim (relaks bo'ldim). Bu narsa ko'rsatganidek, bizga hech narsa qilmaydigan vaqt ham kerakdir. Biz atayin, qilmasa ham bo'ladigan yumushlarni o'ylab topib, hayotimizni o'zimiz band qilib qo'yayotganga o'xshaymiz. Rostdan «vaqt yo'q»mi deb bir o'ylab ko'rishning o'ziyoq, yanada to'kis (mazmunli) vaqtni qaytarib olishimizga yordam berishi mumkin.", "questions": [{"id": "t4-g3-19", "options": ["ないのではないだろうか", "なくてもよいのだろうか", "あるのではないだろうか", "あってもよいのだろうか"], "answer": 3, "blankNo": "19", "explanation_uz": "〜のではないだろうか = ...emasmikan (yumshoq taxmin/xulosa)", "tr": "...していることも[あるのではないだろうか] = ...holatlar ham bordir, shunday emasmi?"}, {"id": "t4-g3-20", "options": ["乗ったすえに", "乗ったとたん", "乗れば乗るほど", "乗ったばかりに"], "answer": 2, "blankNo": "20", "explanation_uz": "〜たとたん = ...ishi bilanoq (darhol)", "tr": "電車に[乗ったとたん]イヤフォンを = poyezdga chiqishim bilanoq quloqchinni."}, {"id": "t4-g3-21", "options": ["たとえば", "または", "しかも", "ところが"], "answer": 4, "blankNo": "21", "explanation_uz": "ところが = biroq, lekin (kutilmagan qarama-qarshilik)", "tr": "[ところが]この日は何も持たずに = biroq bu kuni hech narsasiz."}, {"id": "t4-g3-22", "options": ["このことが示す通り", "このことからはわからないが", "このことが言うには", "このことでよければ"], "answer": 1, "blankNo": "22", "explanation_uz": "このことが示す通り = bu narsa ko'rsatganidek", "tr": "[このことが示す通り]、何もしない時間が必要 = bu narsa ko'rsatganidek, hech narsa qilmaydigan vaqt kerak."}, {"id": "t4-g3-23", "options": ["してもいい", "しなくてもいい", "したほうがいい", "すればいい"], "answer": 2, "blankNo": "23", "explanation_uz": "〜なくてもいい = ...masa ham bo'ladi", "tr": "わざわざ[しなくてもいい]用事を作り = atayin qilmasa ham bo'ladigan yumush o'ylab topib."}]}]}]}, "5": {"id": 5, "title_jp": "第5回 模擬テスト", "title_uz": "5-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t5-v1-1", "stem": "田中さんは、仕事の【経験】が豊富だ。", "options": ["けけん", "けいけん", "きけん", "きいけん"], "answer": 2, "reading": "けいけん", "explanation_uz": "経験 → けいけん (tajriba)", "tr": "Tanaka-sanning ish tajribasi boy."}, {"id": "t5-v1-2", "stem": "あの車は、【速度】が速い。", "options": ["そくど", "そくどう", "そぐど", "そぐどう"], "answer": 1, "reading": "そくど", "explanation_uz": "速度 → そくど (tezlik)", "tr": "Anavi mashinaning tezligi yuqori."}, {"id": "t5-v1-3", "stem": "先生にほめられて、【自信】がついた。", "options": ["ししん", "じしん", "しじん", "じじん"], "answer": 2, "reading": "じしん", "explanation_uz": "自信 → じしん (o'ziga ishonch)", "tr": "O'qituvchi maqtagach, o'zimga bo'lgan ishonchim ortdi."}, {"id": "t5-v1-4", "stem": "今から【重要な】お知らせをします。", "options": ["じゆような", "じゆうような", "じゅような", "じゅうような"], "answer": 4, "reading": "じゅうような", "explanation_uz": "重要な → じゅうような (muhim)", "tr": "Hozir muhim e'lonni aytaman."}, {"id": "t5-v1-5", "stem": "パソコンの電源を【切って】ください。", "options": ["きって", "けって", "はって", "とって"], "answer": 1, "reading": "きって", "explanation_uz": "切る → きる (o'chirmoq, kesmoq)", "tr": "Kompyuterning tokini o'chiring."}, {"id": "t5-v1-6", "stem": "この川の【浅い】ところで遊びましょう。", "options": ["うすい", "せまい", "ほそい", "あさい"], "answer": 4, "reading": "あさい", "explanation_uz": "浅い → あさい (sayoz)", "tr": "Bu daryoning sayoz joyida o'ynaylik."}, {"id": "t5-v1-7", "stem": "手のひらを【太陽】に向けてみる。", "options": ["たよう", "たいよう", "だよう", "だいよう"], "answer": 2, "reading": "たいよう", "explanation_uz": "太陽 → たいよう (quyosh)", "tr": "Kaftimni quyoshga qaratib ko'raman."}, {"id": "t5-v1-8", "stem": "家の前に、ごみが【散らかって】いる。", "options": ["かたづいて", "ちらかって", "ころがって", "ひろがって"], "answer": 2, "reading": "ちらかって", "explanation_uz": "散らかる → ちらかる (sochilib yotmoq)", "tr": "Uyning oldida axlat sochilib yotibdi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t5-v2-9", "stem": "彼は、【いだいな】政治家だ。", "options": ["違大", "遠大", "異大", "偉大"], "answer": 4, "explanation_uz": "いだい → 偉大 (buyuk)", "tr": "U buyuk siyosatchi."}, {"id": "t5-v2-10", "stem": "この機械を【そうさ】するのは、簡単だ。", "options": ["操件", "動件", "操作", "動作"], "answer": 3, "explanation_uz": "そうさ → 操作 (boshqaruv, operatsiya)", "tr": "Bu uskunani boshqarish oson."}, {"id": "t5-v2-11", "stem": "子どもにお菓子を【あたえた】。", "options": ["与えた", "授えた", "余えた", "貸えた"], "answer": 1, "explanation_uz": "あたえる → 与える (bermoq, in'om etmoq)", "tr": "Bolaga shirinlik berdim."}, {"id": "t5-v2-12", "stem": "道を左に【まがる】。", "options": ["反がる", "折がる", "分がる", "曲がる"], "answer": 4, "explanation_uz": "まがる → 曲がる (burilmoq)", "tr": "Yo'ldan chapga burilaman."}, {"id": "t5-v2-13", "stem": "彼は、筋肉が【はったつ】している。", "options": ["配達", "発達", "伝達", "到達"], "answer": 2, "explanation_uz": "はったつ → 発達 (rivojlanish, taraqqiyot)", "tr": "Uning muskullari rivojlangan."}, {"id": "t5-v2-14", "stem": "私の趣味は、【とざん】です。", "options": ["徒山", "踏山", "登山", "道山"], "answer": 3, "explanation_uz": "とざん → 登山 (toqqa chiqish)", "tr": "Mening xobbiyim — toqqa chiqish."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t5-v3-15", "stem": "明日歩く（　）を地図で調べておいた。", "options": ["ゴール", "コース", "センター", "シーン"], "answer": 2, "explanation_uz": "コース = marshrut, yo'nalish", "tr": "Ertaga yuradigan yo'nalishimizni xaritada tekshirib qo'ydim."}, {"id": "t5-v3-16", "stem": "彼は（　）車をほしがっているけれど、買うお金はないようだ。", "options": ["単に", "次第に", "しきりに", "ついに"], "answer": 3, "explanation_uz": "しきりに = tez-tez, qayta-qayta", "tr": "U tez-tez mashina xohlayotganini aytadi-yu, lekin sotib olishga puli yo'q ko'rinadi."}, {"id": "t5-v3-17", "stem": "あの人はまったくお金を使わない（　）な人だ。", "options": ["十分", "多大", "あいまい", "けち"], "answer": 4, "explanation_uz": "けち = xasis, ziqna", "tr": "U umuman pul ishlatmaydigan xasis odam."}, {"id": "t5-v3-18", "stem": "やっと大雨が（　）が、あちこちで被害があった。", "options": ["やんだ", "とめた", "すんだ", "やめた"], "answer": 1, "explanation_uz": "やむ = (yomg'ir, qor) tinmoq", "tr": "Nihoyat jala tindi, lekin turli joylarda talafotlar bo'ldi."}, {"id": "t5-v3-19", "stem": "毎日、（　）の公園へ散歩に出かけます。", "options": ["接近", "存在", "近所", "所在"], "answer": 3, "explanation_uz": "近所 = atrofdagi, mahalladagi", "tr": "Har kuni mahalladagi parkka sayrga chiqaman."}, {"id": "t5-v3-20", "stem": "私の誕生日をみんなで（　）くれて、うれしかった。", "options": ["祝って", "泣いて", "望んで", "願って"], "answer": 1, "explanation_uz": "祝う (いわう) = nishonlamoq, tabriklamoq", "tr": "Tug'ilgan kunimni hammamiz birga nishonlaganimizdan xursand bo'ldim."}, {"id": "t5-v3-21", "stem": "そのニュースを知って、大きな（　）を受けた。", "options": ["アドバイス", "ショック", "ファックス", "メッセージ"], "answer": 2, "explanation_uz": "ショック = shok, zarba", "tr": "O'sha yangilikni eshitib, qattiq shokka tushdim."}, {"id": "t5-v3-22", "stem": "私がその人に会ったのは、5年前に1度（　）です。", "options": ["まま", "ぱなし", "きり", "ごと"], "answer": 3, "explanation_uz": "〜きり = faqatgina ... marta xolos", "tr": "U odam bilan 5 yil oldin bir marta uchrashganman xolos."}, {"id": "t5-v3-23", "stem": "この工場では、食品を（　）している。", "options": ["創造", "創作", "製造", "製作"], "answer": 3, "explanation_uz": "製造 (せいぞう) = ishlab chiqarish", "tr": "Bu zavodda oziq-ovqat mahsulotlari ishlab chiqariladi."}, {"id": "t5-v3-24", "stem": "お父さまに、（　）お体をお大事に、と伝えてください。", "options": ["いまでも", "くれぐれも", "実に", "常に"], "answer": 2, "explanation_uz": "くれぐれも = chin dildan, qayta-qayta (iltimos, ehtiyot bo'ling ma'nosida)", "tr": "Otangizga o'zlarini juda asrashlarini aytib qo'ying."}, {"id": "t5-v3-25", "stem": "ひどいことを言われて、彼女が怒るのも（　）はない。", "options": ["無実", "無視", "無限", "無理"], "answer": 4, "explanation_uz": "無理はない = o'rinli, asabbuzarlikka haqiqiy sabab bor", "tr": "Bunday yomon gaplarni eshitib, uning g'azablanishi o'rinli (g'azablanmasligining iloji yo'q)."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t5-v4-26", "stem": "あの子どもは、水泳が【うまい】。", "options": ["好きだ", "きらいだ", "上手だ", "下手だ"], "answer": 3, "explanation_uz": "うまい = 上手だ (usta, yaxshi uddalaydi)", "tr": "Anavi bola suzishga usta."}, {"id": "t5-v4-27", "stem": "両親は、今、【留守にして】います。", "options": ["退職して", "失業して", "離婚して", "外出して"], "answer": 4, "explanation_uz": "留守にする = 外出する (uyda bo'lmaslik, tashqariga chiqmoq)", "tr": "Ota-onam hozir uyda yo'q (tashqariga chiqib ketishgan)."}, {"id": "t5-v4-28", "stem": "お皿を【さげて】ください。", "options": ["持って来て", "持って行って", "洗って", "ふいて"], "answer": 2, "explanation_uz": "さげる = 持って行く (olib ketmoq, stoldan yig'ishtirmoq)", "tr": "Likopchalarni olib keting (yig'ishtiring)."}, {"id": "t5-v4-29", "stem": "私の父は【温厚だ】。", "options": ["陽気だ", "体温が高い", "おだやかだ", "太っている"], "answer": 3, "explanation_uz": "温厚だ = おだやかだ (muloyim, xotirjam tabiatli)", "tr": "Otam muloyim (bosiq) odam."}, {"id": "t5-v4-30", "stem": "彼の話し方はいつも【皮肉だ】。", "options": ["意地が悪い", "役に立つ", "わけがわからない", "とても優しい"], "answer": 1, "explanation_uz": "皮肉だ = 意地が悪い (kinoyali, g'arazli)", "tr": "Uning gapirish tarzi doim kinoyali."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t5-v5-31", "stem": "集中", "options": ["私はきれいな外国の切手を集中している。", "お店が駅から遠いので、お客が集中しない。", "飲み会に参加する人を集中しましょう。", "テレビを消して、勉強に集中する。"], "answer": 4, "optsTr": ["Men chiroyli chet el markalarini 'diqqat qilyapman' (noto'g'ri, 'to'playapman' bo'lishi kerak).", "Do'kon stansiyadan uzoq, shuning uchun mijozlar 'jamlanmaydi' (noto'g'ri).", "Ziyofat ishtirokchilarini 'diqqat qilaylik' (noto'g'ri).", "Televizorni o'chirib, o'qishga diqqatimni jamlayman. (to'g'ri)"], "tr": "集中 (しゅうちゅう) = diqqatni jamlash, to'plash."}, {"id": "t5-v5-32", "stem": "あきる", "options": ["日本にあきたので、どんな場所でも1人で行けます。", "毎日この店のラーメンを食べたので、もうあきた。", "ドアをあきて、ベランダへ出ました。", "テニスにあきたので、プロのテニス選手を目指すことにした。"], "answer": 2, "optsTr": ["Yaponiyaga 'jonim tekkani' uchun, har qayerga yolg'iz bora olaman (noto'g'ri).", "Har kuni bu do'konning ramenini yeganim uchun, endi jonimga tegdi. (to'g'ri)", "Eshikni 'joniga tegib', balkonga chiqdim (noto'g'ri).", "Tennis 'jonimga tekkani' uchun, professional o'yinchi bo'lishga qaror qildim (noto'g'ri)."], "tr": "あきる (飽きる) = joniga tegmoq, me'daga tegmoq."}, {"id": "t5-v5-33", "stem": "付き合い", "options": ["雨が降ってきたので、駅まで付き合いに来てください。", "この魚の料理は、ごはんといい付き合いだ。", "私と彼の付き合いは、長い。", "田口さんと山川さんは仲が悪いので、ときどき付き合いをする。"], "answer": 3, "optsTr": ["Yomg'ir yog'ayotgani uchun stansiyagacha 'munosabat'ga keling (noto'g'ri).", "Bu baliq taomi guruch bilan yaxshi 'munosabat'da (noto'g'ri).", "U bilan munosabatlarimiz (tanishligimiz) uzoq muddatli. (to'g'ri)", "Taguchi va Yamakavaning munosabati yomon, shuning uchun ba'zan 'aloqa qilishadi' (noto'g'ri)."], "tr": "付き合い (つきあい) = munosabat, aloqa, tanishlik."}, {"id": "t5-v5-34", "stem": "じゃま", "options": ["あの人は性格がじゃまなので、みんなにきらわれている。", "道に大きな石があってじゃまだ。", "1週間そうじをしなかったら、部屋がとてもじゃまになった。", "この本は、内容がとてもじゃまで、理解できない。"], "answer": 2, "optsTr": ["Uning xarakteri 'to'siq' bo'lgani uchun hamma yomon ko'radi (noto'g'ri).", "Yo'lda katta tosh yotibdi, u juda xalaqit beryapti. (to'g'ri)", "1 hafta tozalamasam, xona juda 'xalaqit' bo'lib ketdi (noto'g'ri).", "Bu kitobning mazmuni juda 'to'siq' shuning uchun tushuna olmayapman (noto'g'ri)."], "tr": "じゃま (邪魔) = xalaqit, to'siq."}, {"id": "t5-v5-35", "stem": "寄る", "options": ["私の娘は、私の両親にとても寄っている。", "1週間前に寄った荷物が、まだ着きません。", "寄った食事をしていると、体によくないですよ。", "会社に行く前に、私の家に寄ってください。"], "answer": 4, "optsTr": ["Qizim ota-onamga juda 'kirib o'tmoqda' (noto'g'ri).", "1 hafta oldin 'kirib o'tgan' yuk hamon kelmadi (noto'g'ri).", "'Kirib o'tgan' ovqat yesangiz, sog'liqqa zarar (noto'g'ri).", "Ishga borishdan oldin, mening uyimga kirib o'ting. (to'g'ri)"], "tr": "寄る (よる) = yo'l-yo'lakay kirib o'tmoq."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t5-g1-1", "stem": "吉田「あなたも一緒に食事に行く（　）。」山本「うん、行くよ。」", "options": ["わ", "の", "し", "のに"], "answer": 2, "explanation_uz": "〜の？ = ...mi? (ko'proq og'zaki tilda savol berish)", "tr": "Yoshida: «Siz ham birga ovqatlanishga borasizmi?» Yamamoto: «Ha, boraman.»"}, {"id": "t5-g1-2", "stem": "自分でやると決めた（　）、何が何でもやり抜くぞ。", "options": ["以上", "以上の", "以上から", "以上も"], "answer": 1, "explanation_uz": "〜以上 = ...ekan, ...gandan keyin albatta", "tr": "O'zim qilaman deb qaror qilgan ekanman, nima bo'lsa ham oxiriga yetkazaman."}, {"id": "t5-g1-3", "stem": "50個（　）セール品はなくなりますので、お早めに。", "options": ["あいだに", "しか", "限りで", "まで"], "answer": 3, "explanation_uz": "〜限りで = shu bilan tugaydi, shu chegaragacha", "tr": "50 dona sotilgandan so'ng chegirmadagi mahsulotlar tugaydi, shuning uchun tezroq oling."}, {"id": "t5-g1-4", "stem": "林さんがなくなったなんて、まさか（　）はずはない。", "options": ["そんな", "どんな", "この", "あの"], "answer": 1, "explanation_uz": "そんなはずはない = aslo bunday bo'lishi mumkin emas", "tr": "Hayashi-san vafot etdi degani, aslo bunday bo'lishi mumkin emas."}, {"id": "t5-g1-5", "stem": "明日のハイキングが行われるかどうかは、天気（　）。", "options": ["限りだ", "次第だ", "ばかりだ", "通りだ"], "answer": 2, "explanation_uz": "〜次第だ = ...ga bog'liq", "tr": "Ertangi xiking bo'lish-bo'lmasligi ob-havoga bog'liq."}, {"id": "t5-g1-6", "stem": "うれしい（　）、みんなから結婚のお祝いをもらった。", "options": ["ものに", "ことに", "ほどに", "わけに"], "answer": 2, "explanation_uz": "〜ことに = shunday (quvonchli) narsaki, ...", "tr": "Qanday quvonchliyki, hammadan to'y sovg'asini oldim."}, {"id": "t5-g1-7", "stem": "参加したい人は、男女に関係なくだれでも参加して（　）。", "options": ["できます", "できません", "かまいます", "かまいません"], "answer": 4, "explanation_uz": "〜てかまいません = ...sa hechqisi yo'q, ...sa bo'ladi", "tr": "Qatnashishni xohlovchilar jinsidan qat'iy nazar hammalari qatnashaverishsa bo'ladi."}, {"id": "t5-g1-8", "stem": "試験は明日なのだから、今から（　）ようがない。もうあきらめた。", "options": ["準備", "準備する", "準備して", "準備し"], "answer": 4, "explanation_uz": "〜ようがない = ...ishning umuman imkoni yo'q (fe'lning o'zagi qo'shiladi: 準備する -> 準備し)", "tr": "Imtihon ertaga, shuning uchun hozirdan tayyorgarlik ko'rishning imkoni yo'q. Allaqachon taslim bo'ldim."}, {"id": "t5-g1-9", "stem": "たとえこの先（　）、私たちはずっと友だちだ。", "options": ["会えなくなったとしても", "会ったとしても", "会うまいとしたら", "会えるとしたら"], "answer": 1, "explanation_uz": "たとえ〜としても = mobodo ...sa ham", "tr": "Mobodo bundan keyin ko'risha olmasak ham, biz doim do'stmiz."}, {"id": "t5-g1-10", "stem": "鈴木「森先生が学校をやめるんだって。」川村「ちっとも（　）よ。」", "options": ["知っていた", "知らなかった", "知ればよかった", "知らないはずだ"], "answer": 2, "explanation_uz": "ちっとも〜ない = umuman ...yo'q", "tr": "Suzuki: «Mori ustoz maktabdan ketarmish.» Kawamura: «Zarracha ham bilmagandim.»"}, {"id": "t5-g1-11", "stem": "社長は、あの新聞記事をもう（　）。", "options": ["読ませていただきましたか", "お読みいたしましたか", "読んでまいりましたか", "お読みになりましたか"], "answer": 4, "explanation_uz": "お〜になる = hurmat shakli (boshqa shaxsga nisbatan)", "tr": "Hurmatli direktor, u gazeta maqolasini o'qib chiqdingizmi?"}, {"id": "t5-g1-12", "stem": "この国の将来が（　）。", "options": ["楽しんでできます", "楽しみでできません", "楽しみでなります", "楽しみでなりません"], "answer": 4, "explanation_uz": "〜てならない = juda, g'oyatda (his-tuyg'ular jilovlab bo'lmaydigan darajada)", "tr": "Bu mamlakatning kelajagini juda intizorlik bilan kutyapman (kuta olmayapman darajasida)."}, {"id": "t5-g1-13", "stem": "このまま木村さんが（　）、木村さんの意見は聞かないことにします。", "options": ["来たそうなら", "来そうなら", "来ないようなら", "来るようなら"], "answer": 3, "explanation_uz": "〜ようなら = agar ...dek holat bo'lsa", "tr": "Agar Kimura-san kelmaydigan bo'lsa, uning fikrini eshitmaslikka qaror qilamiz."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t5-g2-14", "options": ["教えて", "おかげで", "親切に", "くださった"], "answer": 4, "prefix": "入社してから、課長が", "suffix": "、ほかの社員より早く仕事を覚えることができました。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: 親切に 教えて くださった おかげで", "tr": "To'g'ri tartib: «Ishga kirganimdan so'ng, bo'lim boshlig'i mehribonlik bilan o'rgatganlari sharofati bilan boshqa xodimlardan tezroq ishni o'rganib oldim.»"}, {"id": "t5-g2-15", "options": ["言って", "言っていた", "もう一度", "ことを"], "answer": 3, "prefix": "悪いけど、さっき", "suffix": "くれる。", "starPos": 3, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: 言っていた ことを もう一度 言って", "tr": "To'g'ri tartib: «Kechirasiz-u, boya aytgan narsangizni yana bir marta qaytara olasizmi.»"}, {"id": "t5-g2-16", "options": ["きれいで", "よければ", "最高だ", "見た目も"], "answer": 1, "prefix": "この店の料理は、味も", "suffix": "と思います。", "starPos": 3, "order": [2, 4, 1, 3], "explanation_uz": "To'g'ri tartib: よければ 見た目も きれいで 最高だ", "tr": "To'g'ri tartib: «Bu restoranning taomlari ta'mi ham yaxshi, ko'rinishi ham chiroyli va eng zo'ridir deb o'ylayman.»"}, {"id": "t5-g2-17", "options": ["ぽろぽろ", "とたん", "見た", "一目"], "answer": 2, "prefix": "長い旅から帰って、両親の顔を", "suffix": "涙がこぼれてきた。", "starPos": 3, "order": [4, 3, 2, 1], "explanation_uz": "To'g'ri tartib: 一目 見た とたん ぽろぽろ", "tr": "To'g'ri tartib: «Uzoq safardan qaytib, ota-onamning yuzini bir ko'rishim bilanoq ko'zlarimdan duv-duv yosh to'kildi.»"}, {"id": "t5-g2-18", "options": ["講演が", "予定", "林先生による", "行われる"], "answer": 4, "prefix": "明日の午前10時から、大学のホールで、", "suffix": "です。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: 林先生による 講演が 行われる 予定", "tr": "To'g'ri tartib: «Ertaga ertalab soat 10 da universitet zali, Hayashi-sensei tomonidan leksiya o'tkazilishi rejalashtirilgan.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "新聞の保存のしかた", "passage": "私は、いろいろな情報を得るため、日本語の新聞{{19}}、英字新聞も読むようにして\nいます。これは、もう10年続けている習慣です。このことにより、情報を得るだけでなく、\n英語の勉強にもなっています。長い間読んできた{{20}}、最近では最初のページから\nざっと目を通すだけで、おおよその内容を理解できるようになりました。\n\nところが問題が1つあります。それは、増えていく新聞を、どうやってわかりやすく整\n理して保存するかということです。毎週英字新聞を買うので、重ねてそのままにしておけば、\nもし古い新聞をもう一度読みたくなったときに、どこにあるかわからなくなってしまいます。\n\n新聞を読むのが大好きな私にとって、古い新聞を捨てるということは{{21}}。その\nためいろいろやってみて、最近{{22}}この問題を解決する方法を見つけました。それは、\n年と月で新聞をわけて箱に入れて保存しておくというやり方です。簡単な方法ですが、結\n局これがもっとも効率のよい保存方法で、すぐに新聞を取り出せるようになりました。\n{{23}}ことには、わくわくするような楽しさがあるのです。", "passage_tr": "Men turli ma'lumotlarni olish uchun faqat yapon gazetasini emas, inglizcha gazetani ham o'qishga harakat qilyapman. Bu allaqachon 10 yildan beri davom etib kelayotgan odatdir. Bu orqali nafaqat ma'lumot olaman, balki ingliz tilini ham o'rganyapman. Uzoq vaqt davomida o'qib kelganim sharofati bilan, oxirgi paytlarda faqat birinchi sahifasiga ko'z yugurtirishning o'zi bilan mazmunni tushuna oladigan bo'ldim.\n\nBiroq bitta muammo bor. U ham bo'lsa, ko'payib borayotgan gazetalarni qanday qilib tushunarli tarzda tartibga solib saqlashdir. Har hafta inglizcha gazeta olaman, shuning uchun ularni ustma-ust taxlab qo'ysam, mobodo eski gazetani yana bir marta o'qigim kelganda, uning qayerdaligini bilmay qolaman.\n\nGazeta o'qishni yaxshi ko'radigan men uchun, eski gazetalarni tashlab yuborish degan narsani aslo o'ylab ham bo'lmaydi. Shuning uchun turli usullarni sinab ko'rib, yaqinda nihoyat bu muammoni hal qilish yo'lini topdim. U yil va oy bo'yicha gazetalarni ajratib, qutiga solib saqlash usulidir. Garchi oddiy usul bo'lsa-da, oxir-oqibat bu eng samarali saqlash usuli bo'ldi va darrov gazetani olib chiqa oladigan bo'ldim. O'tmishdagi gazetalarni ko'rishda o'zgacha hayajonli zavq bor-da.", "questions": [{"id": "t5-g3-19", "options": ["に限り", "に限らず", "からして", "からすると"], "answer": 2, "blankNo": "19", "explanation_uz": "〜に限らず = faqat ...emas, balki ...ham", "tr": "日本語の新聞[に限らず] = faqat yapon gazetasigina emas."}, {"id": "t5-g3-20", "options": ["a からには / b 理解しようと思います", "a ばかりに / b 理解できなくなりました", "a おかげで / b 理解できるようになりました", "a せいで / b 理解することができます"], "answer": 3, "blankNo": "20", "explanation_uz": "〜おかげで = ...sharofati bilan; 〜ようになる = ...adigan holatga kelmoq", "tr": "読んできた[おかげで]、おおよその内容を[理解できるようになりました] = O'qiganim sharofati bilan, taxminiy mazmunni tushuna oladigan bo'ldim."}, {"id": "t5-g3-21", "options": ["考えません", "考えさせません", "考えられません", "考えさせられません"], "answer": 3, "blankNo": "21", "explanation_uz": "考えられる = o'ylash mumkin (potensial), 考えられない = o'ylab/tasavvur qilib bo'lmaydi", "tr": "捨てるということは[考えられません] = tashlab yuborishni hatto o'ylab (tasavvur qilib) ham bo'lmaydi."}, {"id": "t5-g3-22", "options": ["だんだん", "ますます", "なかなか", "とうとう"], "answer": 4, "blankNo": "22", "explanation_uz": "とうとう = nihoyat, oxir-oqibat", "tr": "いろいろやってみて、最近[とうとう]見つけました = Turli xil narsalarni sinab, oxiri (nihoyat) topdim."}, {"id": "t5-g3-23", "options": ["現在の新聞を見る", "過去の新聞を見る", "現在の新聞を保存する", "過去の新聞を保存する"], "answer": 2, "blankNo": "23", "explanation_uz": "Kontekst bo'yicha: eski (o'tmishdagi) gazetalarni qayta o'qish/ko'rish zavqi haqida gap ketyapti.", "tr": "古い新聞をもう一度読みたくなった (Eski gazetani yana o'qigim kelganda) -> [過去の新聞を見る]ことには...楽しさがあるのです (O'tmishdagi gazetalarni ko'rishda...)."}]}]}]}, "6": {"id": 6, "title_jp": "第6回 模擬テスト", "title_uz": "6-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t6-v1-1", "stem": "箱が【壊れ】ました。", "options": ["われ", "おれ", "こわれ", "はなれ"], "answer": 3, "reading": "こわれ", "explanation_uz": "壊れる → こわれる (sinmoq, buzilmoq)", "tr": "Quti singan."}, {"id": "t6-v1-2", "stem": "【各地】で雨が降り始めました。", "options": ["かくじ", "かくち", "きゃくじ", "きゃくち"], "answer": 2, "reading": "かくち", "explanation_uz": "各地 → かくち (har joy, turli joylar)", "tr": "Har joyda yomg'ir yog'a boshladi."}, {"id": "t6-v1-3", "stem": "あの店の【主人】は働き者だ。", "options": ["しゅにん", "じゅにん", "しゅじん", "じゅじん"], "answer": 3, "reading": "しゅじん", "explanation_uz": "主人 → しゅじん (xo'jayin, eg)", "tr": "U do'konning egasi mehnatkash."}, {"id": "t6-v1-4", "stem": "このシャツは、もう【洗って】あります。", "options": ["きって", "さわって", "ぬって", "あらって"], "answer": 4, "reading": "あらって", "explanation_uz": "洗う → あらう (yuvmoq)", "tr": "Bu ko'ylak allaqachon yuvilgan."}, {"id": "t6-v1-5", "stem": "アパートは通学に【不便】なところにある。", "options": ["ふべん", "ふだん", "ふまん", "ふしん"], "answer": 1, "reading": "ふべん", "explanation_uz": "不便 → ふべん (noqulay)", "tr": "Kvartira o'qishga borish uchun noqulay joyda."}, {"id": "t6-v1-6", "stem": "久しぶりに【仲間】が集まった。", "options": ["ながま", "なかま", "ちゅうかん", "ちゅうげん"], "answer": 2, "reading": "なかま", "explanation_uz": "仲間 → なかま (sherik, do'st, hamroh)", "tr": "Ancha vaqtdan keyin do'stlar (sheriklar) yig'ildi."}, {"id": "t6-v1-7", "stem": "あの人は、【肌】がきれいだ。", "options": ["ゆび", "ひふ", "はだ", "つめ"], "answer": 3, "reading": "はだ", "explanation_uz": "肌 → はだ (teri)", "tr": "U odamning terisi toza (chiroyli)."}, {"id": "t6-v1-8", "stem": "書類を【郵送】しておきました。", "options": ["はっそう", "はいそう", "ゆそう", "ゆうそう"], "answer": 4, "reading": "ゆうそう", "explanation_uz": "郵送 → ゆうそう (pochta orqali jo'natish)", "tr": "Hujjatlarni pochta orqali jo'natib qo'ydim."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t6-v2-9", "stem": "【ふせいな】取引を禁じる。", "options": ["不生", "不性", "不正", "不成"], "answer": 3, "explanation_uz": "ふせい → 不正 (nohaqlik, g'irromlik)", "tr": "G'irrom (nohaq) savdoni taqiqlash."}, {"id": "t6-v2-10", "stem": "長い【きゅうか】を取る。", "options": ["休憩", "休息", "休養", "休暇"], "answer": 4, "explanation_uz": "きゅうか → 休暇 (ta'til)", "tr": "Uzoq ta'til olaman."}, {"id": "t6-v2-11", "stem": "親に【たのんで】、車を買ってもらった。", "options": ["頼んで", "願んで", "望んで", "希んで"], "answer": 1, "explanation_uz": "たのむ → 頼む (iltimos qilmoq)", "tr": "Ota-onamdan iltimos qilib, menga mashina sotib oldirdim."}, {"id": "t6-v2-12", "stem": "生活で【こまる】ことは何ですか。", "options": ["苦る", "迷る", "因る", "困る"], "answer": 4, "explanation_uz": "こまる → 困る (qiynalmoq, mushkul ahvolga tushmoq)", "tr": "Hayotda qiynaladigan narsangiz nima?"}, {"id": "t6-v2-13", "stem": "ホテルに【とまる】ことにした。", "options": ["止まる", "留まる", "停まる", "泊まる"], "answer": 4, "explanation_uz": "とまる → 泊まる (tunamoq, qo'nmoq)", "tr": "Mehmonxonada tunashga qaror qildim."}, {"id": "t6-v2-14", "stem": "敵と【みかた】にわかれて争う。", "options": ["見方", "味方", "見形", "味形"], "answer": 2, "explanation_uz": "みかた → 味方 (tarafdor, o'z tomon)", "tr": "Dushman va tarafdorlarga bo'linib kurashamiz."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t6-v3-15", "stem": "音楽なら、（　）は関係なく、何でも聞きます。", "options": ["ケース", "クラス", "ステージ", "ジャンル"], "answer": 4, "explanation_uz": "ジャンル = janr, tur", "tr": "Musiqa bo'lsa, janridan qat'i nazar, hamma narsani tinglayman."}, {"id": "t6-v3-16", "stem": "明日は、先生を（　）するつもりです。", "options": ["質問", "訪問", "問答", "返答"], "answer": 2, "explanation_uz": "訪問 = tashrif, ziyorat", "tr": "Ertaga o'qituvchimni ziyorat qilmoqchiman."}, {"id": "t6-v3-17", "stem": "新しい仕事を（　）することになった。", "options": ["出社", "通勤", "出張", "担当"], "answer": 4, "explanation_uz": "担当 = mas'ul bo'lish, zimmasiga olish", "tr": "Yangi ishni zimmamga olishimga to'g'ri keldi."}, {"id": "t6-v3-18", "stem": "彼女を（　）コーヒーを飲みに行った。", "options": ["語って", "誘って", "論じて", "遊んで"], "answer": 2, "explanation_uz": "誘う = taklif qilmoq, birga olib bormoq", "tr": "Uni taklif qilib, kofe ichgani bordik."}, {"id": "t6-v3-19", "stem": "山田さんは、私の（　）の友だちだ。", "options": ["唯一", "単一", "同一", "万一"], "answer": 1, "explanation_uz": "唯一 = yagona, bittagina", "tr": "Yamada-san mening yagona do'stim."}, {"id": "t6-v3-20", "stem": "ちゃんと勉強していれば、テストを（　）よい。", "options": ["かなしまなくても", "おそれなくても", "さびしがらなくても", "にげなくても"], "answer": 2, "explanation_uz": "おそれる = qo'rqmoq; おそれなくてもよい = qo'rqmasa ham bo'ladi", "tr": "Yaxshilab o'qigan bo'lsang, imtihondan qo'rqmasang ham bo'ladi."}, {"id": "t6-v3-21", "stem": "仕事中に大きな（　）が起きた。", "options": ["アクセス", "ストップ", "ヒット", "トラブル"], "answer": 4, "explanation_uz": "トラブル = muammo, nizo", "tr": "Ish vaqtida katta muammo yuz berdi."}, {"id": "t6-v3-22", "stem": "使用（　）のものは、ここに捨ててください。", "options": ["止め", "済み", "終わり", "切り"], "answer": 2, "explanation_uz": "使用済み = ishlatilgan, foydalanib bo'lingan", "tr": "Ishlatib bo'lingan narsalarni shu yerga tashlang."}, {"id": "t6-v3-23", "stem": "私は、両親のおかげで（　）できました。", "options": ["保育", "前後", "成長", "発展"], "answer": 3, "explanation_uz": "成長 = o'sish, ulg'ayish", "tr": "Men ota-onam tufayli ulg'aya oldim."}, {"id": "t6-v3-24", "stem": "（　）お宅に遊びに行くうちに、田中さんと親しくなった。", "options": ["ちかぢか", "まるまる", "たびたび", "いちいち"], "answer": 3, "explanation_uz": "たびたび = tez-tez, qayta-qayta", "tr": "Tez-tez uyiga borib turib, Tanaka-san bilan yaqinlashib qoldim."}, {"id": "t6-v3-25", "stem": "なんとなく体が（　）だ。", "options": ["調子", "調整", "低調", "不調"], "answer": 4, "explanation_uz": "不調 = noso'z, nochor holat, mazasizlik", "tr": "Negadir tanamda nochorlik (mazasizlik) bor."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t6-v4-26", "stem": "この本は、とても【やさしい】。", "options": ["安い", "高い", "簡単だ", "難しい"], "answer": 3, "explanation_uz": "やさしい = oson → 簡単だ", "tr": "Bu kitob juda oson."}, {"id": "t6-v4-27", "stem": "彼女は、電車の中で【ささやいた】。", "options": ["大きな声で話した", "小さな声で話した", "たくさん眠った", "少し眠った"], "answer": 2, "explanation_uz": "ささやく = pichirlamoq → 小さな声で話した (past ovozda gapirdi)", "tr": "U poyezdda pichirladi."}, {"id": "t6-v4-28", "stem": "私のことは、あまり【気にしないで】ください。", "options": ["怒らないで", "笑わないで", "心配しないで", "驚かないで"], "answer": 3, "explanation_uz": "気にする = e'tibor bermoq, tashvishlanmoq → 心配しないで", "tr": "Men haqimda ko'p tashvishlanmang."}, {"id": "t6-v4-29", "stem": "先生は子どもたちを【しかった】。", "options": ["命令した", "監督した", "注意した", "評価した"], "answer": 3, "explanation_uz": "しかる = koyimoq, urishmoq → 注意した (ogohlantirdi, tanbeh berdi)", "tr": "O'qituvchi bolalarni urishdi (tanbeh berdi)."}, {"id": "t6-v4-30", "stem": "あの人は、とても【ていねいに】話す。", "options": ["大きな声で", "親切そうに", "きれいな発音で", "礼儀正しく"], "answer": 4, "explanation_uz": "ていねいに = ehtiyotkorlik/odob bilan → 礼儀正しく (odobli)", "tr": "U odam juda odob bilan gapiradi."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t6-v5-31", "stem": "すれ違う", "options": ["さっき、知り合いが乗った車とすれ違った。", "左右の靴をすれ違ってはいていた。", "本の名前をすれ違って、他の本を買ってしまった。", "今度のテストでは、たくさん答えをすれ違った。"], "answer": 1, "optsTr": ["Hozir tanishim o'tirgan mashina bilan yonma-yon o'tib ketdik. (to'g'ri)", "Chap-o'ng oyoq kiyimni 'aralashtirib' kiygan edim (noto'g'ri — 間違える kerak).", "Kitob nomini 'adashtirib', boshqa kitob sotib oldim (noto'g'ri).", "Bu testda ko'p javoblarni 'adashtirdim' (noto'g'ri)."], "tr": "すれ違う = bir-birining yonidan o'tib ketmoq (qarama-qarshi yo'nalishda)."}, {"id": "t6-v5-32", "stem": "わかす", "options": ["たまごをわかして食べるとおいしい。", "トースターでパンをわかして食べた。", "なべで野菜をわかして料理を作った。", "お茶を飲むために、お湯をわかした。"], "answer": 4, "optsTr": ["Tuxumni 'qaynatib' yegan mazali (noto'g'ri — ゆでる kerak).", "Tosterda nonni 'qaynatib' yedim (noto'g'ri).", "Qozonda sabzavotni 'qaynatib' taom qildim (noto'g'ri — 煮る kerak).", "Choy ichish uchun suv qaynatdim. (to'g'ri)"], "tr": "わかす = (suvni) qaynatmoq."}, {"id": "t6-v5-33", "stem": "タイミング", "options": ["タイミングがなくて、試験の問題が全部できませんでした。", "上手なタイミングをして、会議の時間に会社に着いた。", "駅に着いたら、タイミングよく電車が来た。", "長いタイミングがあったら、ぜひまた旅行に行きましょう。"], "answer": 3, "optsTr": ["'Vaqt-payt' bo'lmagani uchun imtihon savollarini bajara olmadim (noto'g'ri — 時間 kerak).", "'Yaxshi tayming qilib', yig'ilish vaqtida yetib keldim (noto'g'ri).", "Bekatga yetganimda, ayni paytida poyezd keldi. (to'g'ri)", "'Uzoq tayming' bo'lsa, yana sayohatga boraylik (noto'g'ri — 時間 kerak)."], "tr": "タイミング = vaqt-payt, qulay lahza."}, {"id": "t6-v5-34", "stem": "しろうと", "options": ["彼はこの分野のしろうとなので、何でも質問してください。", "彼はしろうとの運転手なので、かなり運転が上手だ。", "この病院には、しろうとの病人がたくさんいる。", "私は映画のしろうとなので、映画のことはよくわかりません。"], "answer": 4, "optsTr": ["U bu sohaning 'havaskori', shuning uchun istalgan narsani so'rang (noto'g'ri — 専門家 kerak).", "U 'havaskor' haydovchi, shuning uchun juda yaxshi haydaydi (noto'g'ri/ziddiyat).", "Bu kasalxonada 'havaskor' bemorlar ko'p (noto'g'ri).", "Men kino bo'yicha havaskorman, kino haqida yaxshi bilmayman. (to'g'ri)"], "tr": "しろうと(素人) = havaskor, mutaxassis bo'lmagan odam."}, {"id": "t6-v5-35", "stem": "豊か", "options": ["あの男の人が着ているシャツやネクタイの色は豊かだ。", "この国は、気候も温暖だし、資源も豊かだ。", "今晩は時間が豊かなので、電話してください。", "たくさん運動して、筋肉を豊かにしようと思う。"], "answer": 2, "optsTr": ["U erkak kiygan ko'ylak va galstuk rangi 'boy' (noto'g'ri — 派手 kerak).", "Bu davlatning iqlimi ham issiq, resurslari ham boy. (to'g'ri)", "Bugun kechqurun vaqtim 'boy' (noto'g'ri — たっぷり kerak).", "Ko'p sport qilib, mushaklarni 'boy' qilmoqchiman (noto'g'ri)."], "tr": "豊か = boy, mo'l, serob."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t6-g1-1", "stem": "もし時間があったら、あそこでお茶（　）飲みませんか。", "options": ["ほど", "でも", "から", "きり"], "answer": 2, "explanation_uz": "〜でも = ...-poy (misol keltirib, yengil taklif)", "tr": "Agar vaqting bo'lsa, anavi yerda choy-poy ichmaymizmi?"}, {"id": "t6-g1-2", "stem": "よけいなことを言った（　）、母が怒ってしまった。", "options": ["たびに", "ところに", "ばかりに", "ごとに"], "answer": 3, "explanation_uz": "〜たばかりに = faqat ...ganim sababli (yomon natija)", "tr": "Ortiqcha gap aytganim uchun, onam jahli chiqib qoldi."}, {"id": "t6-g1-3", "stem": "私は25歳なので、もう（　）以上、背は高くならないだろう。", "options": ["どこ", "それ", "どれ", "これ"], "answer": 4, "explanation_uz": "これ以上 = bundan ortiq, bundan ziyod", "tr": "Men 25 yoshdaman, shuning uchun bundan ortiq bo'yim o'smasa kerak."}, {"id": "t6-g1-4", "stem": "一度にバナナを20本も食べられる（　）。", "options": ["ようがない", "ものがない", "ことがない", "わけがない"], "answer": 4, "explanation_uz": "〜わけがない = ...bo'lishi mumkin emas", "tr": "Bir o'tirishda 20 dona bananni yeb bo'lmaydi (mumkin emas)."}, {"id": "t6-g1-5", "stem": "高橋「山田さん、英語がお上手ですね。」山田「いいえ、（　）上手じゃありません。」", "options": ["めったに", "たいして", "やたらに", "ほんの"], "answer": 2, "explanation_uz": "たいして〜ない = uncha ...emas", "tr": "Takaxashi: «Yamada-san, ingliz tilini yaxshi bilarkansiz.» Yamada: «Yo'q, uncha yaxshi emasman.»"}, {"id": "t6-g1-6", "stem": "この食品は、味がいいのに（　）、値段も安いです。", "options": ["加えずに", "加えないで", "加えて", "加えたら"], "answer": 3, "explanation_uz": "〜に加えて = ...ga qo'shimcha, bundan tashqari", "tr": "Bu mahsulot mazasi yaxshi bo'lishiga qo'shimcha, narxi ham arzon."}, {"id": "t6-g1-7", "stem": "病気になってから、もうたばこは（　）まいと思った。", "options": ["吸う", "吸い", "吸おう", "吸って"], "answer": 2, "explanation_uz": "〜まい = ...maslikka (qat'iy inkor niyat). 吸い+まい", "tr": "Kasal bo'lganimdan keyin, endi tamaki chekmaslikka qaror qildim."}, {"id": "t6-g1-8", "stem": "卒業するときに、先生からプレゼントを（　）。", "options": ["あげました", "さしあげました", "やりました", "いただきました"], "answer": 4, "explanation_uz": "いただく = もらう ning kamtarlik shakli (oldim)", "tr": "Bitirayotganimda, o'qituvchidan sovg'a oldim."}, {"id": "t6-g1-9", "stem": "社員「社長の来月の予定を教えていただけますか。」課長「もうしわけありませんが、社長の予定は（　）。」", "options": ["わかります", "わかりました", "わかりかねます", "わかりかねました"], "answer": 3, "explanation_uz": "〜かねる = ... qila olmaslik (xushmuomala rad). わかりかねます = bila olmayman", "tr": "Xodim: «Rahbarning keyingi oylik rejasini ayta olasizmi?» Bo'lim boshlig'i: «Kechirasiz, rahbarning rejasini bila olmayman.»"}, {"id": "t6-g1-10", "stem": "日本では、新しい学年は4月に始まる（　）。", "options": ["ものとなっている", "こととなっている", "わけになっている", "ほどになっている"], "answer": 2, "explanation_uz": "〜こととなっている = ...qilib belgilangan (qoida/qaror)", "tr": "Yaponiyada yangi o'quv yili aprelda boshlanadigan qilib belgilangan."}, {"id": "t6-g1-11", "stem": "彼は何も準備をしていないのだから、明日の試験に（　）。", "options": ["落ちるに決めている", "落ちるところに決めている", "落ちるに決まっている", "落ちるところに決まっている"], "answer": 3, "explanation_uz": "〜に決まっている = albatta ...bo'ladi (ishonch)", "tr": "U hech qanday tayyorgarlik ko'rmagan, shuning uchun ertangi imtihondan albatta yiqiladi."}, {"id": "t6-g1-12", "stem": "小さい子どもは、たばこを（　）。", "options": ["吸ってもらいません", "吸うわけではありません", "吸わなくしてください", "吸ってはいけません"], "answer": 4, "explanation_uz": "〜てはいけない = ...maslik kerak (taqiq)", "tr": "Kichik bolalar tamaki chekmasligi kerak."}, {"id": "t6-g1-13", "stem": "店員「いらっしゃいませ。」客「すみません。この服を（　）。」", "options": ["着てみたらいいでしょうか", "着てみるのもいいですか", "着てみるのがいいでしょうか", "着てみてもいいですか"], "answer": 4, "explanation_uz": "〜てみてもいいですか = ...ib ko'rsam bo'ladimi (ruxsat so'rash)", "tr": "Sotuvchi: «Xush kelibsiz.» Mijoz: «Kechirasiz. Bu kiyimni kiyib ko'rsam bo'ladimi?»"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t6-g2-14", "options": ["せいで", "甘い", "大好きな", "ものが"], "answer": 3, "prefix": "チョコレートやケーキなど", "suffix": "太ってしまった。", "starPos": 3, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: 甘いものが大好きなせいで", "tr": "To'g'ri jumla: «Shokolad va tort kabi shirin narsalarni juda yaxshi ko'rganim sababli, semirib ketdim.»"}, {"id": "t6-g2-15", "options": ["ことを", "おけば", "決まった", "申し上げて"], "answer": 1, "prefix": "では、部長には、会議で", "suffix": "よろしいでしょうか。", "starPos": 2, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: 決まったことを申し上げておけば", "tr": "To'g'ri jumla: «Bo'lim boshlig'iga yig'ilishda hal qilingan narsani aytib qo'ysam bo'ladimi?»"}, {"id": "t6-g2-16", "options": ["と", "している", "しよう", "ところへ"], "answer": 2, "prefix": "ちょうど宿題を", "suffix": "友だちがやって来た。", "starPos": 3, "order": [3, 1, 2, 4], "explanation_uz": "To'g'ri tartib: しようとしているところへ", "tr": "To'g'ri jumla: «Aynan uy vazifasini qilmoqchi bo'lib turganimda, do'stim kelib qoldi.»"}, {"id": "t6-g2-17", "options": ["に", "行く", "旅行に", "たび"], "answer": 4, "prefix": "私は、人形が好きなので、", "suffix": "その国の人形を買ってきます。", "starPos": 3, "order": [3, 2, 4, 1], "explanation_uz": "To'g'ri tartib: 旅行に行くたびに", "tr": "To'g'ri jumla: «Men qo'g'irchoqlarni yoqtirganim uchun, har safar sayohatga borganimda o'sha mamlakat qo'g'irchog'ini sotib olib kelaman.»"}, {"id": "t6-g2-18", "options": ["動物たちが", "はじめ", "かわいい", "とする"], "answer": 3, "prefix": "その動物園には、パンダを", "suffix": "たくさんいる。", "starPos": 3, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: はじめとするかわいい動物たちが (Aを はじめとする = A boshchiligida)", "tr": "To'g'ri jumla: «U hayvonot bog'ida pandani boshlab, ko'plab yoqimtoy hayvonlar bor.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "初めての銭湯（ピエール・マルタン）", "passage": "あなたは、日本のお風呂といえば何を思いうかべますか。温泉でしょうか、銭湯でしょうか。いろいろありますが、私の場合は「銭湯」です。\n私の故郷には、毎日お風呂に入るという習慣はありません。{{19}}、日本へ来たばかりのときは、日本人が毎日お風呂に入るということを知って、とても驚きました。\n家にお風呂がある人は、家のお風呂に毎日入りますし、家にお風呂がない場合も、毎日のように家の近所にある「銭湯」に行きます。{{20}}習慣を持っている民族は、広い世界の中でもあまりないと思います。\n初めて銭湯に行ったときに、驚いたことがたくさんありました。{{21a}}、建物がお寺や神社のようなとても古い建物だったこと。第二に、入口が「男湯」と「女湯」に分かれていたこと。第三に、ほかの人の前で服を全部脱いでお風呂に入らなければならなかったこと。{{21b}}、お風呂のお湯の温度がとても高かったことです。\nしかし、今では日本の銭湯にも{{22}}。なにも気にせずに熱いお湯にゆっくり入れるようになりました。私もかなり「日本人」に近づいてきたという{{23}}。", "passage_tr": "Yaponiyaning hammomi (お風呂) deyilsa, nima ko'z oldingizga keladi? Issiq buloqmi (onsen), jamoa hammomimi (sento)? Turlichasi bor, mening holatimda esa — «sento». Mening vatanimda har kuni hammomga tushish odati yo'q. SHUNING UCHUN, Yaponiyaga endi kelganimda, yaponlar har kuni cho'milishini bilib, juda hayron bo'ldim. Uyida hammomi bor odamlar har kuni o'z hammomida cho'miladi; hammomi yo'qlar ham deyarli har kuni uy yaqinidagi «sento»ga boradi. BUNDAY odatga ega xalq keng dunyoda ham kam uchraydi deb o'ylayman. Birinchi marta sento'ga borganimda, hayron qoldirgan narsalar ko'p edi. AVVALO, bino ibodatxona yoki ziyoratgohga o'xshash juda eski bino edi. Ikkinchidan, kirish «erkaklar hammomi» va «ayollar hammomi»ga ajratilgan edi. Uchinchidan, boshqalar oldida kiyimni butunlay yechib cho'milish kerak edi. ENG AVVALO (yana bir muhimi), suvning harorati juda yuqori edi. Ammo endilikda yapon sento'siga ham KO'NIKIB BORYAPMAN. Hech narsadan tashvishlanmay, issiq suvga bemalol tusha oladigan bo'ldim. Men ham ancha «yaponlar»ga yaqinlashib qolganim SHU bo'lsa kerak.", "questions": [{"id": "t6-g3-19", "options": ["なぜなら", "または", "ですから", "ただし"], "answer": 3, "blankNo": "19", "explanation_uz": "ですから = shuning uchun, demak (sabab-natija)", "tr": "習慣はありません。[ですから]日本へ来たばかりのとき…驚きました = odat yo'q. SHUNING UCHUN kelganimda hayron bo'ldim."}, {"id": "t6-g3-20", "options": ["あの", "このような", "ああした", "それほどの"], "answer": 2, "blankNo": "20", "explanation_uz": "このような = bunday, shunaqa (yaqinda aytilganga ishora)", "tr": "[このような]習慣を持っている民族 = BUNDAY odatga ega xalq."}, {"id": "t6-g3-21", "options": ["まずは ／ 最初に", "まずは ／ 最後に", "最初に ／ まずは", "最後に ／ まずは"], "answer": 3, "blankNo": "21", "explanation_uz": "最初に = avvalo/birinchi (a-o'rin); ro'yxat: 最初に・第二に・第三に", "tr": "21-a [最初に]…第二に…第三に…21-b [まずは] = ro'yxatni 最初に boshlab sanaydi."}, {"id": "t6-g3-22", "options": ["慣れてつつあります", "慣れてつついます", "慣れつつあります", "慣れつついます"], "answer": 3, "blankNo": "22", "explanation_uz": "〜つつある = asta-sekin ...ib bormoqda. ます-shakl: 慣れ+つつある", "tr": "今では銭湯にも[慣れつつあります] = endi ko'nikib boryapman."}, {"id": "t6-g3-23", "options": ["限りでしょうか", "どころでしょうか", "上でしょうか", "ことでしょうか"], "answer": 4, "blankNo": "23", "explanation_uz": "〜ということでしょうか = ...degani shudir/shu bo'lsa kerak (yumshoq xulosa)", "tr": "「日本人」に近づいてきたという[ことでしょうか] = ...ga yaqinlashganim shu bo'lsa kerak."}]}]}]}, "7": {"id": 7, "title_jp": "第7回 模擬テスト", "title_uz": "7-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t7-v1-1", "stem": "道路に大きな木が【倒れて】いる。", "options": ["おれて", "もたれて", "われて", "たおれて"], "answer": 4, "reading": "たおれて", "explanation_uz": "倒れる → たおれる (qulamoq, ag'darilmoq)", "tr": "Yo'lda katta daraxt qulab yotibdi."}, {"id": "t7-v1-2", "stem": "あの【植物】の名前を知っていますか。", "options": ["しょくもの", "しきもの", "しょくぶつ", "しきぶつ"], "answer": 3, "reading": "しょくぶつ", "explanation_uz": "植物 → しょくぶつ (o'simlik)", "tr": "Anavi o'simlikning nomini bilasizmi?"}, {"id": "t7-v1-3", "stem": "週末は、【知人】に会う約束がある。", "options": ["ちにん", "ちじん", "しにん", "しじん"], "answer": 2, "reading": "ちじん", "explanation_uz": "知人 → ちじん (tanish odam)", "tr": "Dam olish kunlari tanishim bilan uchrashuv bor."}, {"id": "t7-v1-4", "stem": "箱をいくつか【積んだ】。", "options": ["たたんだ", "つつんだ", "つんだ", "ふんだ"], "answer": 3, "reading": "つんだ", "explanation_uz": "積む → つむ (ustma-ust qo'ymoq, yuklamoq)", "tr": "Bir nechta qutini ustma-ust qaladim."}, {"id": "t7-v1-5", "stem": "【迷惑】なことをしないでください。", "options": ["めんどう", "めいわく", "じゃま", "さいあく"], "answer": 2, "reading": "めいわく", "explanation_uz": "迷惑 → めいわく (tashvish, ovoragarchilik berish)", "tr": "Bezovta qiladigan (xalaqit beradigan) ish qilmang."}, {"id": "t7-v1-6", "stem": "この【地域】には、スーパーがありません。", "options": ["ちたい", "じたい", "ちいき", "じいき"], "answer": 3, "reading": "ちいき", "explanation_uz": "地域 → ちいき (hudud, mintaqa)", "tr": "Bu hududda supermarket yo'q."}, {"id": "t7-v1-7", "stem": "きのう、【庭】のそうじをしました。", "options": ["にわ", "へや", "ゆか", "かべ"], "answer": 1, "reading": "にわ", "explanation_uz": "庭 → にわ (hovli, bog')", "tr": "Kecha hovlini tozaladim."}, {"id": "t7-v1-8", "stem": "わが社では、最近、社長が【交代】した。", "options": ["こうてい", "こうたい", "こうでい", "こうだい"], "answer": 2, "reading": "こうたい", "explanation_uz": "交代 → こうたい (almashinish, navbatlashish)", "tr": "Bizning kompaniyada yaqinda rahbar almashdi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t7-v2-9", "stem": "【あんいな】考えは捨てなさい。", "options": ["浅易", "案易", "暗易", "安易"], "answer": 4, "explanation_uz": "あんい → 安易 (yengil-elpi, oson yo'l)", "tr": "Yengil-elpi (o'ylamasdan qilingan) fikrni tashlang."}, {"id": "t7-v2-10", "stem": "建物の【こうぞう】を調べる。", "options": ["構造", "溝造", "購造", "講造"], "answer": 1, "explanation_uz": "こうぞう → 構造 (tuzilish, struktura)", "tr": "Binoning tuzilishini tekshiraman."}, {"id": "t7-v2-11", "stem": "それを【ひろって】ください。", "options": ["触って", "拾って", "放って", "払って"], "answer": 2, "explanation_uz": "ひろう → 拾う (terib olmoq, yerdan olmoq)", "tr": "Uni yerdan oling (terib oling)."}, {"id": "t7-v2-12", "stem": "1人に3つずつわけると、2つ【あまる】。", "options": ["与る", "残る", "余る", "甘る"], "answer": 3, "explanation_uz": "あまる → 余る (ortib qolmoq, ortmoq)", "tr": "Har kishiga 3 tadan bo'lsak, 2 ta ortib qoladi."}, {"id": "t7-v2-13", "stem": "いろいろな仕事を【けいけん】する。", "options": ["実験", "体験", "経験", "治験"], "answer": 3, "explanation_uz": "けいけん → 経験 (tajriba)", "tr": "Turli ishlarni tajriba qilaman (boshimdan kechiraman)."}, {"id": "t7-v2-14", "stem": "サルがすばやい【どうさ】で木にのぼる。", "options": ["働昨", "動昨", "働作", "動作"], "answer": 4, "explanation_uz": "どうさ → 動作 (harakat, xatti-harakat)", "tr": "Maymun chaqqon harakat bilan daraxtga chiqadi."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t7-v3-15", "stem": "いつも帽子をかぶるのが、彼の（　）だ。", "options": ["スマート", "タイトル", "ペース", "スタイル"], "answer": 4, "explanation_uz": "スタイル = uslub, stil", "tr": "Doim shlyapa kiyish — uning uslubi (stili)."}, {"id": "t7-v3-16", "stem": "わが国は、A国と（　）を行っている。", "options": ["表示", "貿易", "伝達", "流行"], "answer": 2, "explanation_uz": "貿易 = (tashqi) savdo", "tr": "Bizning davlat A davlat bilan savdo (tashqi savdo) olib boradi."}, {"id": "t7-v3-17", "stem": "できるかぎり（　）して仕事を進める。", "options": ["工夫", "救助", "心配", "採用"], "answer": 1, "explanation_uz": "工夫する = chora-tadbir izlamoq, pux ta o'ylamoq", "tr": "Imkon qadar pux ta o'ylab (chora topib) ishni davom ettiraman."}, {"id": "t7-v3-18", "stem": "雷がこわくて、（　）過ごした。", "options": ["しびれて", "ゆれて", "ふるえて", "ひえて"], "answer": 3, "explanation_uz": "ふるえる = qaltiramoq, titramoq", "tr": "Momaqaldiroqdan qo'rqib, qaltirab o'tirdim."}, {"id": "t7-v3-19", "stem": "テストで、今までで（　）の成績をおさめた。", "options": ["最善", "最大", "最多", "最高"], "answer": 4, "explanation_uz": "最高 = eng yuqori, eng zo'r", "tr": "Testda hozirgacha eng yuqori natijani qo'lga kiritdim."}, {"id": "t7-v3-20", "stem": "建物が台風から私たちを（　）くれた。", "options": ["守って", "許して", "負けて", "認めて"], "answer": 1, "explanation_uz": "守る = himoya qilmoq, asramoq", "tr": "Bino bizni tayfundan himoya qildi."}, {"id": "t7-v3-21", "stem": "コピー機に用紙が（　）されているかどうか、調べてください。", "options": ["スイッチ", "プリント", "インク", "セット"], "answer": 4, "explanation_uz": "セットする = o'rnatmoq, joylashtirmoq, sozlamoq", "tr": "Nusxa olish mashinasiga qog'oz qo'yilgan-qo'yilmaganini tekshiring."}, {"id": "t7-v3-22", "stem": "私のアパートの部屋は東（　）です。", "options": ["開け", "行き", "向き", "沿い"], "answer": 3, "explanation_uz": "〜向き = ...ga qaragan (tomon)", "tr": "Mening kvartiram xonasi sharqqa qaragan."}, {"id": "t7-v3-23", "stem": "音が大きすぎるので、（　）してください。", "options": ["減少", "安定", "調節", "改定"], "answer": 3, "explanation_uz": "調節する = sozlamoq, moslamoq, tartibga solmoq", "tr": "Ovoz juda baland, shuning uchun moslang (sozlang)."}, {"id": "t7-v3-24", "stem": "きのうの夜、（　）おなかが痛くなったので、心配だ。", "options": ["やっと", "せっかく", "ちゃんと", "急に"], "answer": 4, "explanation_uz": "急に = to'satdan, birdan", "tr": "Kecha tunda to'satdan qornim og'rib qoldi, shuning uchun xavotirdaman."}, {"id": "t7-v3-25", "stem": "私にはこの絵の（　）が理解できない。", "options": ["原料", "価値", "金銭", "物価"], "answer": 2, "explanation_uz": "価値 = qiymat, qadr", "tr": "Men bu rasmning qadrini (qiymatini) tushunolmayman."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t7-v4-26", "stem": "【めずらしい】くだものを食べた。", "options": ["よくある", "ときどきある", "あまりない", "どこにもない"], "answer": 3, "explanation_uz": "めずらしい = noyob, kam uchraydigan → あまりない", "tr": "Noyob (kam uchraydigan) mevani yedim."}, {"id": "t7-v4-27", "stem": "テーブルの上の紙を【まとめた】。", "options": ["集めた", "分けた", "捨てた", "破った"], "answer": 1, "explanation_uz": "まとめる = jamlamoq, bir joyga to'plamoq → 集めた", "tr": "Stol ustidagi qog'ozlarni jamladim (bir joyga to'pladim)."}, {"id": "t7-v4-28", "stem": "田中さんは、山田さんに【手を貸した】。", "options": ["握手した", "助けた", "手紙を書いた", "お金を貸した"], "answer": 2, "explanation_uz": "手を貸す = yordam bermoq (idioma) → 助けた", "tr": "Tanaka-san Yamada-sanga yordam berdi."}, {"id": "t7-v4-29", "stem": "あの2人は、【気が合う】ようだ。", "options": ["つき合っている", "ときどき会っている", "仲がよい", "仲が悪い"], "answer": 3, "explanation_uz": "気が合う = til topishmoq, chiqishmoq → 仲がよい", "tr": "U ikkovi til topishadiganga (chiqishadiganga) o'xshaydi."}, {"id": "t7-v4-30", "stem": "【おかしな】ことが続けて起こった。", "options": ["すばらしい", "つまらない", "平凡な", "不思議な"], "answer": 4, "explanation_uz": "おかしな = g'alati, ajabtovur → 不思議な (sirli, g'aroyib)", "tr": "G'alati narsalar ketma-ket yuz berdi."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t7-v5-31", "stem": "さけぶ", "options": ["電話で母に、きのうあった出来事についてさけんだ。", "毎日、その日あったことを日記にさけんでいる。", "前から歩いてきた犬が、私に向かってさけんできた。", "遠くを歩いている友だちの名前を思いきりさけんだ。"], "answer": 4, "optsTr": ["Telefonda onamga kechagi voqea haqida 'baqirdim' (noto'g'ri — 話した kerak).", "Har kuni kun voqealarini kundalikka 'baqiraman' (noto'g'ri — 書く kerak).", "Oldindan kelayotgan it menga qarab 'baqirdi' (noto'g'ri — it uchun 吠える kerak).", "Uzoqda ketayotgan do'stimning ismini bor ovozda baqirdim. (to'g'ri)"], "tr": "さけぶ = baqirmoq, qichqirmoq."}, {"id": "t7-v5-32", "stem": "ふく", "options": ["よごれたシャツを洗たく機でふいた。", "テーブルが汚いので、すぐにふいてください。", "客が来るので、部屋を掃除機でふかなければなりません。", "落ちているごみをごみ箱にふいてください。"], "answer": 2, "optsTr": ["Kir ko'ylakni kir mashinada 'artdim' (noto'g'ri — 洗う kerak).", "Stol kir, shuning uchun darrov arting. (to'g'ri)", "Mehmon keladi, xonani changyutgich bilan 'artish' kerak (noto'g'ri — かける kerak).", "Yerga tushgan axlatni axlat qutisiga 'arting' (noto'g'ri — 捨てる kerak)."], "tr": "ふく(拭く) = artmoq, surtib tozalamoq."}, {"id": "t7-v5-33", "stem": "ヒント", "options": ["景色にヒントをつけて、写真をとりました。", "よいヒントを与えられ、この会社に入ることができました。", "この店では、500円以上買い物しないとヒントがつきません。", "この問題は難しすぎるので、解くためのヒントをください。"], "answer": 4, "optsTr": ["Manzaraga 'ishora' qo'yib, rasmga oldim (noto'g'ri).", "Yaxshi 'ishora' berilib, bu kompaniyaga kira oldim (noto'g'ri — コネ kerak).", "Bu do'konda 500 yendan ko'p xarid qilmasa 'ishora' qo'shilmaydi (noto'g'ri — ポイント kerak).", "Bu masala juda qiyin, yechish uchun ishora (yo'l-yo'riq) bering. (to'g'ri)"], "tr": "ヒント = ishora, yo'l-yo'riq, maslahat."}, {"id": "t7-v5-34", "stem": "お見舞い", "options": ["今日は私の誕生日なので、お見舞いをもらった。", "日本では結婚式のお見舞いに、何をあげればいいですか。", "夜遅くまで勉強していたら、母がお見舞いを持って来てくれた。", "病院に入院している同僚に、お見舞いを持って行った。"], "answer": 4, "optsTr": ["Bugun tug'ilgan kunim, 'ko'rgani sovg'a' oldim (noto'g'ri — プレゼント kerak).", "Yaponiyada to'yga 'ko'rgani sovg'a' sifatida nima berish kerak? (noto'g'ri — ご祝儀 kerak).", "Kech tungacha o'qiganimda, onam 'ko'rgani sovg'a' olib keldi (noto'g'ri — 夜食 kerak).", "Kasalxonada yotgan hamkasbimni ko'rgani sovg'a olib bordim. (to'g'ri)"], "tr": "お見舞い = (kasal/baxtsizlikka uchraganni) ko'rgani borish, ko'rgazma sovg'asi."}, {"id": "t7-v5-35", "stem": "おしゃれ", "options": ["この部屋はそうじをしたばかりなので、おしゃれです。", "あの人は頭はいいが、おしゃれなところがある。", "祖母は今年80歳になるが、今でもとてもおしゃれだ。", "授業中に友だちとおしゃれしていて、先生に注意されてしまった。"], "answer": 3, "optsTr": ["Bu xona endi tozalangani uchun 'shinam' (noto'g'ri — きれい kerak).", "U odam aqlli, lekin 'shinam' joyi bor (noto'g'ri — ぬけた kerak).", "Buvim bu yil 80 yoshga kiradi, lekin hozir ham juda shinam kiyinadi. (to'g'ri)", "Dars vaqtida do'stim bilan 'shinam' bo'lib, o'qituvchidan tanbeh oldim (noto'g'ri — おしゃべり kerak)."], "tr": "おしゃれ = shinam kiyinish, didli, zamonaviy ko'rinish."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t7-g1-1", "stem": "子ども（　）できる計算をまちがえてしまった。", "options": ["から", "だけ", "でも", "しか"], "answer": 3, "explanation_uz": "〜でも = hatto ...ham (so'nggi darajani misol qilib)", "tr": "Hatto bola ham bajara oladigan hisobni xato qilib qo'ydim."}, {"id": "t7-g1-2", "stem": "彼女の優しい言葉を聞いて、うれしくて涙が出る（　）だった。", "options": ["もの", "こと", "ほど", "よう"], "answer": 3, "explanation_uz": "〜ほど = ...darajada (daraja ko'rsatadi)", "tr": "Uning mehribon so'zlarini eshitib, xursandligimdan ko'z yoshim chiqquday bo'ldi."}, {"id": "t7-g1-3", "stem": "あの人は、2年前（　）ギターを習い始めたそうです。", "options": ["より", "により", "よりも", "はより"], "answer": 1, "explanation_uz": "〜より = ...dan (vaqt/o'rin boshlanish nuqtasi)", "tr": "U odam 2 yil avvaldan gitara o'rgana boshlagan ekan."}, {"id": "t7-g1-4", "stem": "今から私の言う（　）、ノートに書いてください。", "options": ["なりに", "ほどに", "通りに", "そうに"], "answer": 3, "explanation_uz": "〜通りに = ...ganday, xuddi ...kabi", "tr": "Endi men aytganimday qilib, daftaringizga yozing."}, {"id": "t7-g1-5", "stem": "広い道路（　）、まっすぐ10分くらい歩くと、会社に着きます。", "options": ["において", "にかけて", "に沿って", "を通じて"], "answer": 3, "explanation_uz": "〜に沿って = ...bo'ylab, ...ga yondosh", "tr": "Keng yo'l bo'ylab to'g'riga 10 daqiqacha yursangiz, kompaniyaga yetasiz."}, {"id": "t7-g1-6", "stem": "あの人があぶない運転を（　）なんて、信じられない。", "options": ["す", "する", "し", "して"], "answer": 2, "explanation_uz": "普通形+なんて = ...deganni (kutilmagan/ishonarsiz his). 運転をする+なんて", "tr": "U odam xavfli haydash qiladi deganni ishonib bo'lmaydi."}, {"id": "t7-g1-7", "stem": "学校の先生に、この教室には（　）と言われました。", "options": ["入らされるな", "入るな", "入らせるな", "入られるな"], "answer": 2, "explanation_uz": "動詞辞書形+な = ...ma (qat'iy taqiq). 入るな", "tr": "Maktab o'qituvchisi menga: «Bu sinfga kirma» dedi."}, {"id": "t7-g1-8", "stem": "1人で10人分の仕事をするなんて（　）。", "options": ["できかねない", "できなくはない", "できっこない", "できないことはない"], "answer": 3, "explanation_uz": "〜っこない = aslo ...bo'lmaydi (kuchli inkor). できっこない", "tr": "Yolg'iz 10 kishilik ishni qilish — aslo bo'lmaydi (imkonsiz)."}, {"id": "t7-g1-9", "stem": "松本「今日はおじゃましました。」金子「いいえ、また（　）ください。」", "options": ["おはいりになって", "おいきになって", "おかえりになって", "おいでになって"], "answer": 4, "explanation_uz": "おいでになる = 来る/行く ning hurmat shakli (keling)", "tr": "Matsumoto: «Bugun bezovta qildim.» Kaneko: «Yo'q, yana keling.»"}, {"id": "t7-g1-10", "stem": "秘書「部長、ワールド商事の青木様が（　）。」部長「会議室にご案内して。」", "options": ["参られました", "参りました", "見ました", "見えました"], "answer": 4, "explanation_uz": "見える = 来る ning hurmat shakli (keldilar). お客様が見えました", "tr": "Kotiba: «Boshliq, World Shoji'dan Aoki-sama keldilar.» Boshliq: «Yig'ilish xonasiga boshlab boring.»"}, {"id": "t7-g1-11", "stem": "私は、ただの社員に（　）、大事なことを決めることはできません。", "options": ["あり得ますから", "あり得ませんので", "すぎますから", "すぎませんので"], "answer": 4, "explanation_uz": "〜にすぎない = faqat ...xolos. ただの社員にすぎません", "tr": "Men oddiy xodimdan boshqa narsa emasman, shuning uchun muhim narsalarni hal qila olmayman."}, {"id": "t7-g1-12", "stem": "このセーターはかわいいけれど（　）、着るときに注意しています。", "options": ["汚れやすいので", "汚れてもいいので", "汚れづらいので", "汚れにくいので"], "answer": 1, "explanation_uz": "〜やすい = oson ...bo'ladi. 汚れやすい = oson kirlanadigan", "tr": "Bu sviter chiroyli, lekin oson kirlanadigani uchun kiyganda ehtiyot bo'laman."}, {"id": "t7-g1-13", "stem": "この犬は、こわい顔をしていますが、本当は優しいので、（　）ください。", "options": ["こわくならないで", "こわくしないで", "こわがられないでいて", "こわがらないで"], "answer": 4, "explanation_uz": "〜がる = ...lik his qilmoq. こわがる = qo'rqmoq → こわがらないで", "tr": "Bu it qo'rqinchli ko'rinadi, lekin aslida yuvosh, shuning uchun qo'rqmang."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t7-g2-14", "options": ["かわりに", "私が", "作る", "晩ごはんを"], "answer": 3, "prefix": "今日は", "suffix": "あなたはそうじをしてよ。", "starPos": 3, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: 私が晩ごはんを作るかわりに", "tr": "To'g'ri jumla: «Bugun men kechki ovqat qilish o'rniga, sen uy yig'ishtir.»"}, {"id": "t7-g2-15", "options": ["うれしく", "かかれた", "お目に", "ことを"], "answer": 2, "prefix": "「はじめまして。", "suffix": "存じます。」", "starPos": 2, "order": [3, 2, 4, 1], "explanation_uz": "To'g'ri tartib: お目にかかれたことをうれしく (お目にかかる = «ko'rishmoq» ning kamtarlik shakli)", "tr": "To'g'ri jumla: «Tanishganimdan xursandman (siz bilan ko'rishganimdan mamnunman).»"}, {"id": "t7-g2-16", "options": ["限り", "ある", "仕事が", "としても"], "answer": 2, "prefix": "私は、何歳になった", "suffix": "働き続けたいです。", "starPos": 3, "order": [4, 3, 2, 1], "explanation_uz": "To'g'ri tartib: としても仕事があるかぎり", "tr": "To'g'ri jumla: «Necha yoshga kirsam ham, ish bor ekan, ishlashda davom etgim keladi.»"}, {"id": "t7-g2-17", "options": ["上で", "別れる", "とうとう", "話し合った"], "answer": 1, "prefix": "2人は、何度も", "suffix": "ことを決めた。", "starPos": 2, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: 話し合った上でとうとう別れる (〜上で = ...gandan keyin/asosida)", "tr": "To'g'ri jumla: «Ikkovi ko'p marta gaplashib olgandan so'ng, oxir-oqibat ajrashishga qaror qilishdi.»"}, {"id": "t7-g2-18", "options": ["関する", "資料", "新しい", "最も"], "answer": 3, "prefix": "これは、現在のわが国の環境問題に", "suffix": "です。", "starPos": 3, "order": [1, 4, 3, 2], "explanation_uz": "To'g'ri tartib: 関する最も新しい資料 (〜に関する = ...ga oid)", "tr": "To'g'ri jumla: «Bu — mamlakatimizning hozirgi ekologik muammolariga oid eng yangi hujjat (material).»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "商店街の新しい名前が決まる", "passage": "ある商店街が、商店街の新しい名前を募集した。すると約1000通{{19}}応募があった。その中から、商店街の店のオーナーたちが話し合って、いちばんいいものを選んで、商店街の新しい名前が決まった。\nその新しい名前は、「キウイ通り」という。今までは、その町の古い地名から、「古川通り」と呼ばれていたので、{{20a}}、古くからここに住んでいる人にとっては驚くような名前{{20b}}。若者も集まるような明るく元気のある名前にしようと、特産物であるくだもののキウイをもとにした今回の名前が決まった。\nこの商店街は、約100年以上も前からあるという古い通りだ。{{21}}、最近建物や道路が古くなってきて、夜にはバイクに乗った若者たちが集まってさわいだり、犯罪が発生したりと様々な問題が起きるようになっていた。また、近くに大きなショッピングセンターができ、お客も減ってしまった。今回、商店街の人たちが{{22}}のは、昔のように活気がある通りにするための作戦の1つだという。お店の人々は新しい名前の効果ができるだけ早く出ることを{{23}}。", "passage_tr": "Bir savdo rastasi (shopping street) o'ziga yangi nom uchun tanlov e'lon qildi. Shunda taxminan 1000  taga YAQIN ariza keldi. Ular ichidan rasta do'konlari egalari maslahatlashib, eng yaxshisini tanlab, rastaning yangi nomi belgilandi. Yangi nom — «Kivi ko'chasi». Ilgari shaharning eski joy nomidan «Furukawa ko'chasi» deb atalardi, shuning uchun, EHTIMOL, azaldan shu yerda yashab kelayotganlar uchun bu hayratlanarli nom BO'LSA KERAK. Yoshlar ham yig'iladigan yorqin, quvnoq nom bo'lsin deb, mahalliy mahsulot — kivi mevasiga asoslangan bu nom tanlandi. Bu savdo rastasi 100 yildan ko'proq oldindan mavjud eski ko'cha. ASLIDA esa, so'nggi paytda bino va yo'llar eskirib, kechalari mototsiklli yoshlar yig'ilib shovqin solishi yoki jinoyat sodir bo'lishi kabi turli muammolar kelib chiqayotgan edi. Yana, yaqinda katta savdo markazi paydo bo'lib, mijozlar ham kamayib ketdi. Bu safar rasta ahli NOMNI O'ZGARTIRGANI — ilgarigiday gavjum ko'chaga aylantirish uchun qilingan rejalardan biri ekan. Do'kon egalari yangi nomning samarasi iloji boricha tezroq chiqishini TILAYOTGANIGA SHUBHA YO'Q.", "questions": [{"id": "t7-g3-19", "options": ["しか", "もの", "すら", "さえ"], "answer": 2, "blankNo": "19", "explanation_uz": "数量+もの = ...cha (ko'plikni ta'kidlash)", "tr": "約1000通[もの]応募 = ~1000 taga yaqin (shuncha ko'p) ariza."}, {"id": "t7-g3-20", "options": ["もしも ／ だろう", "もしかすると ／ かもしれない", "もしや ／ だったのだ", "もしかしたら ／ だということだ"], "answer": 2, "blankNo": "20", "explanation_uz": "もしかすると〜かもしれない = ehtimol ...bo'lishi mumkin", "tr": "[もしかすると]…驚くような名前[かもしれない] = EHTIMOL…hayratlanarli nom BO'LSA KERAK."}, {"id": "t7-g3-21", "options": ["だからといって", "実は", "それとも", "または"], "answer": 2, "blankNo": "21", "explanation_uz": "実は = aslida, rostini aytsa (ichki holatni ochish)", "tr": "[実は]、最近建物や道路が古くなって… = ASLIDA esa, yaqinda bino-yo'llar eskirib…"}, {"id": "t7-g3-22", "options": ["名前を変えた", "名前が変わった", "名前を変えずにいた", "名前が変わっていた"], "answer": 1, "blankNo": "22", "explanation_uz": "名前を変えた = nomni o'zgartirdi (odamlar — o'timli fe'l, harakat egasi bor)", "tr": "商店街の人たちが[名前を変えた]のは…作戦の1つ = rasta ahli NOMNI O'ZGARTIRGANI…rejalardan biri."}, {"id": "t7-g3-23", "options": ["祈っているにちがいない", "祈っている一方だ", "祈りたいにすぎない", "祈りたいものだ"], "answer": 1, "blankNo": "23", "explanation_uz": "〜にちがいない = ...ligi shubhasiz, albatta ...dir", "tr": "効果が早く出ることを[祈っているにちがいない] = samara tez chiqishini TILAYOTGANIGA SHUBHA YO'Q."}]}]}]}, "8": {"id": 8, "title_jp": "第8回 模擬テスト", "title_uz": "8-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t8-v1-1", "stem": "大きな鳥が【飛んで】いるのを見ました。", "options": ["あそんで", "よんで", "とんで", "さけんで"], "answer": 3, "reading": "とんで", "explanation_uz": "飛ぶ → とぶ (uchmoq)", "tr": "Katta qush uchib yurganini ko'rdim."}, {"id": "t8-v1-2", "stem": "子どもは、【無料】で入れます。", "options": ["むりょ", "むりょう", "ぶりょ", "ぶりょう"], "answer": 2, "reading": "むりょう", "explanation_uz": "無料 → むりょう (bepul, tekin)", "tr": "Bolalar bepul kirishlari mumkin."}, {"id": "t8-v1-3", "stem": "この道は、車の【通行】ができない。", "options": ["とうこう", "とうごう", "つうこう", "つうごう"], "answer": 3, "reading": "つうこう", "explanation_uz": "通行 → つうこう (yurish, qatnov, o'tish)", "tr": "Bu yo'ldan mashina o'tolmaydi."}, {"id": "t8-v1-4", "stem": "彼は、とても【疲れて】いるようだ。", "options": ["つかれて", "あきれて", "くたびれて", "おそれて"], "answer": 1, "reading": "つかれて", "explanation_uz": "疲れる → つかれる (charchamoq)", "tr": "U juda charchaganga o'xshaydi."}, {"id": "t8-v1-5", "stem": "この計画には、悪いところもあるが、よい【面】もある。", "options": ["てん", "めん", "へん", "けん"], "answer": 2, "reading": "めん", "explanation_uz": "面 → めん (tomon, yuza, jihat)", "tr": "Bu rejaning yomon tomonlari ham, yaxshi tomoni ham bor."}, {"id": "t8-v1-6", "stem": "友だちの【知恵】を借りて、課題を完成させました。", "options": ["ちえ", "ちしき", "ちせい", "ちのう"], "answer": 1, "reading": "ちえ", "explanation_uz": "知恵 → ちえ (aql, zakovat, tadbir)", "tr": "Do'stimning aqlidan (maslahatidan) foydalanib, vazifani tugatdim."}, {"id": "t8-v1-7", "stem": "現代には【多様】な生き方がある。", "options": ["おおさま", "たさま", "おおよう", "たよう"], "answer": 4, "reading": "たよう", "explanation_uz": "多様 → たよう (xilma-xil, turli-tuman)", "tr": "Hozirgi zamonda turli-tuman yashash tarzi bor."}, {"id": "t8-v1-8", "stem": "荷物は、きのう【到着】しました。", "options": ["とちゃく", "とうちゃく", "どちゃく", "どうちゃく"], "answer": 2, "reading": "とうちゃく", "explanation_uz": "到着 → とうちゃく (yetib kelish, manzilga yetish)", "tr": "Yuk kecha yetib keldi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t8-v2-9", "stem": "その決定に、【ふまん】を言う人がたくさんいた。", "options": ["否満", "無満", "不満", "未満"], "answer": 3, "explanation_uz": "ふまん → 不満 (norozilik)", "tr": "Bu qarordan norozilik bildirgan odamlar ko'p edi."}, {"id": "t8-v2-10", "stem": "駅前でビルを【けんちく】している。", "options": ["建設", "建造", "建立", "建築"], "answer": 4, "explanation_uz": "けんちく → 建築 (qurilish, me'morchilik)", "tr": "Bekat oldida bino qurilyapti."}, {"id": "t8-v2-11", "stem": "旅行をして自宅に【もどって】、安心した。", "options": ["戻って", "帰って", "返って", "来って"], "answer": 1, "explanation_uz": "もどる → 戻る (qaytmoq, qaytib kelmoq)", "tr": "Sayohatdan o'z uyimga qaytib, xotirjam bo'ldim."}, {"id": "t8-v2-12", "stem": "校則違反を【みとめる】ことはできない。", "options": ["求める", "救める", "許める", "認める"], "answer": 4, "explanation_uz": "みとめる → 認める (tan olmoq, e'tirof etmoq)", "tr": "Maktab qoidasini buzishni tan olib (ruxsat berib) bo'lmaydi."}, {"id": "t8-v2-13", "stem": "東京の【こうがい】に家を買いました。", "options": ["郊外", "戸外", "口外", "校外"], "answer": 1, "explanation_uz": "こうがい → 郊外 (shahar chekkasi, atrof)", "tr": "Tokio chekkasida (atrofida) uy sotib oldim."}, {"id": "t8-v2-14", "stem": "今月の【やちん】を払った。", "options": ["家貸", "屋貸", "家賃", "屋賃"], "answer": 3, "explanation_uz": "やちん → 家賃 (uy ijara haqi)", "tr": "Shu oylik uy ijara haqini to'ladim."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t8-v3-15", "stem": "現代社会では、だれもが（　）を感じている。", "options": ["センス", "センチメンタル", "ストレス", "ニュアンス"], "answer": 3, "explanation_uz": "ストレス = stress, ruhiy zo'riqish", "tr": "Hozirgi jamiyatda hamma stress his qiladi."}, {"id": "t8-v3-16", "stem": "書類のこの部分を（　）してください。", "options": ["変更", "変化", "変革", "変身"], "answer": 1, "explanation_uz": "変更 = o'zgartirish (rejani, ma'lumotni)", "tr": "Hujjatning bu qismini o'zgartiring."}, {"id": "t8-v3-17", "stem": "会社に入るために、（　）を受けた。", "options": ["対応", "対面", "面接", "応対"], "answer": 3, "explanation_uz": "面接 = suhbat, intervyu", "tr": "Kompaniyaga kirish uchun suhbatdan o'tdim."}, {"id": "t8-v3-18", "stem": "海に（　）、魚をとった。", "options": ["しずんで", "もぐって", "わたって", "ころんで"], "answer": 2, "explanation_uz": "もぐる = sho'ng'imoq, suvga sho'ng'imoq", "tr": "Dengizga sho'ng'ib, baliq tutdim."}, {"id": "t8-v3-19", "stem": "私の（　）は、人とすぐになかよくなれることです。", "options": ["高所", "低所", "長所", "短所"], "answer": 3, "explanation_uz": "長所 = yaxshi tomon, fazilat", "tr": "Mening yaxshi tomonim — odamlar bilan tez til topisha olishim."}, {"id": "t8-v3-20", "stem": "生まれた国を（　）、10年ほどたった。", "options": ["渡って", "乗り越えて", "曲がって", "離れて"], "answer": 4, "explanation_uz": "離れる = ajralmoq, uzoqlashmoq, tark etmoq", "tr": "Tug'ilgan mamlakatimni tark etib, 10 yilcha bo'ldi."}, {"id": "t8-v3-21", "stem": "私の趣味は、プラモデルを（　）ことです。", "options": ["まとめあげる", "組み立てる", "立てかける", "作り置く"], "answer": 2, "explanation_uz": "組み立てる = yig'moq, qismlardan qurmoq", "tr": "Mening sevimli mashg'ulotim — plastik modellarni yig'ish (qurib chiqish)."}, {"id": "t8-v3-22", "stem": "マラソン大会に参加する人は、参加（　）を払ってください。", "options": ["価", "金", "料", "値"], "answer": 3, "explanation_uz": "参加料 = ishtirok haqi (〜料 = haq, to'lov)", "tr": "Marafon musobaqasida qatnashadiganlar ishtirok haqini to'lasin."}, {"id": "t8-v3-23", "stem": "あの人の仕事は、雑誌の（　）です。", "options": ["設立", "保護", "整備", "編集"], "answer": 4, "explanation_uz": "編集 = tahrir qilish, muharrirlik", "tr": "U odamning ishi — jurnal tahririyati (muharrirligi)."}, {"id": "t8-v3-24", "stem": "ものごとをよく（　）してみましょう。", "options": ["感動", "観察", "関係", "熱中"], "answer": 2, "explanation_uz": "観察 = kuzatish, kuzatuv", "tr": "Narsalarni yaxshilab kuzatib ko'raylik."}, {"id": "t8-v3-25", "stem": "山本さんは、（　）で、うそをつかない人です。", "options": ["軽薄", "派手", "地味", "誠実"], "answer": 4, "explanation_uz": "誠実 = halol, samimiy, vijdonli", "tr": "Yamamoto-san halol (samimiy), yolg'on gapirmaydigan odam."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t8-v4-26", "stem": "彼女は、とても【わがままだ】。", "options": ["親切だ", "勝手だ", "優しい", "冷たい"], "answer": 2, "explanation_uz": "わがまま = o'zboshimcha, injiq → 勝手だ (o'zicha ish qiladigan)", "tr": "U juda o'zboshimcha (injiq)."}, {"id": "t8-v4-27", "stem": "私はその話を【全然】知らなかった。", "options": ["今まで", "そのときは", "二度と", "少しも"], "answer": 4, "explanation_uz": "全然〜ない = umuman/mutlaqo ...emas → 少しも〜ない (zarracha ham emas)", "tr": "Men bu gapni mutlaqo bilmasdim."}, {"id": "t8-v4-28", "stem": "商売でお金を【もうけた】。", "options": ["得た", "なくした", "借りた", "貸した"], "answer": 1, "explanation_uz": "もうける = foyda qilmoq, pul ishlamoq → 得た (qo'lga kiritdi)", "tr": "Savdoda pul ishladim (topdim)."}, {"id": "t8-v4-29", "stem": "質問があれば、【どんどん】聞いてください。", "options": ["よく考えてから", "遠慮しないで", "みんな一緒に", "全部まとめて"], "answer": 2, "explanation_uz": "どんどん = bemalol, ketma-ket, tortinmay → 遠慮しないで", "tr": "Savolingiz bo'lsa, tortinmasdan so'rayvering."}, {"id": "t8-v4-30", "stem": "先輩に【アドバイス】をもらった。", "options": ["命令", "お礼", "助言", "心配"], "answer": 3, "explanation_uz": "アドバイス = maslahat → 助言", "tr": "Kattadan (sempaydan) maslahat oldim."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t8-v5-31", "stem": "ためす", "options": ["試験中にうで時計を見て、時間をためした。", "将来はお金をためして、大きな家をたてるつもりです。", "古い自転車をためして、乗れるようになった。", "日本語の力をためすために、テストを受けようと思います。"], "answer": 4, "optsTr": ["Imtihon paytida qo'l soatga qarab, vaqtni 'sinadim' (noto'g'ri — 確認 kerak).", "Kelajakda pulni 'sinab', katta uy quraman (noto'g'ri — ためる/jamg'armoq kerak).", "Eski velosipedni 'sinab', minadigan bo'ldim (noto'g'ri — 直す kerak).", "Yapon tili kuchimni sinash uchun test topshirmoqchiman. (to'g'ri)"], "tr": "ためす(試す) = sinab ko'rmoq, tekshirib ko'rmoq."}, {"id": "t8-v5-32", "stem": "アンケート", "options": ["コンサートの終わりに何度もアンケートがあって、盛り上がった。", "大学生活についてのアンケートに質問した。", "運動不足なので、友だちとアンケートをしに行った。", "クラス全員にアンケートを取って、やり方を決めた。"], "answer": 4, "optsTr": ["Konsert oxirida ko'p marta 'so'rovnoma' bo'lib, qizib ketdi (noto'g'ri — アンコール kerak).", "Universitet hayoti haqidagi 'so'rovnoma'ga savol berdim (noto'g'ri).", "Sport yetishmaganidan, do'stim bilan 'so'rovnoma' qilgani bordik (noto'g'ri).", "Sinfdagi hammadan so'rovnoma olib, usulni belgiladik. (to'g'ri)"], "tr": "アンケート = so'rovnoma, anketa."}, {"id": "t8-v5-33", "stem": "配る", "options": ["買い物のとき、レジでお金を配った。", "テスト用紙を全員に配ってください。", "きのうは母の誕生日だったので、母にプレゼントを配りました。", "このパソコンは、作動が早く配られている。"], "answer": 2, "optsTr": ["Xarid paytida kassada pulni 'tarqatdim' (noto'g'ri — 払う kerak).", "Test qog'ozlarini hammaga tarqating. (to'g'ri)", "Kecha onamning tug'ilgan kuni edi, onamga sovg'a 'tarqatdim' (noto'g'ri — あげる kerak).", "Bu kompyuter ishlashi tez 'tarqatilgan' (noto'g'ri)."], "tr": "配る = tarqatmoq, ulashmoq."}, {"id": "t8-v5-34", "stem": "係", "options": ["うちの子どもは、クラスのそうじの係だ。", "田中さんと鈴木さんは係がよくない。", "これは、野菜に見えますが、果物の係です。", "私の係は、会社員です。"], "answer": 1, "optsTr": ["Mening bolam sinfning tozalik mas'uli (navbatchisi). (to'g'ri)", "Tanaka va Suzuki 'mas'uli' yaxshi emas (noto'g'ri — 仲 kerak).", "Bu sabzavotga o'xshaydi, lekin mevaning 'mas'uli' (noto'g'ri — 仲間/種類 kerak).", "Mening 'mas'ulim' — kompaniya xodimi (noto'g'ri — 仕事/職業 kerak)."], "tr": "係(かかり) = mas'ul (xodim), navbatchi, vazifa egasi."}, {"id": "t8-v5-35", "stem": "挑戦", "options": ["今年は、新しい仕事に挑戦してみたい。", "強い選手とテニスの挑戦をして、負けた。", "人と出会う挑戦は、多ければ多いほどいい。", "あの2人は仲が悪くて、いつも挑戦している。"], "answer": 1, "optsTr": ["Bu yil yangi ishga urinib ko'rmoqchiman (challenge qilmoqchiman). (to'g'ri)", "Kuchli o'yinchi bilan tennis 'challenge'i qilib, yutqazdim (noto'g'ri — 試合 kerak).", "Odam bilan uchrashish 'challenge'i ko'p bo'lsa yaxshi (noto'g'ri — 機会 kerak).", "U ikkovi yomon, doim 'challenge' qiladi (noto'g'ri — けんか kerak)."], "tr": "挑戦(ちょうせん) = sinov, urinib ko'rish, da'vat (challenge)."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t8-g1-1", "stem": "松田「今日、飲み会に行く?」竹中「明日のテストの準備もある（　）、今日は行かないよ。」", "options": ["けど", "と", "し", "まで"], "answer": 3, "explanation_uz": "〜し = ...-u, ham (sabablarni sanash)", "tr": "Matsuda: «Bugun ziyofatga borasanmi?» Takenaka: «Ertangi testga tayyorgarlik ham bor-u, bugun bormayman.»"}, {"id": "t8-g1-2", "stem": "料理がまずく、店員の態度も悪い。（　）店には二度と行きたくない。", "options": ["あんな", "どんな", "ある", "どの"], "answer": 1, "explanation_uz": "あんな = unaqa, bunaqa (salbiy holatga ishora)", "tr": "Ovqati ham bemaza, xodimning muomalasi ham yomon. Bunday do'konga ikkinchi bormayman."}, {"id": "t8-g1-3", "stem": "この町は、富士山がよく見える（　）、富士見町という名前が付いた。", "options": ["ことに", "ことから", "ことを", "ことは"], "answer": 2, "explanation_uz": "〜ことから = ...ligi sababli, shu sababdan", "tr": "Bu shaharchadan Fuji tog'i yaxshi ko'rinishi sababli, Fujimi-machi degan nom berilgan."}, {"id": "t8-g1-4", "stem": "いくらいそがしい（　）、まったく運動しないのは、体によくない。", "options": ["からして", "からといって", "からには", "からあって"], "answer": 2, "explanation_uz": "〜からといって = ...deb (shu bahonada ham)", "tr": "Qanchalik band bo'lsang ham, mutlaqo sport qilmaslik salomatlik uchun yomon."}, {"id": "t8-g1-5", "stem": "すべての大学生が、（　）まじめに勉強しているわけではない。", "options": ["かわりに", "かろうじて", "かえって", "かならずしも"], "answer": 4, "explanation_uz": "かならずしも〜わけではない = har doim ham ...emas", "tr": "Hamma talaba ham albatta tirishib o'qiydi, deb bo'lmaydi."}, {"id": "t8-g1-6", "stem": "今日はとても暑いので、プールで泳ぎたくて（　）。", "options": ["しかたない", "しない", "できない", "かぎらない"], "answer": 1, "explanation_uz": "〜たくてしかたない = ...gisi kelib chidab bo'lmaslik", "tr": "Bugun juda issiq, basseynda suzgim kelib chidab bo'lmayapti."}, {"id": "t8-g1-7", "stem": "男の学生「空港までは2時間かかるから、8時に（　）10時に着くね。」", "options": ["出発し", "出発すれば", "出発しようと", "出発するのは"], "answer": 2, "explanation_uz": "〜ば = ...sa (shart)", "tr": "O'g'il bola: «Aeroportga 2 soat ketadi, shuning uchun 8 da jo'nasak, 10 da yetib boramiz.»"}, {"id": "t8-g1-8", "stem": "先生がみんなに、「このゼミの生徒は優秀ですね」と（　）。", "options": ["おっしゃいました", "うかがいました", "申しました", "申し上げました"], "answer": 1, "explanation_uz": "おっしゃる = 言う ning hurmat shakli (dedilar)", "tr": "O'qituvchi hammaga: «Bu seminardagi talabalar a'lo ekan» dedilar."}, {"id": "t8-g1-9", "stem": "2時からの会議のために、資料を用意（　）ください。", "options": ["することになって", "しておいて", "するようになって", "してくれて"], "answer": 2, "explanation_uz": "〜ておく = oldindan ...qilib qo'ymoq", "tr": "Soat 2 dagi yig'ilish uchun, hujjatlarni oldindan tayyorlab qo'ying."}, {"id": "t8-g1-10", "stem": "残念ながら、この実験は失敗だと（　）。", "options": ["言わないではない", "言わないでもない", "言わざるが得ない", "言わざるを得ない"], "answer": 4, "explanation_uz": "〜ざるを得ない = ...maslikning iloji yo'q, ...ishga majbur", "tr": "Afsuski, bu tajriba muvaffaqiyatsiz deb aytmaslikning iloji yo'q."}, {"id": "t8-g1-11", "stem": "これは、ずっと前に私が作った作品に（　）。", "options": ["まちがいます", "まちがいではありません", "ちがいます", "ちがいありません"], "answer": 4, "explanation_uz": "〜にちがいない = ...ligiga shubha yo'q, albatta ...dir", "tr": "Bu — ancha oldin men yaratgan asar ekaniga shubha yo'q."}, {"id": "t8-g1-12", "stem": "苦しいことのあとにいいことがあるのが、（　）と思います。", "options": ["人生という点だ", "人生というところだ", "人生というものだ", "人生というままだ"], "answer": 3, "explanation_uz": "〜というものだ = ...degani shu (umumiy haqiqatni aytish)", "tr": "Qiyinchilikdan keyin yaxshilik bo'lishi — hayot degani shu, deb o'ylayman."}, {"id": "t8-g1-13", "stem": "チェックアウトの時間に間に合わず、ホテルに追加でお金を（　）。", "options": ["払わせることになった", "払わすようにした", "払うはめになった", "払わせるようにした"], "answer": 3, "explanation_uz": "〜はめになる = (noxush) ...holatga tushib qolmoq", "tr": "Chiqish (checkout) vaqtiga ulgurmay, mehmonxonaga qo'shimcha pul to'lashga majbur bo'lib qoldim."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t8-g2-14", "options": ["通りに", "書いて", "ある", "やってみて"], "answer": 1, "prefix": "「私もよくわからないから、説明書に", "suffix": "よ。」", "starPos": 3, "order": [2, 3, 1, 4], "explanation_uz": "To'g'ri tartib: 書いてあるとおりにやってみて", "tr": "To'g'ri jumla: «Men ham yaxshi bilmayman, qo'llanmada yozilganday qilib ko'r-chi.»"}, {"id": "t8-g2-15", "options": ["なりたい", "お見せ", "ようでしたら", "ごらんに"], "answer": 3, "prefix": "こちらが、私が集めている車のカタログですが、", "suffix": "しますよ。", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: ごらんになりたいようでしたらお見せ (ごらんになる = «ko'rmoq» hurmat shakli)", "tr": "To'g'ri jumla: «Mana, men yig'ayotgan mashina kataloglari, ko'rmoqchi bo'lsangiz, ko'rsataman.»"}, {"id": "t8-g2-16", "options": ["簡単な", "軽い", "上", "ので"], "answer": 2, "prefix": "この新しいそうじ機は、使い方が", "suffix": "とても便利だ。", "starPos": 3, "order": [1, 3, 2, 4], "explanation_uz": "To'g'ri tartib: 簡単な上軽いので (〜上 = ...gani ustiga)", "tr": "To'g'ri jumla: «Bu yangi changyutgich foydalanish oson bo'lgani ustiga, yengil bo'lgani uchun juda qulay.»"}, {"id": "t8-g2-17", "options": ["という", "では", "好きだ", "わけ"], "answer": 4, "prefix": "日本人だからといって、だれもがすしや天ぷらが", "suffix": "ない。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: 好きだというわけではない (〜というわけではない = ...degani emas)", "tr": "To'g'ri jumla: «Yapon bo'lgani uchun ham, hamma sushi yoki tempurani yaxshi ko'radi degani emas.»"}, {"id": "t8-g2-18", "options": ["反する", "だけ", "こと", "に"], "answer": 3, "prefix": "若いころの私は、両親の期待", "suffix": "していた。", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: に反することだけ (〜に反する = ...ga zid)", "tr": "To'g'ri jumla: «Yoshligimda men ota-onamning umidiga zid ishlarnigina qilardim.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "働く女性のためのセミナー", "passage": "今度の日曜日に、働く女性を応援するためのセミナー、「ジョブ・セミナー 働く女性の新しい生き方」の第1回目の講座が、駅前の市民ホールで行われる予定です。\n現代の働く女性には、会社員、母、妻、娘など、いろいろな役割があり、いそがしい人が増えています。しかし以前よりいそがしくなった{{19a}}、手伝ってくれる人がいないのが{{19b}}。このセミナーでは、さまざまな業界で活躍されている女性が講師となり、全5回の予定で、{{20}}女性の生き方、上手な働き方を参加者とともに考えていきます。ただ講演を聞く{{21}}、質問をしたり、意見を言える方を募集します。\n第1回目の講師は、会社を経営する森川花子さんです。「仕事を持つ女性の時間の使い方」をテーマにセミナーを行います。講演のあとに、講師と参加者の方々が交流することができるパーティーもあります。\n第2回目{{22}}講師の予定など、その他の内容については、市民ホールのホームページで公開しています。参加をご希望の方は、市民ホール事務所まで直接電話でお申し込みください。みなさまのご参加を{{23}}。", "passage_tr": "Kelasi yakshanba kuni, ishlaydigan ayollarni qo'llab-quvvatlash uchun «Job-seminar: ishlaydigan ayolning yangi hayot tarzi» seminarining 1-mashg'uloti bekat oldidagi shahar zalida o'tkaziladi. Hozirgi ishlaydigan ayolning kompaniya xodimi, ona, xotin, qiz kabi turli rollari bor va band odamlar ko'paymoqda. Biroq ilgarigidan band bo'lib qolganiga QARAMAY, yordam beradigan odam yo'qligi — HOZIRGI AHVOL. Bu seminarda turli sohalarda faoliyat yuritayotgan ayollar o'qituvchi bo'lib, jami 5 marta o'tkazilishi rejalashtirilgan; KELAJAKDAGI ayol hayoti va mohirona ishlash usulini ishtirokchilar bilan birga o'ylab ko'ramiz. Shunchaki ma'ruza eshitishnigina EMAS, balki savol bera oladigan, fikr bildira oladigan kishilarni taklif qilamiz. 1-mashg'ulot o'qituvchisi — kompaniya rahbari Morikava Xanako. «Ishlaydigan ayolning vaqtdan foydalanishi» mavzusida seminar o'tkazadi. Ma'ruzadan keyin o'qituvchi va ishtirokchilar muloqot qila oladigan ziyofat ham bor. 2-mashg'ulot va undan KEYINGI o'qituvchilar rejasi kabi boshqa ma'lumotlar shahar zali veb-saytida e'lon qilingan. Qatnashmoqchi bo'lganlar shahar zali idorasiga to'g'ridan-to'g'ri telefon orqali murojaat qilsin. Barchangizning ishtirokingizni KUTIB QOLAMIZ.", "questions": [{"id": "t8-g3-19", "options": ["からには ／ 結論です", "ことから ／ 感想です", "からといって ／ 満足です", "にもかかわらず ／ 現状です"], "answer": 4, "blankNo": "19", "explanation_uz": "〜にもかかわらず = ...ga qaramay; 現状です = hozirgi ahvol", "tr": "いそがしくなった[にもかかわらず]…いないのが[現状です] = band bo'lganiga QARAMAY…yo'qligi HOZIRGI AHVOL."}, {"id": "t8-g3-20", "options": ["これからの", "あれからの", "こちらからの", "あちらからの"], "answer": 1, "blankNo": "20", "explanation_uz": "これからの = bundan keyingi, kelajakdagi", "tr": "[これからの]女性の生き方 = KELAJAKDAGI ayol hayoti."}, {"id": "t8-g3-21", "options": ["だけであり", "だけであれば", "だけでなく", "だけでなければ"], "answer": 3, "blankNo": "21", "explanation_uz": "〜だけでなく = faqat ...emas, balki (ham)", "tr": "講演を聞く[だけでなく]、質問をしたり… = ma'ruza eshitishnigina EMAS, balki savol ham berib…"}, {"id": "t8-g3-22", "options": ["未満の", "方面の", "以上の", "以降の"], "answer": 4, "blankNo": "22", "explanation_uz": "〜以降 = ...dan keyin, ...dan boshlab", "tr": "第2回目[以降の]講師の予定 = 2-mashg'ulot va undan KEYINGI o'qituvchilar rejasi."}, {"id": "t8-g3-23", "options": ["待たれます", "お待ちでいらっしゃいます", "お待ちいたしております", "お待ちくださいます"], "answer": 3, "blankNo": "23", "explanation_uz": "お待ちいたしております = «kutmoq» ning kamtarlik (謙譲) shakli", "tr": "みなさまのご参加を[お待ちいたしております] = ishtirokingizni KUTIB QOLAMIZ (kamtarlik)."}]}]}]}, "9": {"id": 9, "title_jp": "第9回 模擬テスト", "title_uz": "9-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t9-v1-1", "stem": "パーティーを開くので、部屋をきれいに【飾って】おく。", "options": ["ぬって", "しまって", "かざって", "あらって"], "answer": 3, "reading": "かざって", "explanation_uz": "飾る → かざる (bezamoq)", "tr": "Ziyofat o'tkazaman, shuning uchun xonani chiroyli bezab qo'yaman."}, {"id": "t9-v1-2", "stem": "材料は、【各自】で用意してください。", "options": ["かくし", "かくじ", "きゃくし", "きゃくじ"], "answer": 2, "reading": "かくじ", "explanation_uz": "各自 → かくじ (har kim o'zi, har biri)", "tr": "Materiallarni har kim o'zi tayyorlasin."}, {"id": "t9-v1-3", "stem": "ここが世界一大きな【湖】です。", "options": ["みずうみ", "いけ", "ぬま", "たき"], "answer": 1, "reading": "みずうみ", "explanation_uz": "湖 → みずうみ (ko'l)", "tr": "Bu yer dunyodagi eng katta ko'l."}, {"id": "t9-v1-4", "stem": "家の外で猫が【鳴いて】いる。", "options": ["きいて", "たたいて", "ないて", "さいて"], "answer": 3, "reading": "ないて", "explanation_uz": "鳴く → なく (sayramoq, miyovlamoq — hayvon ovozi)", "tr": "Uy tashqarisida mushuk miyovlayapti."}, {"id": "t9-v1-5", "stem": "【屋上】から町がよく見えます。", "options": ["やしょう", "やじょう", "おくしょう", "おくじょう"], "answer": 4, "reading": "おくじょう", "explanation_uz": "屋上 → おくじょう (tom, bino usti)", "tr": "Tomdan shahar yaxshi ko'rinadi."}, {"id": "t9-v1-6", "stem": "ここを車が【通過】することはできません。", "options": ["つうか", "つうが", "とうか", "とうが"], "answer": 1, "reading": "つうか", "explanation_uz": "通過 → つうか (o'tib ketish)", "tr": "Bu yerdan mashina o'tib keta olmaydi."}, {"id": "t9-v1-7", "stem": "きのうからずっと【歯】が痛い。", "options": ["ば", "は", "し", "じ"], "answer": 2, "reading": "は", "explanation_uz": "歯 → は (tish)", "tr": "Kechadan beri tishim og'riyapti."}, {"id": "t9-v1-8", "stem": "大きな車輪が【回転】する。", "options": ["てんかい", "てんがい", "かいてん", "かいでん"], "answer": 3, "reading": "かいてん", "explanation_uz": "回転 → かいてん (aylanish)", "tr": "Katta g'ildirak aylanadi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t9-v2-9", "stem": "やり方は、【きそく】で決まっています。", "options": ["基則", "規則", "基測", "規測"], "answer": 2, "explanation_uz": "きそく → 規則 (qoida, tartib)", "tr": "Tartib qoida bilan belgilangan."}, {"id": "t9-v2-10", "stem": "あの2人の【ゆうじょう】は、すばらしい。", "options": ["有情", "愛情", "友情", "真情"], "answer": 3, "explanation_uz": "ゆうじょう → 友情 (do'stlik)", "tr": "U ikki kishining do'stligi ajoyib."}, {"id": "t9-v2-11", "stem": "赤ちゃんにセーターとマフラーを【あんだ】。", "options": ["編んだ", "練んだ", "絡んだ", "結んだ"], "answer": 1, "explanation_uz": "あむ → 編む (to'qimoq)", "tr": "Chaqaloqqa sviter va sharf to'qidim."}, {"id": "t9-v2-12", "stem": "わが社では、大事なことは【おもに】社長が決める。", "options": ["重に", "面に", "主に", "思に"], "answer": 3, "explanation_uz": "おもに → 主に (asosan, ko'pincha)", "tr": "Bizning kompaniyada muhim narsalarni asosan rahbar hal qiladi."}, {"id": "t9-v2-13", "stem": "仕事についての新しい【ちしき】を得た。", "options": ["意識", "認識", "常識", "知識"], "answer": 4, "explanation_uz": "ちしき → 知識 (bilim)", "tr": "Ish haqida yangi bilim oldim."}, {"id": "t9-v2-14", "stem": "犬と猫の【せわ】をする。", "options": ["世和", "施和", "世話", "施話"], "answer": 3, "explanation_uz": "せわ → 世話 (parvarish, qarash)", "tr": "It va mushukni parvarish qilaman."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t9-v3-15", "stem": "がんばれば、私にも（　）はあると思います。", "options": ["トップ", "ベスト", "チェンジ", "チャンス"], "answer": 4, "explanation_uz": "チャンス = imkoniyat, fursat", "tr": "Harakat qilsam, menda ham imkoniyat bor deb o'ylayman."}, {"id": "t9-v3-16", "stem": "人を年齢などによって（　）してはいけない。", "options": ["別離", "差別", "対立", "分別"], "answer": 2, "explanation_uz": "差別 = kamsitish, ajratish", "tr": "Odamni yoshi va shu kabilarga qarab kamsitmaslik kerak."}, {"id": "t9-v3-17", "stem": "1日の仕事の内容を必ず上司に（　）してください。", "options": ["出席", "結論", "移転", "報告"], "answer": 4, "explanation_uz": "報告 = hisobot, ma'lumot berish", "tr": "Kunlik ish mazmunini albatta boshliqqa hisobot qiling."}, {"id": "t9-v3-18", "stem": "彼は、この町を（　）行ってしまった。", "options": ["拾って", "去って", "終えて", "投げて"], "answer": 2, "explanation_uz": "去る = ketmoq, tark etmoq", "tr": "U bu shaharni tark etib ketib qoldi."}, {"id": "t9-v3-19", "stem": "レポートを専門（　）にきちんとチェックしてもらってください。", "options": ["員", "者", "家", "屋"], "answer": 3, "explanation_uz": "専門家 = mutaxassis (〜家 = ...shunos, kasb egasi)", "tr": "Hisobotni mutaxassisga yaxshilab tekshirtiring."}, {"id": "t9-v3-20", "stem": "大きなバケツに水を（　）ください。", "options": ["ためて", "のせて", "置いて", "投げて"], "answer": 1, "explanation_uz": "ためる = to'plamoq, jamlamoq (suyuqlik)", "tr": "Katta chelakka suv to'plang (yig'ing)."}, {"id": "t9-v3-21", "stem": "事故のニュースを聞いて、（　）を受けた。", "options": ["ダウン", "チャレンジ", "マイナス", "ショック"], "answer": 4, "explanation_uz": "ショックを受ける = shokka tushmoq", "tr": "Halokat xabarini eshitib, shok bo'ldim."}, {"id": "t9-v3-22", "stem": "出発する日、（　）にたくさんの人が来てくれた。", "options": ["見返し", "見知り", "見聞き", "見送り"], "answer": 4, "explanation_uz": "見送り = kuzatish, kuzatib qo'yish", "tr": "Jo'nash kunim kuzatgani ko'p odam keldi."}, {"id": "t9-v3-23", "stem": "先生に会ったので、（　）した。", "options": ["応援", "指導", "挨拶", "尊重"], "answer": 3, "explanation_uz": "挨拶 = salomlashish, ko'rishish", "tr": "O'qituvchini uchratganim uchun salomlashdim."}, {"id": "t9-v3-24", "stem": "その晩、私は、暖かいベッドで（　）眠った。", "options": ["あっさり", "ぐっすり", "さっぱり", "ぐったり"], "answer": 2, "explanation_uz": "ぐっすり眠る = qotib uxlamoq, maza qilib uxlamoq", "tr": "O'sha kechasi men issiq karavotda qotib (maza qilib) uxladim."}, {"id": "t9-v3-25", "stem": "このような（　）な資料をいただき、ありがとうございます。", "options": ["丈夫", "貴重", "地味", "派手"], "answer": 2, "explanation_uz": "貴重 = qimmatli, qadrli, noyob", "tr": "Bunday qimmatli (qadrli) hujjatni berganingiz uchun rahmat."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t9-v4-26", "stem": "彼女と家の近くで【再会】した。", "options": ["待ち合わせた", "また会った", "別れた", "約束した"], "answer": 2, "explanation_uz": "再会 = qayta uchrashish → また会った", "tr": "U bilan uy yaqinida qayta uchrashdim."}, {"id": "t9-v4-27", "stem": "子どもを見ていると、【はらはら】する。", "options": ["心配だ", "幸福だ", "期待する", "感動する"], "answer": 1, "explanation_uz": "はらはらする = hapriqmoq, xavotirlanmoq → 心配だ", "tr": "Bolaga qarab tursam, yuragim hapriqadi (xavotirlanaman)."}, {"id": "t9-v4-28", "stem": "木村は、今、【席をはずして】おります。", "options": ["そうじして", "とりかえて", "離れて", "戻ってきて"], "answer": 3, "explanation_uz": "席をはずす = joyini bo'shatmoq, o'rnida bo'lmaslik → 離れて", "tr": "Kimura hozir joyida yo'q (joyidan uzoqlashgan)."}, {"id": "t9-v4-29", "stem": "このホテルは【アクセス】がいい。", "options": ["目立つところにある", "地図にのっている", "とても人気がある", "交通が便利だ"], "answer": 4, "explanation_uz": "アクセスがいい = borish qulay → 交通が便利だ", "tr": "Bu mehmonxonaga borish qulay (transport qulay)."}, {"id": "t9-v4-30", "stem": "あの人は【正直】な人だ。", "options": ["うそをつかない", "とても優しい", "勉強ができる", "他人にきびしい"], "answer": 1, "explanation_uz": "正直 = halol, rostgo'y → うそをつかない", "tr": "U odam halol (rostgo'y) odam."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t9-v5-31", "stem": "つつむ", "options": ["テントがとばされないように、ロープでつつんだ。", "これはプレゼントなので、きれいな紙でつつんでください。", "やぶれた紙をセロテープでつつみました。", "雪が山の頂上をつつんでいる。"], "answer": 2, "optsTr": ["Chodir uchib ketmasin deb, arqon bilan 'o'radim' (noto'g'ri — しばる kerak).", "Bu sovg'a, shuning uchun chiroyli qog'ozga o'rang. (to'g'ri)", "Yirtilgan qog'ozni skotch bilan 'o'radim' (noto'g'ri — はる kerak).", "Qor tog' cho'qqisini 'o'rab' turibdi (noto'g'ri — おおう kerak)."], "tr": "つつむ(包む) = o'ramoq, o'rab qo'ymoq."}, {"id": "t9-v5-32", "stem": "こぼす", "options": ["急いでいたので、持っていたかばんをこぼしてしまった。", "時計を床に落としたらこぼしてしまった。", "電車の中にさいふをこぼしてしまい、後で取りに行った。", "シャツにコーヒーをこぼしたので、すぐに着替えた。"], "answer": 4, "optsTr": ["Shoshganim uchun, ko'tarib turgan sumkani 'to'kib yubordim' (noto'g'ri — 落とす kerak).", "Soatni polga tushirsam 'to'kildi' (noto'g'ri — 壊れる kerak).", "Poyezdda hamyonni 'to'kib', keyin olgani bordim (noto'g'ri — 忘れる kerak).", "Ko'ylakka kofe to'kib yuborganim uchun, darrov kiyim almashtirdim. (to'g'ri)"], "tr": "こぼす = to'kib yubormoq (suyuqlik/donador)."}, {"id": "t9-v5-33", "stem": "角", "options": ["部屋の角に植木が置いてあります。", "橋のまん中ではなく、角を渡ってください。", "転んだとき、テーブルの角で頭を打って、とても痛かった。", "その書類は、机の角に入っています。"], "answer": 3, "optsTr": ["Xona burchagiga (隅) tuvak qo'yilgan (noto'g'ri — 隅 kerak).", "Ko'prik o'rtasidan emas, 'burchakdan' o'ting (noto'g'ri).", "Yiqilganimda stol qirrasiga boshimni urib, juda og'ridi. (to'g'ri)", "U hujjat stolning 'burchagiga' solingan (noto'g'ri — 引き出し kerak)."], "tr": "角(かど) = burchak, qirra (chiqib turgan)."}, {"id": "t9-v5-34", "stem": "相手", "options": ["台所のテーブルの相手として、このいすを買いました。", "天気のいい日には、公園にたくさん相手が歩いている。", "さっきの電話の相手は、国の母親です。", "からい料理は、ごはんの相手にちょうどいい。"], "answer": 3, "optsTr": ["Oshxona stolining 'sherigi' sifatida bu stulni oldim (noto'g'ri).", "Havo yaxshi kunlari bog'da ko'p 'sherik' yuradi (noto'g'ri — 人 kerak).", "Hozirgi telefondagi suhbatdosh — yurtimdagi onam. (to'g'ri)", "Achchiq taom guruchga 'sherik' bo'ladi (noto'g'ri — あう kerak)."], "tr": "相手(あいて) = suhbatdosh, qarama-qarshi tomon, sherik."}, {"id": "t9-v5-35", "stem": "夢中", "options": ["彼は、自分の仕事に夢中で取り組んでいる。", "今朝は9時まで夢中で、目が覚めませんでした。", "寝不足のまま、夢中で運転するのは危ないです。", "試合に勝ったあとには、夢中で練習しないでください。"], "answer": 1, "optsTr": ["U o'z ishiga berilib ishlayapti. (to'g'ri)", "Bugun ertalab 9 gacha 'berilib', uyg'onmadim (noto'g'ri — ぐっすり kerak).", "Uyqusiz holda 'berilib' haydash xavfli (noto'g'ri — ぼんやり kerak).", "O'yinda yutgandan keyin, 'berilib' mashq qilmang (noto'g'ri)."], "tr": "夢中 = berilib ketgan, qiziqib ketgan, mahliyo."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t9-g1-1", "stem": "みんなが私の意見に反対していたが、彼女（　）応援してくれた。", "options": ["だけは", "だけなら", "だけに", "だけど"], "answer": 1, "explanation_uz": "〜だけは = ...gina (ajratib ta'kidlash). 彼女だけは = u yolg'iz", "tr": "Hamma mening fikrimga qarshi edi, lekin u (yolg'iz o'zi) qo'llab-quvvatladi."}, {"id": "t9-g1-2", "stem": "すみません、博物館へは（　）行けばいいか、教えてください。", "options": ["どう", "どんなに", "こう", "こんなに"], "answer": 1, "explanation_uz": "どう = qanday (usul haqida savol)", "tr": "Kechirasiz, muzeyga qanday borsam bo'lishini ayting."}, {"id": "t9-g1-3", "stem": "駅に着き（　）、電話をかけてください。", "options": ["通りに", "しだい", "ばかりに", "とたん"], "answer": 2, "explanation_uz": "動詞ます形+しだい = ...ishi bilanoq, darhol", "tr": "Bekatga yetishingiz bilan, telefon qiling."}, {"id": "t9-g1-4", "stem": "空に雲がたくさん出ているので、（　）雨が降るかもしれません。", "options": ["もしも", "もしかしたら", "もし", "もはや"], "answer": 2, "explanation_uz": "もしかしたら〜かもしれない = ehtimol ...bo'lishi mumkin", "tr": "Osmonda bulut ko'p, shuning uchun ehtimol yomg'ir yog'ar."}, {"id": "t9-g1-5", "stem": "あなたは、今までアメリカへ（　）ことがありますか。", "options": ["行き", "行った", "行くの", "行ったの"], "answer": 2, "explanation_uz": "〜たことがある = ...gan tajriba bor (...ganmisiz)", "tr": "Siz shu paytgacha Amerikaga borganmisiz?"}, {"id": "t9-g1-6", "stem": "明日の勝負で優勝できるか決まるので、負ける（　）。", "options": ["わけではない", "わけにはいかない", "ことではない", "ことにはいかない"], "answer": 2, "explanation_uz": "〜わけにはいかない = ...ishning iloji yo'q (axloqiy/vaziyat majburiyati)", "tr": "Ertangi o'yinda g'olib bo'lish hal bo'ladi, shuning uchun yutqazib bo'lmaydi."}, {"id": "t9-g1-7", "stem": "テレビを5時間（　）つづけて、目が痛くなりました。", "options": ["見られ", "見えて", "見せた", "見"], "answer": 4, "explanation_uz": "動詞ます形+つづける = ...ishda davom etmoq. 見+つづける", "tr": "Televizorni 5 soat ko'raverib, ko'zim og'rib qoldi."}, {"id": "t9-g1-8", "stem": "私がこの国の首相（　）、政治をもっとよくするのに。", "options": ["だったからには", "だったとしたら", "にしたら", "にしては"], "answer": 2, "explanation_uz": "〜だったとしたら = agar ...bo'lganda (faraziy shart)", "tr": "Agar men shu davlatning bosh vaziri bo'lganimda, siyosatni yaxshilagan bo'lardim."}, {"id": "t9-g1-9", "stem": "明日、ひさしぶりの休みなので、町へ（　）思います。", "options": ["遊びに行くことに", "遊びに行くのにしようと", "遊びに行くほどだと", "遊びに行こうと"], "answer": 4, "explanation_uz": "〜(よ)うと思う = ...moqchiman (niyat)", "tr": "Ertaga ko'pdan beri dam olish kunim, shuning uchun shaharga sayrga bormoqchiman."}, {"id": "t9-g1-10", "stem": "お荷物の配送については、受付カウンターに（　）、お願いいたします。", "options": ["うかがってくださるよう", "おたずねくださるよう", "聞いてあげるよう", "たずねてあげますよう"], "answer": 2, "explanation_uz": "お〜くださる = (hurmat) siz ...qilishingizni. おたずねくださる = so'rashingiz", "tr": "Yuk yetkazib berish bo'yicha, qabul stoliga murojaat qilishingizni so'raymiz."}, {"id": "t9-g1-11", "stem": "この町には、バスも電車も通っていないのだから、（　）。", "options": ["歩くよりほかはある", "歩くよりほかはない", "歩くよりほかだ", "歩くよりほかではない"], "answer": 2, "explanation_uz": "〜よりほかはない = ...dan boshqa iloj yo'q", "tr": "Bu shaharda avtobus ham, poyezd ham yurmaydi, shuning uchun yurishdan boshqa iloj yo'q."}, {"id": "t9-g1-12", "stem": "この仕事は、とても大変そうに見えますが、がんばれば（　）と思います。", "options": ["ならないこともない", "ならないこともある", "できないこともない", "できないこともある"], "answer": 3, "explanation_uz": "〜ないこともない = ...sa bo'ladi, eplasa bo'ladi (yumshoq imkon)", "tr": "Bu ish juda og'irday ko'rinadi, lekin harakat qilsa, qilsa bo'lmaydigan ish emas (eplasa bo'ladi)."}, {"id": "t9-g1-13", "stem": "明日は会社の面接に行く予定だ。絶対に遅刻（　）。", "options": ["するままにすると", "しないようにすると", "しないままにしないと", "しないようにしないと"], "answer": 4, "explanation_uz": "〜ないようにしないと = ...maslikka harakat qilishim kerak", "tr": "Ertaga kompaniya suhbatiga boraman. Mutlaqo kechikmaslikka harakat qilishim kerak."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t9-g2-14", "options": ["できない", "車の", "ばかりに", "運転が"], "answer": 1, "prefix": "川本「それが結局、", "suffix": "、いいアルバイトが見つからなかったんだ。」", "starPos": 3, "order": [2, 4, 1, 3], "explanation_uz": "To'g'ri tartib: 車の運転ができないばかりに", "tr": "To'g'ri jumla: «Oqibatda, mashina haydashni bilmaganim sababligina, yaxshi ish topilmadi.»"}, {"id": "t9-g2-15", "options": ["て", "教え", "た", "さしあげ"], "answer": 4, "prefix": "ちょうど先生に、会場への行き方を", "suffix": "ところです。", "starPos": 3, "order": [2, 1, 4, 3], "explanation_uz": "To'g'ri tartib: 教えてさしあげたところ (〜てさしあげる = birovga qilib bermoq, kamtarona)", "tr": "To'g'ri jumla: «Hozirgina o'qituvchiga zalga borish yo'lini o'rgatib bergan edim.»"}, {"id": "t9-g2-16", "options": ["いるのは", "ほうでは", "間違って", "あなたがたの"], "answer": 4, "prefix": "結論から言えば、", "suffix": "ないかと思います。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: 間違っているのはあなたがたのほうでは", "tr": "To'g'ri jumla: «Xulosa qilib aytsam, xato qilayotgani sizlar emasmikan deb o'ylayman.»"}, {"id": "t9-g2-17", "options": ["科学者", "発明された", "によって", "機械は"], "answer": 3, "prefix": "この新しい", "suffix": "ものです。", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: 機械は科学者によって発明された (〜によって = ...tomonidan)", "tr": "To'g'ri jumla: «Bu yangi mashina olim tomonidan ixtiro qilingan narsadir.»"}, {"id": "t9-g2-18", "options": ["資料に", "かけて", "もとづく", "集めた"], "answer": 1, "prefix": "これから発表する内容は、10年以上", "suffix": "ものだ。", "starPos": 3, "order": [2, 4, 1, 3], "explanation_uz": "To'g'ri tartib: かけて集めた資料にもとづく (〜にもとづく = ...ga asoslangan)", "tr": "To'g'ri jumla: «Endi taqdim qiladigan mazmunim, 10 yildan ortiq sarflab to'plangan materialga asoslangan narsadir.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "新しいスタイルの雑誌", "passage": "海外からやってきて、日本に住む人々の生活を紹介する雑誌、「Japanライフスタイル」が全国の書店で発売されました。\nこれまで、新聞や雑誌などで、日本で生活する留学生たちや、日本で仕事をする外国の人々について簡単に紹介されることはありましたが、生活そのものをテーマとした雑誌が発行されるのは{{19}}ことです。\n表紙のデザインも明るく、楽しそうな雑誌です。たくさんのカラフルな写真やイラストを使って、彼らの生活の様子を生き生きと紹介しています。\nこの雑誌は、毎月ではなく季刊{{20}}春、夏、秋、冬と、1年に4回発行される予定です。これまでは、インターネットで予約した読者に対し、通信販売のみを行ってきましたが、予想以上に売れ行きがよかったので、書店で売ることになった{{21}}。\nこの雑誌を発売する出版社は、「この雑誌{{22}}、外国人たちがなやみや楽しみを、おたがいに聞いたり教えあったりして、彼らの日本での生活が少しでもよいものになればと思う。」と話しています。日本全国で行われる日本人との交流に関する情報も、{{23}}", "passage_tr": "Chet eldan kelib Yaponiyada yashayotgan odamlarning hayotini tanishtiruvchi «Japan Lifestyle» jurnali butun mamlakat kitob do'konlarida sotuvga chiqdi. Shu paytgacha gazeta-jurnallarda Yaponiyada yashovchi chet ellik talabalar yoki ishlayotgan chet elliklar haqida qisqacha tanishtirilardi, biroq hayotning o'zini mavzu qilgan jurnal chiqarilishi JUDA KAM UCHRAYDIGAN hodisa. Muqova dizayni ham yorqin, quvnoq jurnal. Ko'plab rang-barang foto va rasmlardan foydalanib, ularning turmush tarzini jonli tasvirlaydi. Bu jurnal har oy emas, balki mavsumiy — YA'NI bahor, yoz, kuz, qish bo'lib, yiliga 4 marta chiqarilishi rejalashtirilgan. Shu paytgacha internet orqali oldindan buyurtma bergan o'quvchilarga faqat pochta orqali sotilardi, ammo kutilganidan ham yaxshi sotilgani uchun, kitob do'konlarida sotiladigan BO'LDI. Jurnalni chiqaruvchi nashriyot: «Bu jurnal ORQALI chet elliklar tashvish va quvonchlarini o'zaro so'rashib, o'rgatishib, ularning Yaponiyadagi hayoti ozgina bo'lsa-da yaxshilanса edi deb umid qilamiz», deydi. Yaponiya bo'ylab o'tkaziladigan yaponlar bilan muloqotга oid ma'lumotlarni ham TANISHTIRIB BORISH NIYATIDA EKAN.", "questions": [{"id": "t9-g3-19", "options": ["かなりよくある", "ときどき見られる", "きわめてまれな", "ないこともない"], "answer": 3, "blankNo": "19", "explanation_uz": "きわめてまれな = nihoyatda kam uchraydigan, juda noyob", "tr": "生活そのものをテーマとした雑誌…[きわめてまれな]こと = hayotni mavzu qilgan jurnal JUDA KAM uchraydigan hodisa."}, {"id": "t9-g3-20", "options": ["ところで", "つまり", "しかし", "それから"], "answer": 2, "blankNo": "20", "explanation_uz": "つまり = ya'ni, demak (izohlash)", "tr": "季刊[つまり]春夏秋冬…4回 = mavsumiy, YA'NI bahor-yoz-kuz-qish, 4 marta."}, {"id": "t9-g3-21", "options": ["というわけです", "ものがあります", "どころではありません", "というばかりです"], "answer": 1, "blankNo": "21", "explanation_uz": "〜というわけです = ...mana shunday/shu sababdan (xulosa-izoh)", "tr": "書店で売ることになった[というわけです] = kitob do'konida sotiladigan bo'ldi, MANA SHUNDAY."}, {"id": "t9-g3-22", "options": ["にとって", "に際して", "につれて", "を通じて"], "answer": 4, "blankNo": "22", "explanation_uz": "〜を通じて = ...orqali, ...vositasida", "tr": "この雑誌[を通じて]…聞いたり教えあったり = bu jurnal ORQALI o'zaro so'rashib, o'rgatishib."}, {"id": "t9-g3-23", "options": ["紹介するおそれがあるのです", "紹介していきかねません", "紹介していくつもりだそうです", "紹介するかのようです"], "answer": 3, "blankNo": "23", "explanation_uz": "〜つもりだそうです = ...moqchi ekan (eshitilgan niyat)", "tr": "情報も[紹介していくつもりだそうです] = ma'lumotlarni ham tanishtirib borish NIYATIDA EKAN."}]}]}]}, "10": {"id": 10, "title_jp": "第10回 模擬テスト", "title_uz": "10-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t10-v1-1", "stem": "ものを【盗んで】はいけません。", "options": ["にくんで", "かんで", "ぬすんで", "ふんで"], "answer": 3, "reading": "ぬすんで", "explanation_uz": "盗む → ぬすむ (o'g'irlamoq)", "tr": "Narsa o'g'irlamaslik kerak."}, {"id": "t10-v1-2", "stem": "彼のけがの【程度】は、まだわからない。", "options": ["ていど", "でいど", "しょうど", "じょうど"], "answer": 1, "reading": "ていど", "explanation_uz": "程度 → ていど (daraja, miqdor)", "tr": "Uning jarohati darajasi hali noma'lum."}, {"id": "t10-v1-3", "stem": "【帰国】する前に先生に会いたいです。", "options": ["きくに", "きぐに", "きこく", "きごく"], "answer": 3, "reading": "きこく", "explanation_uz": "帰国 → きこく (vatanga qaytish)", "tr": "Vatanga qaytishdan oldin o'qituvchim bilan ko'rishmoqchiman."}, {"id": "t10-v1-4", "stem": "彼女は、目を【閉じて】音楽を聞いていた。", "options": ["かんじて", "とじて", "はじて", "ふうじて"], "answer": 2, "reading": "とじて", "explanation_uz": "閉じる → とじる (yopmoq, yummoq)", "tr": "U ko'zini yumib musiqa tinglardi."}, {"id": "t10-v1-5", "stem": "あの人には、あまり【欲】がないようです。", "options": ["こころ", "こころざし", "いよく", "よく"], "answer": 4, "reading": "よく", "explanation_uz": "欲 → よく (nafs, istak, ochko'zlik)", "tr": "U odamda unchalik nafs (ochko'zlik) yo'qqa o'xshaydi."}, {"id": "t10-v1-6", "stem": "田中さんは、私の【親友】です。", "options": ["しんゆう", "しにゅう", "じんゆう", "じにゅう"], "answer": 1, "reading": "しんゆう", "explanation_uz": "親友 → しんゆう (qadrdon do'st)", "tr": "Tanaka-san mening qadrdon do'stim."}, {"id": "t10-v1-7", "stem": "【袋】が破れているので、とりかえてください。", "options": ["ぬの", "はこ", "ひも", "ふくろ"], "answer": 4, "reading": "ふくろ", "explanation_uz": "袋 → ふくろ (xalta, qop)", "tr": "Xalta yirtilgan, almashtiring."}, {"id": "t10-v1-8", "stem": "次の場所へ【移動】しなければなりません。", "options": ["うんどう", "かつどう", "こうどう", "いどう"], "answer": 4, "reading": "いどう", "explanation_uz": "移動 → いどう (ko'chish, siljish)", "tr": "Keyingi joyga ko'chishimiz (siljishimiz) kerak."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t10-v2-9", "stem": "仕事は、【じゅんちょう】に進んでいる。", "options": ["順常", "順調", "順長", "順状"], "answer": 2, "explanation_uz": "じゅんちょう → 順調 (silliq, muvaffaqiyatli kechayotgan)", "tr": "Ish silliq (yaxshi) ketyapti."}, {"id": "t10-v2-10", "stem": "友だちのことばを【しんよう】する。", "options": ["信用", "信頼", "真用", "真要"], "answer": 1, "explanation_uz": "しんよう → 信用 (ishonch, ishonish)", "tr": "Do'stimning so'ziga ishonaman."}, {"id": "t10-v2-11", "stem": "一晩中【おどって】、とても楽しかった。", "options": ["通って", "音って", "踊って", "舞って"], "answer": 3, "explanation_uz": "おどる → 踊る (raqsga tushmoq)", "tr": "Tun bo'yi raqsga tushib, juda zavqlandim."}, {"id": "t10-v2-12", "stem": "ラッシュアワーを【さけて】、早い時間の電車に乗った。", "options": ["逃けて", "裂けて", "割けて", "避けて"], "answer": 4, "explanation_uz": "さける → 避ける (qochmoq, chetlab o'tmoq)", "tr": "Tirbandlik (rush hour) dan qochib, erta vaqtdagi poyezdga chiqdim."}, {"id": "t10-v2-13", "stem": "【へいわ】な生活を送りたい。", "options": ["平安", "安平", "平和", "和平"], "answer": 3, "explanation_uz": "へいわ → 平和 (tinchlik)", "tr": "Tinch hayot kechirmoqchiman."}, {"id": "t10-v2-14", "stem": "サッカーの【しあい】に出場した。", "options": ["試場", "試合", "技場", "技合"], "answer": 2, "explanation_uz": "しあい → 試合 (o'yin, musobaqa)", "tr": "Futbol o'yiniga (musobaqasiga) chiqdim."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t10-v3-15", "stem": "この雑誌の（　）は、中年男性だ。", "options": ["メーカー", "ニーズ", "ターゲット", "リンク"], "answer": 3, "explanation_uz": "ターゲット = nishon, maqsadli auditoriya", "tr": "Bu jurnalning maqsadli auditoriyasi — o'rta yoshli erkaklar."}, {"id": "t10-v3-16", "stem": "明日の5時に荷物の（　）をお願いします。", "options": ["伝達", "発達", "到達", "配達"], "answer": 4, "explanation_uz": "配達 = yetkazib berish (pochta/yuk)", "tr": "Ertaga soat 5 da yukni yetkazib berishni so'rayman."}, {"id": "t10-v3-17", "stem": "車が（　）したので、自転車で会社に行くことにした。", "options": ["破壊", "故障", "悪化", "滅亡"], "answer": 2, "explanation_uz": "故障 = buzilish, nosozlik (texnika)", "tr": "Mashina buzilgani uchun, ishga velosipedda borishga qaror qildim."}, {"id": "t10-v3-18", "stem": "時間がたって、コーヒーが（　）しまった。", "options": ["凍って", "冷めて", "わいて", "とけて"], "answer": 2, "explanation_uz": "冷める = sovimoq (issiq narsa)", "tr": "Vaqt o'tib, kofe sovib qoldi."}, {"id": "t10-v3-19", "stem": "田中さんは、私とリンさんの（　）の友人だ。", "options": ["共同", "共感", "共通", "共有"], "answer": 3, "explanation_uz": "共通 = umumiy, mushtarak", "tr": "Tanaka-san men va Lin-sanning umumiy (mushtarak) do'stimiz."}, {"id": "t10-v3-20", "stem": "難しい問題が（　）、うれしかった。", "options": ["解けて", "割れて", "折れて", "破れて"], "answer": 1, "explanation_uz": "解ける = yechilmoq (masala)", "tr": "Qiyin masala yechilib, xursand bo'ldim."}, {"id": "t10-v3-21", "stem": "あと1000円（　）すると、もっとよい部屋に変更できます。", "options": ["ダブル", "シングル", "プラス", "チップ"], "answer": 3, "explanation_uz": "プラスする = qo'shmoq, ustiga qo'shish", "tr": "Yana 1000 yen qo'shsangiz, yaxshiroq xonaga o'zgartira olasiz."}, {"id": "t10-v3-22", "stem": "このバイオリンはイタリア（　）です。", "options": ["造", "産", "作", "製"], "answer": 4, "explanation_uz": "〜製 = ...da ishlangan, ...ishi (mamlakat + 製)", "tr": "Bu skripka Italiyada ishlangan (Italiya ishi)."}, {"id": "t10-v3-23", "stem": "3人の意見が（　）した。", "options": ["合同", "選択", "統一", "一致"], "answer": 4, "explanation_uz": "一致 = mos kelish, bir xil bo'lish", "tr": "Uch kishining fikri bir xil chiqdi (mos keldi)."}, {"id": "t10-v3-24", "stem": "有名なレストランの料理を食べたが、おいしくなくて（　）した。", "options": ["ぴったり", "にっこり", "めっきり", "がっかり"], "answer": 4, "explanation_uz": "がっかりする = hafsalasi pir bo'lmoq, umidsizlanmoq", "tr": "Mashhur restoran taomini yedim, lekin mazasiz bo'lib, hafsalam pir bo'ldi."}, {"id": "t10-v3-25", "stem": "今年の夏は、いつもより（　）すずしかった。", "options": ["特殊", "特別", "一斉", "同一"], "answer": 2, "explanation_uz": "特別 = alohida, ayniqsa, juda", "tr": "Bu yilgi yoz odatdagidan ko'ra alohida salqin edi."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t10-v4-26", "stem": "【とんでもない】ことが起こった。", "options": ["初めての", "よくある", "普通の", "意外な"], "answer": 4, "explanation_uz": "とんでもない = kutilmagan, aql bovar qilmas → 意外な (kutilmagan)", "tr": "Kutilmagan (g'ayrioddiy) voqea yuz berdi."}, {"id": "t10-v4-27", "stem": "部屋を【散らかした】。", "options": ["きれいにした", "汚くした", "明るくした", "暗くした"], "answer": 2, "explanation_uz": "散らかす = to'zitmoq, tartibsiz qilmoq → 汚くした", "tr": "Xonani to'zitib (kir qilib) tashladim."}, {"id": "t10-v4-28", "stem": "彼女は、道の途中で【ふり返った】。", "options": ["前を見た", "後ろを見た", "あちらへ行った", "こちらへ帰ってきた"], "answer": 2, "explanation_uz": "ふり返る = ortiga qaramoq → 後ろを見た", "tr": "U yo'l o'rtasida ortiga qaradi."}, {"id": "t10-v4-29", "stem": "後輩「おかわりを注文しましょうか。」先輩「今、料理は【間に合っている】よ。」", "options": ["時間通りに来る", "十分である", "完成している", "もっと必要である"], "answer": 2, "explanation_uz": "間に合っている = yetarli, kifoya → 十分である", "tr": "Kichik: «Yana buyurtma beraymi?» Katta: «Hozir ovqat yetarli (kifoya).»"}, {"id": "t10-v4-30", "stem": "彼女は、とても【慎重な】人です。", "options": ["人より静かな", "太っている", "よく考えてから行動する", "何を考えているかわからない"], "answer": 3, "explanation_uz": "慎重 = ehtiyotkor, o'ylab ish qiladigan → よく考えてから行動する", "tr": "U juda ehtiyotkor odam."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t10-v5-31", "stem": "ほえる", "options": ["家の外で、虫のほえる声が聞こえた。", "新入社員が社長に向かって友だちのようにほえていた。", "私の家の犬は、夜中によくほえます。", "かわいがっていたペットが死んで、悲しくてほえた。"], "answer": 3, "optsTr": ["Uy tashqarisida hasharotning 'vovullashi' eshitildi (noto'g'ri — 鳴く kerak).", "Yangi xodim rahbarga do'stiday 'vovullardi' (noto'g'ri).", "Mening uy itim kechalari tez-tez vovullaydi. (to'g'ri)", "Sevimli uy hayvonim o'lib, qayg'udan 'vovulladim' (noto'g'ri — 泣く kerak)."], "tr": "ほえる(吠える) = (it/yirtqich) vovullamoq, akillamoq."}, {"id": "t10-v5-32", "stem": "あふれる", "options": ["お菓子を買いすぎてあふれたので、少しあげます。", "コップに水を入れたら、あふれてしまった。", "授業が終わったあとも、教室に生徒が1人あふれていた。", "道で転んで、足が赤くあふれてしまいました。"], "answer": 2, "optsTr": ["Shirinlik ko'p olib 'toshib ketdi', ozini beraman (noto'g'ri — 余る kerak).", "Stakanga suv quysam, toshib ketdi. (to'g'ri)", "Dars tugagach ham, sinfda 1 o'quvchi 'toshib' turardi (noto'g'ri — 残る kerak).", "Yo'lda yiqilib, oyog'im qizarib 'toshib ketdi' (noto'g'ri — はれる kerak)."], "tr": "あふれる(溢れる) = toshib ketmoq, to'lib oshmoq."}, {"id": "t10-v5-33", "stem": "しばる", "options": ["出かけるときは、ちゃんとドアのかぎをしばってください。", "シャツのボタンが開いているので、しばったほうがいいですよ。", "手紙に切手をしばって、ポストに入れた。", "その荷物をロープでかたくしばってください。"], "answer": 4, "optsTr": ["Chiqayotganda eshik qulfini 'bog'lang' (noto'g'ri — かける kerak).", "Ko'ylak tugmasi ochiq, 'bog'lagan' ma'qul (noto'g'ri — とめる kerak).", "Xatga markani 'bog'lab', qutiga soldim (noto'g'ri — はる kerak).", "U yukni arqon bilan mahkam bog'lang. (to'g'ri)"], "tr": "しばる(縛る) = bog'lamoq, mahkam bog'lab qo'ymoq."}, {"id": "t10-v5-34", "stem": "得", "options": ["彼女はギターがとても得だ。", "商売で大きな得をした。", "私はあなたよりテニスが得です。", "デパートで得でかばんを買った。"], "answer": 2, "optsTr": ["U gitarada juda 'foydali' (noto'g'ri — 得意 kerak).", "Savdoda katta foyda ko'rdim. (to'g'ri)", "Men sizdan tennis o'yinida 'foydaliman' (noto'g'ri — 得意 kerak).", "Univermagda 'foyda bilan' sumka oldim (noto'g'ri — 安く kerak)."], "tr": "得(とく) = foyda, manfaat, yutuq."}, {"id": "t10-v5-35", "stem": "鋭い", "options": ["一日中、鋭い仕事をするのは大変だ。", "このかばんは、鋭くてとても便利だ。", "このスープは、鋭いので気をつけて食べてください。", "彼の批判は、ときどきとても鋭い。"], "answer": 4, "optsTr": ["Kun bo'yi 'o'tkir' ish qilish og'ir (noto'g'ri — きつい kerak).", "Bu sumka 'o'tkir' va juda qulay (noto'g'ri — 便利 kerak).", "Bu sho'rva 'o'tkir', ehtiyot bo'lib yeng (noto'g'ri — 熱い kerak).", "Uning tanqidi ba'zan juda o'tkir (teran) bo'ladi. (to'g'ri)"], "tr": "鋭い(するどい) = o'tkir, keskin, teran."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t10-g1-1", "stem": "こんな小さな子ども用の服が、1万円（　）する。", "options": ["は", "も", "と", "を"], "answer": 2, "explanation_uz": "数量+も = ...cha (ko'plik/hayratni ta'kidlash)", "tr": "Bunday kichkina bolalar kiyimi 10 ming yen turadi (shuncha qimmat)."}, {"id": "t10-g1-2", "stem": "学生「資料を50部コピーしましたが、足りますか。」先生「参加者は40人なので、（　）くらいでいいでしょう。」", "options": ["それ", "そこ", "あれ", "あそこ"], "answer": 1, "explanation_uz": "それくらい = shuncha (yaqindagi narsa/miqdorga ishora)", "tr": "Talaba: «Hujjatdan 50 nusxa oldim, yetadimi?» O'qituvchi: «Ishtirokchi 40 kishi, shuncha bo'lsa bo'ldi.»"}, {"id": "t10-g1-3", "stem": "地図を（　）浅草を歩く。", "options": ["見たところ", "見るに応じて", "見るかと思うと", "見つつ"], "answer": 4, "explanation_uz": "〜つつ = ...gan holda, bir vaqtda (ikki harakat)", "tr": "Xaritaga qarab-qarab Asakusani aylanaman."}, {"id": "t10-g1-4", "stem": "今年はたくさん雪が降り、昨年（　）、かなり寒い。", "options": ["とひきかえ", "としたら", "におうじて", "にくらべ"], "answer": 4, "explanation_uz": "〜にくらべ = ...ga nisbatan, taqqoslaganda", "tr": "Bu yil ko'p qor yog'di, o'tgan yilga nisbatan ancha sovuq."}, {"id": "t10-g1-5", "stem": "中田くんは、スポーツ選手（　）、走るのがとても速い。", "options": ["まであって", "だけあって", "ほどあって", "しかあって"], "answer": 2, "explanation_uz": "〜だけあって = ...ga yarasha, ...bo'lgani uchun (kutilgandek)", "tr": "Nakata sportchi bo'lgani uchun ham, juda tez yuguradi."}, {"id": "t10-g1-6", "stem": "学校のある駅から銀座までは、2回（　）といけない。", "options": ["乗り換え", "乗り換えた", "乗り換えない", "乗り換える"], "answer": 3, "explanation_uz": "〜ないといけない = ...masa bo'lmaydi. 乗り換えないと", "tr": "Maktab bekatidan Ginzagacha 2 marta poyezd almashtirmasa bo'lmaydi."}, {"id": "t10-g1-7", "stem": "男女を（　）だれでも参加できます。", "options": ["問えば", "問わず", "問うと", "問えず"], "answer": 2, "explanation_uz": "〜を問わず = ...ga qaramay, ...dan qat'i nazar", "tr": "Erkak-ayolligidan qat'i nazar, hamma qatnasha oladi."}, {"id": "t10-g1-8", "stem": "石川君が大切な書類をなくしたらしい。無責任な彼が（　）ことだ。", "options": ["やらなそうな", "やりそうな", "やらないような", "やったような"], "answer": 2, "explanation_uz": "〜そうな = ...adigandek, ...ishi mumkin (taxmin). やりそうな = qiladigandek", "tr": "Ishikava muhim hujjatni yo'qotibdi. Mas'uliyatsiz uning qiladigan ishi-da."}, {"id": "t10-g1-9", "stem": "もし川島さんの電話番号を（　）、教えてください。", "options": ["知りましたら", "知られましたら", "存じましたら", "ご存じでしたら"], "answer": 4, "explanation_uz": "ご存じ = 知っている ning hurmat shakli (bilsangiz)", "tr": "Agar Kavashima-sanning telefon raqamini bilsangiz, ayting."}, {"id": "t10-g1-10", "stem": "今日の朝は、とてもいそがしかったので、（　）会社へ行った。", "options": ["何を食べても", "何も食べずに", "何も食べないと", "何を食べるまでもなく"], "answer": 2, "explanation_uz": "〜ずに = ...masdan. 食べずに = yemasdan", "tr": "Bugun ertalab juda band edim, shuning uchun hech narsa yemay ishga ketdim."}, {"id": "t10-g1-11", "stem": "あそこに立っている男の人は、これから何を（　）いるのですか。", "options": ["しようとして", "しろといって", "するとして", "したといって"], "answer": 1, "explanation_uz": "〜(よ)うとしている = ...moqchi bo'lyapti (harakat oldidagi holat)", "tr": "Anavi turgan erkak hozir nima qilmoqchi bo'lyapti?"}, {"id": "t10-g1-12", "stem": "三井「あなたはドイツ語がお上手だそうですね。」山中「いいえ、（　）が、まだまだです。」", "options": ["話さないことはできます", "話さないことはできません", "話せないことはあります", "話せないことはありません"], "answer": 4, "explanation_uz": "〜ないことはない = ...sa qila olaman (yumshoq tasdiq). 話せないことはない = gapira olmasligim emas", "tr": "Mitsui: «Siz nemis tilini yaxshi bilarkansiz.» Yamanaka: «Yo'q, gapira olmasligim emas-u (ozroq gapiraman), lekin hali yo'l bor.»"}, {"id": "t10-g1-13", "stem": "先週借りたお金は、もうほとんど（　）。", "options": ["使うところでした", "使わないことでした", "使ってしまいました", "使ってしまいませんでした"], "answer": 3, "explanation_uz": "〜てしまう = ...ib bo'lmoq (tugatish/tugallanish). 使ってしまいました", "tr": "O'tgan hafta qarz olgan pulni endi deyarli sarflab bo'ldim."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t10-g2-14", "options": ["電車が", "ものですから", "遅れた", "事故で"], "answer": 3, "prefix": "内田「もうしわけありません。", "suffix": "、遅くなりました。」", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: 事故で電車が遅れたものですから (〜ものですから = ...gani sababli)", "tr": "To'g'ri jumla: «Kechirasiz. Avariya tufayli poyezd kechikkani sababli, kechikib qoldim.»"}, {"id": "t10-g2-15", "options": ["遊びに", "いい", "行きたい", "から"], "answer": 1, "prefix": "今日は夏休みの初日だし、天気もいいし、どこでも", "suffix": "なあ。", "starPos": 3, "order": [2, 4, 1, 3], "explanation_uz": "To'g'ri tartib: いいから遊びに行きたい", "tr": "To'g'ri jumla: «Bugun yozги ta'tilning birinchi kuni, havo ham yaxshi, qayerga bo'lsa ham sayrga borgim kelyapti.»"}, {"id": "t10-g2-16", "options": ["思い出す", "多い", "人も", "のでは"], "answer": 2, "prefix": "日本の有名な山と言われれば、富士山を", "suffix": "ないか。", "starPos": 3, "order": [1, 3, 2, 4], "explanation_uz": "To'g'ri tartib: 思い出す人も多いのでは (〜のではないか = ...emasmi)", "tr": "To'g'ri jumla: «Yaponiyaning mashhur tog'i deyilsa, Fuji tog'ini eslaydigan odam ham ko'p emasmi.»"}, {"id": "t10-g2-17", "options": ["要求に", "形で", "強い", "こたえる"], "answer": 4, "prefix": "以前からの、社員の", "suffix": "社長は給料を上げた。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: 強い要求にこたえる形で (〜にこたえる = ...ga javob bermoq)", "tr": "To'g'ri jumla: «Ilgaridan beri xodimlarning kuchli talabiga javob bergan tarzda, rahbar maoshni oshirdi.»"}, {"id": "t10-g2-18", "options": ["わたる", "数か月に", "して", "船の旅を"], "answer": 4, "prefix": "昔は、飛行機がなかったので、", "suffix": "海外へ行きました。", "starPos": 3, "order": [2, 1, 4, 3], "explanation_uz": "To'g'ri tartib: 数か月にわたる船の旅をして (〜にわたる = ...davomida cho'zilgan)", "tr": "To'g'ri jumla: «Ilgari samolyot bo'lmagani uchun, bir necha oyga cho'zilgan kema sayohatini qilib chet elga borardik.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "食べ物とコミュニケーション", "passage": "「男性の心をつかむには、まず胃袋から」という言葉を聞いたことがありますか。恋愛について相談をしているときに、だれかから聞いたことがあるかもしれません。男性は、{{19}}を作ってくれる女性を好きになることが多い、つまり、食事は男性にとっては重要だということです。\n{{20}}、この言葉は、恋愛や男性だけにあてはまるわけではありません。人と人とのコミュニケーションにおいて、食べ物は非常に重要な役割をはたすからです。\nたとえば、ある人と親しくなりたいと思った場合、「一緒に近くを歩きませんか」と言うよりも、「一緒においしいケーキを食べに行きませんか」と言うほうが、ずっと仲よくなれそうな気がしませんか。\n実際に、一緒にものを食べたり飲んだりした人と、前よりずっと仲よくなった、という思い出が{{21}}。\n食事が重要な役割をはたすのは、友だちや彼氏、彼女を作る場合だけに{{22}}。仕事の話をする場合でも、一緒に食事をすることは大きな意味を持ちます。落ちついて話ができる、サービスも味もよいお店を知っていることが、仕事の話をうまく進めるための手段に{{23}}。", "passage_tr": "«Erkakning ko'nglini olish uchun, avvalo oshqozonidan» degan iborani eshitganmisiz? Sevgi haqida maslahatlashayotganda, kimdandir eshitgan bo'lishingiz mumkin. Erkaklar MAZALI TAOM pishirib beradigan ayolni yoqtirib qolishi ko'p uchraydi — ya'ni, ovqat erkak uchun muhim degani. SHUNDAY BO'LSA-DA, bu ibora faqat sevgi yoki erkaklarga taalluqli emas. Chunki inson bilan inson muloqotida ovqat juda muhim rol o'ynaydi. Masalan, kimdir bilan yaqinlashmoqchi bo'lsangiz, «birga yaqin-atrofda yuramizmi» deyishdan ko'ra «birga mazali tort yegani boramizmi» deganingiz ancha yaqinlashtiradigandek tuyulmaydimi? Haqiqatan, birga biror narsa yeb-ichgan odam bilan oldingidan ancha yaqinlashgan degan xotirangiz BORDIR deb o'ylayman. Ovqat muhim rol o'ynashi faqat do'st, yigit yoki qiz orttirish holatigagina TAALLUQLI EMAS. Ish haqida gaplashganda ham birga ovqatlanish katta ma'no kasb etadi. Bemalol gaplasha oladigan, xizmati ham, mazasi ham yaxshi joyni bilish — ish muzokarasini muvaffaqiyatli olib borish vositasiga AYLANISHI HAM MUMKIN.", "questions": [{"id": "t10-g3-19", "options": ["まあまあの料理", "おいしい料理", "いつもの料理", "すべての料理"], "answer": 2, "blankNo": "19", "explanation_uz": "おいしい料理 = mazali taom (kontekstga mos)", "tr": "男性は[おいしい料理]を作ってくれる女性 = erkak MAZALI TAOM pishirib beradigan ayolni yoqtiradi."}, {"id": "t10-g3-20", "options": ["そのため", "それだけ", "そうはいっても", "なぜなら"], "answer": 3, "blankNo": "20", "explanation_uz": "そうはいっても = shunday bo'lsa-da, shunga qaramay", "tr": "[そうはいっても]、恋愛や男性だけにあてはまるわけではない = SHUNDAY BO'LSA-DA, faqat sevgi/erkakka taalluqli emas."}, {"id": "t10-g3-21", "options": ["するかと思います", "なるかと思います", "いることと思います", "あることと思います"], "answer": 4, "blankNo": "21", "explanation_uz": "〜ことと思います = ...dir deb o'ylayman (muloyim taxmin)", "tr": "思い出が[あることと思います] = bunday xotirangiz BORDIR deb o'ylayman."}, {"id": "t10-g3-22", "options": ["限りました", "限るようです", "限ります", "限りません"], "answer": 4, "blankNo": "22", "explanation_uz": "〜に限りません = faqat ...bilan cheklanmaydi", "tr": "作る場合だけに[限りません] = ...holatigagina TAALLUQLI EMAS (faqat shuning bilan cheklanmaydi)."}, {"id": "t10-g3-23", "options": ["なることさえあるのです", "することはあるのです", "なるしかないのです", "するしかないのです"], "answer": 1, "blankNo": "23", "explanation_uz": "〜さえある = hatto ...ham bo'ladi", "tr": "手段に[なることさえあるのです] = vositaga AYLANISHI HAM MUMKIN (hatto)."}]}]}]}, "11": {"id": 11, "title_jp": "第11回 模擬テスト", "title_uz": "11-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t11-v1-1", "stem": "天気がいいので、洗たく物がよく【乾いた】。", "options": ["ひらいた", "うごいた", "みがいた", "かわいた"], "answer": 4, "reading": "かわいた", "explanation_uz": "乾く → かわく (qurimoq)", "tr": "Havo yaxshi bo'lgani uchun kir yaxshi quridi."}, {"id": "t11-v1-2", "stem": "この道がとなりの市との【境界】です。", "options": ["きょかい", "きょうかい", "きょがい", "きょうがい"], "answer": 2, "reading": "きょうかい", "explanation_uz": "境界 → きょうかい (chegara)", "tr": "Bu yo'l qo'shni shahar bilan chegara."}, {"id": "t11-v1-3", "stem": "【以後】は、別々に行動しましょう。", "options": ["いこ", "いこう", "いご", "いごう"], "answer": 3, "reading": "いご", "explanation_uz": "以後 → いご (bundan keyin, keyinchalik)", "tr": "Bundan keyin alohida harakat qilaylik."}, {"id": "t11-v1-4", "stem": "もえないごみを土に【埋めて】はいけません。", "options": ["こめて", "ためて", "とめて", "うめて"], "answer": 4, "reading": "うめて", "explanation_uz": "埋める → うめる (ko'mmoq)", "tr": "Yonmaydigan axlatni tuproqqa ko'mish mumkin emas."}, {"id": "t11-v1-5", "stem": "【例】をあげて説明してください。", "options": ["え", "れい", "ず", "けん"], "answer": 2, "reading": "れい", "explanation_uz": "例 → れい (misol)", "tr": "Misol keltirib tushuntiring."}, {"id": "t11-v1-6", "stem": "美しい【風景】が広がっている。", "options": ["ふうけい", "ふうげい", "ふけい", "ふげい"], "answer": 1, "reading": "ふうけい", "explanation_uz": "風景 → ふうけい (manzara, ko'rinish)", "tr": "Go'zal manzara yoyilib yotibdi."}, {"id": "t11-v1-7", "stem": "甘いものは【骨】によくない。", "options": ["こつ", "ごつ", "ほね", "ぼね"], "answer": 3, "reading": "ほね", "explanation_uz": "骨 → ほね (suyak)", "tr": "Shirinlik suyak uchun yaxshi emas."}, {"id": "t11-v1-8", "stem": "ある人から【奇妙】な話を聞いた。", "options": ["びりょう", "びみょう", "きちょう", "きみょう"], "answer": 4, "reading": "きみょう", "explanation_uz": "奇妙 → きみょう (g'alati, ajabtovur)", "tr": "Bir odamdan g'alati gap eshitdim."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t11-v2-9", "stem": "【しぜん】の中で運動するのは、気持ちがよい。", "options": ["仕然", "事然", "自然", "私然"], "answer": 3, "explanation_uz": "しぜん → 自然 (tabiat)", "tr": "Tabiat qo'ynida sport qilish yoqimli."}, {"id": "t11-v2-10", "stem": "【きょうじゅ】の指導のもとで、論文を書いた。", "options": ["教師", "教示", "教受", "教授"], "answer": 4, "explanation_uz": "きょうじゅ → 教授 (professor)", "tr": "Professor rahbarligida ilmiy ish yozdim."}, {"id": "t11-v2-11", "stem": "この川は、あの川より【あさい】。", "options": ["深い", "浅い", "太い", "細い"], "answer": 2, "explanation_uz": "あさい → 浅い (sayoz)", "tr": "Bu daryo u daryodan sayozroq."}, {"id": "t11-v2-12", "stem": "この木は、冬に【かれて】しまう。", "options": ["枝れて", "朽れて", "枯れて", "相れて"], "answer": 3, "explanation_uz": "かれる → 枯れる (qurimoq — o'simlik)", "tr": "Bu daraxt qishda qurib qoladi."}, {"id": "t11-v2-13", "stem": "自分の考えを【しゅちょう】する。", "options": ["手長", "手張", "主長", "主張"], "answer": 4, "explanation_uz": "しゅちょう → 主張 (qat'iy fikr bildirish, da'vo)", "tr": "O'z fikrini qat'iy bildiraman (talab qilaman)."}, {"id": "t11-v2-14", "stem": "コンサートホールに【おおぜい】の人が集まった。", "options": ["大勢", "多勢", "大盛", "多盛"], "answer": 1, "explanation_uz": "おおぜい → 大勢 (ko'p odam, anchagina)", "tr": "Konsert zaliga ko'p odam yig'ildi."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t11-v3-15", "stem": "デジカメの写真の（　）をコンピューターに保存してください。", "options": ["マウス", "キーボード", "カバー", "データ"], "answer": 4, "explanation_uz": "データ = ma'lumot, data", "tr": "Raqamli kamera suratlari ma'lumotini kompyuterga saqlang."}, {"id": "t11-v3-16", "stem": "友だちから、メールの（　）が来ないので、心配だ。", "options": ["電信", "配布", "返信", "到着"], "answer": 3, "explanation_uz": "返信 = javob (xat/xabarga)", "tr": "Do'stimdan elektron xat javobi kelmagani uchun xavotirdaman."}, {"id": "t11-v3-17", "stem": "ヨーロッパの歴史あるホテルに（　）しました。", "options": ["滞在", "存在", "停留", "停滞"], "answer": 1, "explanation_uz": "滞在 = vaqtincha turish, qolish", "tr": "Yevropaning tarixiy mehmonxonasida turdim (yashadim)."}, {"id": "t11-v3-18", "stem": "自転車を（　）、前へ進む。", "options": ["おして", "こいで", "にぎって", "とめて"], "answer": 2, "explanation_uz": "(自転車を)こぐ = pedal bosmoq, velosiped haydamoq", "tr": "Velosiped pedalini bosib (haydab), oldinga yuraman."}, {"id": "t11-v3-19", "stem": "テストに向けて（　）の準備をした。", "options": ["全長", "全盛", "万人", "万全"], "answer": 4, "explanation_uz": "万全 = to'la-to'kis, mukammal (tayyorgarlik)", "tr": "Testga to'liq (mukammal) tayyorgarlik ko'rdim."}, {"id": "t11-v3-20", "stem": "オレンジを（　）、ジュースを作る。", "options": ["ぬって", "かんで", "こんで", "しぼって"], "answer": 4, "explanation_uz": "しぼる = siqmoq, siqib olmoq", "tr": "Apelsinni siqib, sharbat tayyorlayman."}, {"id": "t11-v3-21", "stem": "（　）を取りながら、発表を聞いてください。", "options": ["レポート", "メモ", "ペーパー", "ディベート"], "answer": 2, "explanation_uz": "メモを取る = qayd qilmoq, eslatma yozmoq", "tr": "Qayd (eslatma) olib turib, taqdimotni tinglang."}, {"id": "t11-v3-22", "stem": "私の夢は、3階（　）の家に住むことです。", "options": ["作り", "建て", "重ね", "乗せ"], "answer": 2, "explanation_uz": "〜階建て = ...qavatli (bino)", "tr": "Mening orzuim — 3 qavatli uyda yashash."}, {"id": "t11-v3-23", "stem": "私は、2人の意見を聞いて、彼の意見が正しいと（　）した。", "options": ["行", "成立", "判断", "実現"], "answer": 3, "explanation_uz": "判断 = hukm, baho, qaror", "tr": "Men ikki kishining fikrini eshitib, uning fikri to'g'ri deb hukm qildim (qaror qildim)."}, {"id": "t11-v3-24", "stem": "髪を短く切って、（　）した気分になった。", "options": ["すっきり", "こっそり", "すっかり", "たっぷり"], "answer": 1, "explanation_uz": "すっきりする = yengil tortmoq, tiniqlashmoq", "tr": "Sochni kalta qildirib, yengillashgan (tetik) holatga keldim."}, {"id": "t11-v3-25", "stem": "新しい仕事についたばかりで、少し（　）だ。", "options": ["不正", "不安", "不運", "不明"], "answer": 2, "explanation_uz": "不安 = xavotir, tashvish, bezovtalik", "tr": "Yangi ishga endi kirganim uchun, biroz xavotirdaman."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t11-v4-26", "stem": "あなたに、本当に【すまない】と思います。", "options": ["相談したい", "会いたい", "もうしわけない", "何もしたくない"], "answer": 3, "explanation_uz": "すまない = kechirasiz, uzr → もうしわけない", "tr": "Sizdan rostdan ham uzr so'rayman (afsusdaman)."}, {"id": "t11-v4-27", "stem": "土曜日はデートなので、とても【わくわく】しています。", "options": ["幸せになって", "楽しみにして", "緊張して", "心配して"], "answer": 2, "explanation_uz": "わくわくする = hayajon bilan kutmoq → 楽しみにして", "tr": "Shanba kuni uchrashuv, shuning uchun juda intiqman (kutaman)."}, {"id": "t11-v4-28", "stem": "明日、予定が【重なって】しまいました。", "options": ["急に予定が入って", "同時に予定が入って", "大切な予定が入って", "難しい予定が入って"], "answer": 2, "explanation_uz": "予定が重なる = rejalar to'qnash kelmoq → 同時に予定が入って", "tr": "Ertaga rejalar bir-birining ustiga tushib qoldi."}, {"id": "t11-v4-29", "stem": "休みがとれず、【ダウンして】しまった。", "options": ["けがして", "眠って", "逃げて", "倒れて"], "answer": 4, "explanation_uz": "ダウンする = holdan toymoq, yiqilmoq → 倒れて", "tr": "Dam ololmay, holdan toyib (yiqilib) qoldim."}, {"id": "t11-v4-30", "stem": "机の上が【ごちゃごちゃ】なので、かたづけてください。", "options": ["汚い", "せまい", "くさい", "黒い"], "answer": 1, "explanation_uz": "ごちゃごちゃ = tartibsiz, alag'-chalag' → 汚い", "tr": "Stol usti tartibsiz (alag'-chalag') bo'lgani uchun, yig'ishtiring."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t11-v5-31", "stem": "つぶれる", "options": ["強い風で、その木はまん中からつぶれてしまった。", "急に雨がつぶれ、急いで近くのお店に入った。", "先日の大きな地震で、たくさんの家がつぶれた。", "前から使っていた時計がつぶれて、動かなくなった。"], "answer": 3, "optsTr": ["Kuchli shamoldan o'sha daraxt o'rtasidan 'ezildi' (noto'g'ri — 折れる kerak).", "To'satdan yomg'ir 'ezildi', do'konga kirdim (noto'g'ri — 降る kerak).", "Yaqindagi katta zilzilada ko'p uy quladi (vayron bo'ldi). (to'g'ri)", "Eski soat 'ezilib', ishlamay qoldi (noto'g'ri — 壊れる kerak)."], "tr": "つぶれる(潰れる) = ezilmoq, qulamoq, vayron bo'lmoq."}, {"id": "t11-v5-32", "stem": "増す", "options": ["台風のため、風の強さが増している。", "1日3時間勉強したので、彼の日本語はいきなり増した。", "社長に、給料を増してくださいとお願いした。", "大学に入ってから、友だちが増してうれしい。"], "answer": 1, "optsTr": ["Tayfun tufayli shamol kuchi ortib boryapti. (to'g'ri)", "Kuniga 3 soat o'qigani uchun, uning yaponchasi birdan 'ortdi' (noto'g'ri — 上達 kerak).", "Rahbarga maoshni 'oshiring' deb so'radim (noto'g'ri — 上げる kerak).", "Universitetga kirgach, do'stim 'ortib' xursandman (noto'g'ri — 増える kerak)."], "tr": "増す(ます) = ko'paymoq, kuchaymoq, ortmoq."}, {"id": "t11-v5-33", "stem": "におい", "options": ["この料理は、おいしそうなにおいがする。", "黒いにおいを見て、マンションの火事に気がついた。", "昨晩は、となりの家の大きなにおいが聞こえてきた。", "今朝はいい天気で、空にいくつか白いにおいが出ている。"], "answer": 1, "optsTr": ["Bu taomdan mazali hid keladi. (to'g'ri)", "Qora 'hid'ni ko'rib, yong'inni payqadim (noto'g'ri — 煙 kerak).", "Kecha qo'shni uyning katta 'hidi' eshitildi (noto'g'ri — 音 kerak).", "Bugun havo yaxshi, osmonda bir nechta oq 'hid' bor (noto'g'ri — 雲 kerak)."], "tr": "におい = hid, is."}, {"id": "t11-v5-34", "stem": "声", "options": ["車の声がうるさくて、テレビの音が聞こえない。", "駅まで走ったら、声が切れてしまった。", "風邪をひいて、きのうから声が止まらない。", "もっと他人の声に耳をかたむけたほうがよい。"], "answer": 4, "optsTr": ["Mashina 'ovozi' shovqinli, televizor eshitilmaydi (noto'g'ri — 音 kerak).", "Bekatga yugursam, 'ovozim' uzilib qoldi (noto'g'ri — 息 kerak).", "Shamollab, kechadan beri 'ovozim' to'xtamayapti (noto'g'ri — せき kerak).", "Boshqalarning ovoziga (fikriga) ko'proq quloq solgan ma'qul. (to'g'ri)"], "tr": "声(こえ) = ovoz (odam/jonzot tovushi)."}, {"id": "t11-v5-35", "stem": "あやしい", "options": ["今日は寒いので、あやしいものが食べたい。", "帰宅すると、家の前にあやしい男が立っていた。", "彼女は、親切であやしいので、みんなに人気がある。", "この手帳は、なんでも書くことができて、とてもあやしい。"], "answer": 2, "optsTr": ["Bugun sovuq, 'shubhali' narsa yegim keladi (noto'g'ri — あたたかい kerak).", "Uyga qaytsam, uy oldida shubhali erkak turardi. (to'g'ri)", "U mehribon va 'shubhali', hammaga yoqadi (noto'g'ri — やさしい kerak).", "Bu daftarga hammasini yozsa bo'ladi, juda 'shubhali' (noto'g'ri — 便利 kerak)."], "tr": "あやしい(怪しい) = shubhali, gumonli, g'alati."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t11-g1-1", "stem": "台風が来て、昨日は沖縄では大雨だった（　）。", "options": ["のは", "とを", "のを", "とか"], "answer": 4, "explanation_uz": "〜とか = ...emish, ...deyishadi (eshitilgan, noaniq)", "tr": "Tayfun kelib, kecha Okinavada kuchli yomg'ir bo'libdi (deyishadi)."}, {"id": "t11-g1-2", "stem": "妻「明日からたばこを吸うのをやめてちょうだい。」夫「（　）厳しいことを言わないでよ。」", "options": ["こんなに", "そんなに", "あんなに", "どんなに"], "answer": 2, "explanation_uz": "そんなに = unaqa, shunaqa (suhbatdosh aytganiga ishora)", "tr": "Xotin: «Ertadan tamaki chekishni tashla.» Er: «Unaqa qattiq gaplarni aytma-da.»"}, {"id": "t11-g1-3", "stem": "私は昨日から風邪（　）で、熱が少しある。", "options": ["っぱい", "ほど", "げ", "気味"], "answer": 4, "explanation_uz": "〜気味 = ...ga moyil, ...nishonasi bor. 風邪気味 = shamollaganga o'xshash", "tr": "Men kechadan beri shamollaganga o'xshab, ozroq isitmam bor."}, {"id": "t11-g1-4", "stem": "近所へ散歩に行った（　）、スーパーで牛乳を買ってきました。", "options": ["かたがた", "ついでに", "かわりに", "ままに"], "answer": 2, "explanation_uz": "〜ついでに = ...gan paytda birga, zayli bilan", "tr": "Yaqin atrofga sayrga borgan paytim, zaodan sut ham olib keldim."}, {"id": "t11-g1-5", "stem": "学校から家へ帰る（　）彼女に会ったので、道で少し話しました。", "options": ["途中まで", "途中へ", "途中で", "途中から"], "answer": 3, "explanation_uz": "〜途中で = ...yo'lda, ...yo'l-yo'lakay", "tr": "Maktabdan uyga qaytayotib yo'lda uni uchratdim, ko'chada ozroq gaplashdik."}, {"id": "t11-g1-6", "stem": "この町は、駅を（　）発展してきた。", "options": ["中心とともに", "中心として", "中心において", "中心にかけて"], "answer": 2, "explanation_uz": "〜を中心として = ...ni markaz qilib, ...atrofida", "tr": "Bu shahar bekatni markaz qilib rivojlanib kelgan."}, {"id": "t11-g1-7", "stem": "毎朝私は、ベランダの花に水を（　）。", "options": ["くれます", "もらいます", "やります", "さしあげます"], "answer": 3, "explanation_uz": "やる = (pastga/o'simlik-hayvonga) bermoq. 水をやる = suv quymoq", "tr": "Har kuni ertalab men balkondagi gullarga suv quyaman (beraman)."}, {"id": "t11-g1-8", "stem": "彼女に会うのは、卒業以来3年（　）。", "options": ["よりだ", "ながらだ", "からだ", "ぶりだ"], "answer": 4, "explanation_uz": "〜ぶり = ...dan keyin (vaqt o'tib qaytadan). 3年ぶり = 3 yildan keyin", "tr": "Uni ko'rishim — bitirganimdan beri 3 yildan keyin (3 yil o'tib)."}, {"id": "t11-g1-9", "stem": "弟は先生に何と（　）。", "options": ["お話しなさいましたか", "話されましたか", "おっしゃいましたか", "申しましたか"], "answer": 4, "explanation_uz": "申す = 言う ning kamtarlik shakli (ukam — o'z guruh a'zosi). 申しましたか", "tr": "Ukam o'qituvchiga nima dedi?"}, {"id": "t11-g1-10", "stem": "あの子は、小さい子ども（　）、とてもかしこい。", "options": ["にしては", "のあまり", "であるからには", "からして"], "answer": 1, "explanation_uz": "〜にしては = ...ga qaraganda (kutilganidan farqli)", "tr": "U bola kichkina bola bo'lishiga qaramay, juda aqlli."}, {"id": "t11-g1-11", "stem": "男の学生「ペンを忘れちゃった。」女の学生「私（　）、これを使ってよ。」", "options": ["のもよければ", "のでよければ", "がよいから", "でよいから"], "answer": 2, "explanation_uz": "〜でよければ = ...bo'lsa ham bo'lsa, ...rozimisan. 私の(ペン)でよければ", "tr": "O'g'il bola: «Ruchkamni unutibman.» Qiz bola: «Meniki bo'lsa ham bo'lsa, mana buni ishlat.»"}, {"id": "t11-g1-12", "stem": "あまり時間がないから、食事を（　）、簡単なものにするつもりだ。", "options": ["するとしては", "するとしようと", "するとしても", "するとしようなら"], "answer": 3, "explanation_uz": "〜としても = ...sa ham, ...bo'lgan taqdirda ham", "tr": "Vaqt kam, shuning uchun ovqatlansak ham, oddiy narsa qilmoqchiman."}, {"id": "t11-g1-13", "stem": "私はアイスクリームが大好きなので、お店で見かけると（　）。", "options": ["買おうとしています", "買おうとはしません", "買わないでいられます", "買わないではいられません"], "answer": 4, "explanation_uz": "〜ないではいられない = ...masdan turolmaslik (chiday olmay qilib qo'yish)", "tr": "Men muzqaymoqni juda yaxshi ko'raman, shuning uchun do'konda ko'rsam, sotib olmay turolmayman."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t11-g2-14", "options": ["反して", "予想に", "人々の", "多くの"], "answer": 2, "prefix": "きのうのゲームは", "suffix": "Aチームが勝った。", "starPos": 3, "order": [4, 3, 2, 1], "explanation_uz": "To'g'ri tartib: 多くの人々の予想に反して (〜に反して = ...ga zid)", "tr": "To'g'ri jumla: «Kechagi o'yin ko'pchilik odamlarning bashoratiga zid ravishda A jamoa yutdi.»"}, {"id": "t11-g2-15", "options": ["ものですが", "お菓子を", "こちらの", "いただいた"], "answer": 3, "prefix": "よろしければ、", "suffix": "どうぞ。", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: いただいたものですがこちらのお菓子を (いただく = «olmoq» kamtarlik)", "tr": "To'g'ri jumla: «Agar mayli bo'lsa, mana bu — menga berilgan shirinlikdan, oling.»"}, {"id": "t11-g2-16", "options": ["会議で", "かまわない", "進めても", "決まったように"], "answer": 3, "prefix": "では、このプロジェクトは、先日の", "suffix": "でしょうか。", "starPos": 3, "order": [1, 4, 3, 2], "explanation_uz": "To'g'ri tartib: 会議で決まったように進めてもかまわない", "tr": "To'g'ri jumla: «Demak, bu loyihani o'tgan kungi yig'ilishda hal qilingandek davom ettirsak bo'ladimi?»"}, {"id": "t11-g2-17", "options": ["一方", "なる", "前より", "下手に"], "answer": 2, "prefix": "以前は毎日ピアノの練習をしていましたが、最近はしていないので、", "suffix": "です。", "starPos": 3, "order": [3, 4, 2, 1], "explanation_uz": "To'g'ri tartib: 前より下手になる一方 (〜一方だ = tobora ...bo'lib bormoqda)", "tr": "To'g'ri jumla: «Ilgari har kuni pianino mashq qilardim, lekin yaqinda qilmayapman, shuning uchun avvalgidan yomonlashib boryapman.»"}, {"id": "t11-g2-18", "options": ["なんと", "土地を", "争いは", "めぐる"], "answer": 4, "prefix": "その村の人たちの", "suffix": "数十年間も続いた。", "starPos": 2, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: 土地をめぐる争いはなんと (〜をめぐる = ...yuzasidan, ...haqidagi)", "tr": "To'g'ri jumla: «O'sha qishloq aholisining yer ustidagi janjali nima-niki, o'nlab yillar davom etdi.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "富士山のこと（張拓）", "passage": "土曜、日曜日に、日本に来て初めて、富士山に行きました。日本に来る前は、日本のイメージを代表するものは富士山でした。富士山に{{19}}、前の日の夜はうれしくて、よく眠れませんでした。\n私が友だちと一緒に参加したツアーは、朝早くバスで出発し、まずバスで五合目まで行き、その後、ガイドさんに従って、八合目までのぼり、山小屋にとまって、次の日の朝、頂上を目指すというものです。とても天気がよかったので、頂上で「ご来光」と呼ばれる朝日を{{20}}。本当にきれいでした。\nただ、残念だったのは、ごみがたくさん捨てられていたことです。{{21}}、友だちと下りるときにごみを拾うことにしました。もっていた袋に、見つけたごみを入れていくと、五合目に戻るころには、ごみ袋がいっぱいでした。遠くから見るとあんなに{{22a}}富士山も、実際はこんなに{{22b}}ことがわかって、悲しい気持ちになりました。ガイドさんも、富士山のごみは問題になっている、と言っていました。\n帰ってきてから、パソコンで{{23}}、山を登りながらごみを拾うツアーもあるようです。富士山をきれいにするために、今度はこのようなツアーに参加したいと思いました。", "passage_tr": "Shanba-yakshanba kunlari, Yaponiyaga kelganimdan beri birinchi marta Fuji tog'iga bordim. Yaponiyaga kelishimdan oldin, Yaponiya obrazini eng yaxshi ifodalovchi narsa — Fuji tog'i edi. Fuji tog'iga CHIQA OLAMAN deb o'ylaganimdan, oldingi kechasi xursandligimdan yaxshi uxlay olmadim. Do'stim bilan qatnashgan turimiz ertalab erta avtobusda jo'nab, avval avtobusda 5-bekatgacha borib, so'ng gid ortidan 8-bekatgacha chiqib, tog' kulbasida tunab, ertasi ertalab cho'qqini ko'zlash edi. Havo juda yaxshi bo'lgani uchun, cho'qqida «goraikou» deb ataladigan tong quyoshini KO'RA OLDIK. Rostdan ham go'zal edi. Faqat, afsuski, juda ko'p axlat tashlangani edi. SHUNING UCHUN, do'stim bilan tushayotganda axlat terishga qaror qildik. Olib yurgan xaltamizga topgan axlatni solib borib, 5-bekatga qaytar chog'imizda axlat xaltasi to'lib ketgandi. Uzoqdan qaraganda shunchalik GO'ZAL ko'rinadigan Fuji aslida shunchalik IFLOSLANGANini bilib, hafa bo'ldim. Gid ham Fuji axlati muammoga aylangan deb aytdi. Qaytib kelgach, kompyuterdan QIDIRIB KO'RGANIMDA, tog'ga chiqa turib axlat teradigan turlar ham bor ekan. Fujini toza qilish uchun, keyingi safar shunday turga qatnashmoqchiman.", "questions": [{"id": "t11-g3-19", "options": ["登れると思うと", "登れたと思うと", "登れたと思ったら", "登れと思ったら"], "answer": 1, "blankNo": "19", "explanation_uz": "〜と思うと = ...deb o'ylasa (...ni o'ylab hayajon). 登れる = chiqa olish", "tr": "富士山に[登れると思うと]、前の日…眠れませんでした = Fujiga CHIQA OLAMAN deb o'ylasam, oldingi kechasi uxlay olmadim."}, {"id": "t11-g3-20", "options": ["見られそうでした", "見ることでした", "見ることができました", "見たいと思いました"], "answer": 3, "blankNo": "20", "explanation_uz": "〜ことができる = ...a olmoq (imkoniyat). 見ることができました", "tr": "朝日を[見ることができました] = tong quyoshini KO'RA OLDIK."}, {"id": "t11-g3-21", "options": ["ところで", "そこで", "ところが", "それが"], "answer": 2, "blankNo": "21", "explanation_uz": "そこで = shuning uchun, shu sababli (harakatga o'tish)", "tr": "ごみが…捨てられていた。[そこで]、ごみを拾うことにしました = axlat tashlangan. SHUNING UCHUN, axlat terishga qaror qildik."}, {"id": "t11-g3-22", "options": ["きたない ／ よごれている", "きたない ／ よごれていない", "きれいな ／ よごれていない", "きれいな ／ よごれている"], "answer": 4, "blankNo": "22", "explanation_uz": "22-a きれいな (go'zal) ↔ 22-b よごれている (ifloslangan) — qarama-qarshilik", "tr": "遠くからあんなに[きれいな]富士も、実際はこんなに[よごれている] = uzoqdan GO'ZAL, aslida IFLOSLANGAN."}, {"id": "t11-g3-23", "options": ["調べるものの", "調べようと", "調べるにしたら", "調べたところ"], "answer": 4, "blankNo": "23", "explanation_uz": "〜たところ = ...gan paytda, ...gach (ma'lum bo'ldi)", "tr": "パソコンで[調べたところ]、ツアーもあるようです = kompyuterdan QIDIRIB KO'RGANIMDA, turlar ham bor ekan."}]}]}]}, "12": {"id": 12, "title_jp": "第12回 模擬テスト", "title_uz": "12-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t12-v1-1", "stem": "木の枝が【折れて】います。", "options": ["かれて", "われて", "おれて", "きれて"], "answer": 3, "reading": "おれて", "explanation_uz": "折れる → おれる (singmoq — uzun narsa)", "tr": "Daraxt shoxi singan."}, {"id": "t12-v1-2", "stem": "現金と野菜を【交換】する。", "options": ["こうさい", "こうかん", "こうりゅう", "こうたい"], "answer": 2, "reading": "こうかん", "explanation_uz": "交換 → こうかん (almashtirish)", "tr": "Naqd pul va sabzavotni almashtiramiz."}, {"id": "t12-v1-3", "stem": "新しい【図書】を注文した。", "options": ["としょ", "とじょ", "とうしょ", "とうじょ"], "answer": 1, "reading": "としょ", "explanation_uz": "図書 → としょ (kitob, adabiyot)", "tr": "Yangi kitob buyurtma qildim."}, {"id": "t12-v1-4", "stem": "この国では、【老人】がどんどん増えている。", "options": ["のうじん", "のうにん", "ろうじん", "ろうにん"], "answer": 3, "reading": "ろうじん", "explanation_uz": "老人 → ろうじん (keksa, qariya)", "tr": "Bu mamlakatda keksalar tez ko'paymoqda."}, {"id": "t12-v1-5", "stem": "その【缶】は金曜日に捨ててください。", "options": ["かん", "びん", "きん", "ほん"], "answer": 1, "reading": "かん", "explanation_uz": "缶 → かん (banka, quti — metall)", "tr": "U bankani juma kuni tashlang."}, {"id": "t12-v1-6", "stem": "南は、あちらの【方向】です。", "options": ["ほうく", "ほうこ", "ほうくう", "ほうこう"], "answer": 4, "reading": "ほうこう", "explanation_uz": "方向 → ほうこう (yo'nalish, tomon)", "tr": "Janub — anavi tomonda (yo'nalishda)."}, {"id": "t12-v1-7", "stem": "この料理は、とても【苦い】です。", "options": ["からい", "にがい", "すっぱい", "あまい"], "answer": 2, "reading": "にがい", "explanation_uz": "苦い → にがい (achchiq, taxir)", "tr": "Bu taom juda achchiq (totuvi taxir)."}, {"id": "t12-v1-8", "stem": "公園の【辺り】を散歩します。", "options": ["となり", "ひだり", "まわり", "あたり"], "answer": 4, "reading": "あたり", "explanation_uz": "辺り → あたり (atrof, tevarak)", "tr": "Bog' atrofini aylanaman."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t12-v2-9", "stem": "【ふうん】なことに、事故にあった。", "options": ["不運", "無運", "負運", "未運"], "answer": 1, "explanation_uz": "ふうん → 不運 (baxtsizlik, omadsizlik)", "tr": "Baxtsizlikka — avariyaga uchradim."}, {"id": "t12-v2-10", "stem": "学者としての【じっせき】を上げる。", "options": ["実責", "実積", "実績", "実席"], "answer": 3, "explanation_uz": "じっせき → 実績 (amaliy natija, yutuq)", "tr": "Olim sifatidagi yutuqlarni (natijalarni) oshiraman."}, {"id": "t12-v2-11", "stem": "森の中で【まよって】、一晩中歩き続けた。", "options": ["悩って", "困って", "寄って", "迷って"], "answer": 4, "explanation_uz": "まよう → 迷う (adashmoq, yo'l yo'qotmoq)", "tr": "O'rmonda adashib, tun bo'yi yurdim."}, {"id": "t12-v2-12", "stem": "この動物園では、動物に【さわる】ことができます。", "options": ["採る", "触る", "解る", "探る"], "answer": 2, "explanation_uz": "さわる → 触る (tegmoq, ushlamoq)", "tr": "Bu hayvonot bog'ida hayvonlarga tegish mumkin."}, {"id": "t12-v2-13", "stem": "実家は【のうぎょう】を営んでいます。", "options": ["漁業", "林業", "工業", "農業"], "answer": 4, "explanation_uz": "のうぎょう → 農業 (dehqonchilik, qishloq xo'jaligi)", "tr": "Ota uyim dehqonchilik (qishloq xo'jaligi) bilan shug'ullanadi."}, {"id": "t12-v2-14", "stem": "この店には、よい【しなもの】が置いてある。", "options": ["商品", "商者", "品物", "品者"], "answer": 3, "explanation_uz": "しなもの → 品物 (mol, buyum, narsa)", "tr": "Bu do'konda yaxshi mol (buyum) bor."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t12-v3-15", "stem": "彼の日曜日のすごし方は、いつも同じ（　）だ。", "options": ["フォーム", "カラー", "ライン", "パターン"], "answer": 4, "explanation_uz": "パターン = qolip, andoza, naqsh", "tr": "Uning yakshanbani o'tkazish tarzi doim bir xil andoza (qolip)."}, {"id": "t12-v3-16", "stem": "どのようにして事故が起きたのか、細かく（　）した。", "options": ["等分", "分析", "分担", "配分"], "answer": 2, "explanation_uz": "分析 = tahlil", "tr": "Avariya qanday yuz berganini batafsil tahlil qildim."}, {"id": "t12-v3-17", "stem": "食事を全部食べないで捨てるのは（　）。", "options": ["うらやましい", "めんどうくさい", "こまかい", "もったいない"], "answer": 4, "explanation_uz": "もったいない = isrof, achinarli, behuda ketkazish", "tr": "Ovqatni to'liq yemay tashlash — isrofgarchilik (achinarli)."}, {"id": "t12-v3-18", "stem": "夏休みは、いつも海外の別荘で（　）います。", "options": ["住んで", "過ごして", "離れて", "戻って"], "answer": 2, "explanation_uz": "過ごす = (vaqt) o'tkazmoq", "tr": "Yozgi ta'tilni doim chet eldagi dala hovlida o'tkazaman."}, {"id": "t12-v3-19", "stem": "コーヒーを（　）飲みに行きませんか。", "options": ["一口", "一杯", "一個", "一枚"], "answer": 2, "explanation_uz": "一杯 = bir piyola/stakan (ichimlik sanog'i)", "tr": "Bir piyola kofe ichgani bormaymizmi?"}, {"id": "t12-v3-20", "stem": "この1年で身長が10センチも（　）。", "options": ["太った", "得た", "ふくらんだ", "伸びた"], "answer": 4, "explanation_uz": "伸びる = o'smoq, cho'zilmoq (bo'y)", "tr": "Shu bir yilda bo'yim 10 santimetr o'sdi."}, {"id": "t12-v3-21", "stem": "荷物を受け取るときに、（　）を求められた。", "options": ["マーク", "ポスト", "サイン", "クレーム"], "answer": 3, "explanation_uz": "サイン = imzo", "tr": "Yukni olayotganda imzo (sayn) so'rashdi."}, {"id": "t12-v3-22", "stem": "私（　）の手紙が来ていませんか。", "options": ["行き", "向き", "届け", "あて"], "answer": 4, "explanation_uz": "〜あて = ...ga atalgan, ...nomiga (manzil)", "tr": "Menga atalgan (mening nomimga) xat kelmadimi?"}, {"id": "t12-v3-23", "stem": "他の会社に送る書類の（　）をするよう、部下に指示した。", "options": ["提示", "作成", "集合", "設定"], "answer": 2, "explanation_uz": "作成 = tuzish, tayyorlash (hujjat)", "tr": "Boshqa kompaniyaga yuboriladigan hujjatni tayyorlashni xodimimga topshirdim."}, {"id": "t12-v3-24", "stem": "いそがしい1日だったので、家に帰ると（　）した。", "options": ["はっと", "さっと", "ほっと", "ざっと"], "answer": 3, "explanation_uz": "ほっとする = yengil tortmoq, tinchlanmoq", "tr": "Band kun bo'lgani uchun, uyga qaytsam yengil tortdim (tinchlandim)."}, {"id": "t12-v3-25", "stem": "その文章は、（　）なことばで書かれていた。", "options": ["不足", "丈夫", "明確", "優秀"], "answer": 3, "explanation_uz": "明確 = aniq, ravshan", "tr": "U matn aniq (ravshan) so'zlar bilan yozilgan edi."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t12-v4-26", "stem": "その旅館の部屋はとても【清潔だ】。", "options": ["古い", "かわいい", "きれいだ", "明るい"], "answer": 3, "explanation_uz": "清潔 = toza, ozoda → きれいだ", "tr": "U mehmonxona xonasi juda toza."}, {"id": "t12-v4-27", "stem": "仕事の準備が【整った】。", "options": ["続行した", "停止した", "開始した", "終了した"], "answer": 4, "explanation_uz": "整う = tartibga tushmoq, tayyor bo'lmoq → 終了した (yakunlandi)", "tr": "Ish tayyorgarligi yakunlandi (bitdi)."}, {"id": "t12-v4-28", "stem": "彼は、友だちを【ぶって】しまった。", "options": ["手で打って", "足でけって", "体をぶつけて", "悪口を言って"], "answer": 1, "explanation_uz": "ぶつ = urmoq (qo'l bilan) → 手で打って", "tr": "U do'stini urib qo'ydi (qo'li bilan)."}, {"id": "t12-v4-29", "stem": "映画館は【がらがらだ】。", "options": ["広い", "汚い", "こんでいる", "すいている"], "answer": 4, "explanation_uz": "がらがら = bo'm-bo'sh, huvillagan → すいている", "tr": "Kinoteatr huvillab yotibdi (bo'm-bo'sh)."}, {"id": "t12-v4-30", "stem": "デパートの【向かい】に本屋があります。", "options": ["正面", "手前", "先", "後ろ"], "answer": 1, "explanation_uz": "向かい = ro'para, qarshi tomon → 正面", "tr": "Univermag ro'parasida kitob do'koni bor."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t12-v5-31", "stem": "合わせる", "options": ["毎朝、彼女と駅で合わせて一緒に学校へ行く。", "友だちと声を合わせて、歌を歌った。", "私の趣味は、外国の切手を合わせることです。", "父と母は、学生のころに合わせて、結婚した。"], "answer": 2, "optsTr": ["Har kuni u bilan bekatda 'moslashib' maktabga boraman (noto'g'ri — 待ち合わせる kerak).", "Do'stim bilan ovozni qo'shib, qo'shiq aytdik. (to'g'ri)", "Mening sevimli mashg'ulotim — chet el markalarini 'moslashtirish' (noto'g'ri — 集める kerak).", "Ota-onam talabalik chog'ida 'moslashib', turmush qurishdi (noto'g'ri — 出会う kerak)."], "tr": "合わせる = moslashtirmoq, qo'shmoq, birlashtirmoq."}, {"id": "t12-v5-32", "stem": "いきおい", "options": ["この魚は、とてもいきおいがよくておいしい。", "パソコンのいきおいが悪いので、修理をすることにした。", "今日は体のいきおいがいいので、とても元気です。", "その子どもたちは、いきおいよく走りだした。"], "answer": 4, "optsTr": ["Bu baliq 'shiddati' yaxshi va mazali (noto'g'ri — 新鮮 kerak).", "Kompyuter 'shiddati' yomon, ta'mirlaydigan bo'ldim (noto'g'ri — 調子 kerak).", "Bugun tana 'shiddati' yaxshi, juda tetikman (noto'g'ri — 調子 kerak).", "O'sha bolalar shiddat bilan yugurib ketishdi. (to'g'ri)"], "tr": "いきおい(勢い) = shiddat, kuch, jadallik."}, {"id": "t12-v5-33", "stem": "坂", "options": ["長い坂を渡って、家に帰りました。", "ここは、日本でいちばん高い坂です。", "私の学校は、急な坂の上に建っています。", "強い風で坂がすべって、たくさんの人がけがをしました。"], "answer": 3, "optsTr": ["Uzun qiyalikni 'kechib' uyga qaytdim (noto'g'ri — のぼる kerak).", "Bu yer Yaponiyadagi eng baland 'qiyalik' (noto'g'ri — 山 kerak).", "Mening maktabim tik qiyalik ustida joylashgan. (to'g'ri)", "Kuchli shamoldan 'qiyalik sirpanib', ko'p odam jarohatlandi (noto'g'ri — 道 kerak)."], "tr": "坂(さか) = qiyalik, do'nglik, qir yo'l."}, {"id": "t12-v5-34", "stem": "すがた", "options": ["この音楽は、すがたがとてもいいので好きです。", "私の兄と弟は、声のすがたがよく似ています。", "有名なレストランで、肉のすがたを食べました。", "さっき駅前で、彼女のすがたを見かけました。"], "answer": 4, "optsTr": ["Bu musiqaning 'qiyofasi' yaxshi, yoqadi (noto'g'ri — メロディー kerak).", "Akam va ukam 'ovoz qiyofasi' o'xshash (noto'g'ri — 声 kerak).", "Mashhur restoranda 'go'sht qiyofasi'ni yedim (noto'g'ri — 料理 kerak).", "Hozir bekat oldida uning qiyofasini ko'rib qoldim. (to'g'ri)"], "tr": "すがた(姿) = qiyofa, ko'rinish, gavda."}, {"id": "t12-v5-35", "stem": "はげしい", "options": ["歩いていたら、雨がはげしくふり出した。", "彼の日本語は、この数カ月でとてもはげしくなった。", "この紅茶ははげしくておいしいので、おかわりをください。", "今日は、朝から何も食べていないので、おなかがはげしい。"], "answer": 1, "optsTr": ["Yurib ketayotsam, yomg'ir qattiq yog'a boshladi. (to'g'ri)", "Uning yaponchasi shu oylarda juda 'shiddatli' bo'ldi (noto'g'ri — 上達 kerak).", "Bu choy 'shiddatli' va mazali, yana quying (noto'g'ri — 濃い kerak).", "Bugun ertalabdan yemadim, qornim 'shiddatli' (noto'g'ri — すく kerak)."], "tr": "はげしい(激しい) = qattiq, shiddatli, kuchli."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t12-g1-1", "stem": "男性「どんなマンガが好きですか。」女性「私はマンガ（　）は読みません。時間のむだですから。」", "options": ["しか", "ほど", "から", "など"], "answer": 4, "explanation_uz": "〜など = ...-panga (mensimaslik, pisanda)", "tr": "Erkak: «Qanday manga yoqadi?» Ayol: «Men manga-panga o'qimayman. Vaqtni behuda ketkazadi.»"}, {"id": "t12-g1-2", "stem": "私の息子は、まだ10歳の子どもの（　）、高いものをほしがる。", "options": ["ものに", "ところに", "くせに", "きりに"], "answer": 3, "explanation_uz": "〜くせに = ...bo'la turib (norozilik, ayb qo'yish)", "tr": "O'g'lim hali 10 yoshli bola bo'la turib, qimmat narsalarni xohlaydi."}, {"id": "t12-g1-3", "stem": "一生けん命走った（　）、電車に間に合わなかった。", "options": ["からには", "からといって", "あげく", "あまり"], "answer": 3, "explanation_uz": "〜あげく = ...gan oqibatda (ko'pincha yomon natija)", "tr": "Jon-jahdim bilan yugurdim-u, oqibatda poyezdga ulgurmadim."}, {"id": "t12-g1-4", "stem": "大事な会議の（　）、また後で電話してください。", "options": ["最中として", "最中なので", "最中であって", "最中ながら"], "answer": 2, "explanation_uz": "〜最中なので = ayni ...ayotgan payt bo'lgani uchun", "tr": "Muhim yig'ilishning ayni qizg'in payti bo'lgani uchun, keyinroq telefon qiling."}, {"id": "t12-g1-5", "stem": "家族と食事をしている（　）、学校の友だちが遊びに来た。", "options": ["ところで", "ところは", "ところが", "ところへ"], "answer": 4, "explanation_uz": "〜ているところへ = ayni ...ayotgan paytga (kimdir keladi)", "tr": "Oila bilan ovqatlanib o'tirgan paytimga maktab do'stim o'ynagani keldi."}, {"id": "t12-g1-6", "stem": "母「手術が成功するか心配で…」娘「手術（　）すぐに終わるし、心配しないで。」", "options": ["というと", "といえば", "といっても", "といったら"], "answer": 3, "explanation_uz": "〜といっても = ...desa ham, ...deyilsa-da", "tr": "Ona: «Operatsiya muvaffaqiyatli bo'ladimi deb tashvishlanyapman…» Qiz: «Operatsiya desa ham tez tugaydi, xavotir olma.»"}, {"id": "t12-g1-7", "stem": "もし外国に（　）のなら、フィンランドに住んでみたい。", "options": ["住む", "住み", "住んで", "住んだ"], "answer": 1, "explanation_uz": "〜のなら = ...adigan bo'lsa (shart). 住むのなら", "tr": "Agar chet elda yashaydigan bo'lsam, Finlyandiyada yashab ko'rmoqchiman."}, {"id": "t12-g1-8", "stem": "田中「ぼくはカレーライス。」鈴木「私はとんかつ（　）。」", "options": ["にします", "をします", "としています", "でしています"], "answer": 1, "explanation_uz": "〜にする = ...ga qaror qilmoq, ...ni tanlamoq", "tr": "Tanaka: «Men karri guruch.» Suzuki: «Men tonkatsu olaman (tanladim).»"}, {"id": "t12-g1-9", "stem": "社長は何かスポーツを（　）。", "options": ["まいりますか", "なさいますか", "いたしますか", "いらっしゃいますか"], "answer": 2, "explanation_uz": "なさる = する ning hurmat shakli (qiladilar)", "tr": "Rahbar biror sport bilan shug'ullanadilarmi?"}, {"id": "t12-g1-10", "stem": "小学生のころ、父は私に勉強を教えて（　）。", "options": ["やりました", "あげました", "さしあげました", "くれました"], "answer": 4, "explanation_uz": "〜てくれる = (boshqa kishi menga) ...ib bermoq. 教えてくれました", "tr": "Boshlang'ich sinfda otam menga darsni o'rgatib berardi."}, {"id": "t12-g1-11", "stem": "自分がいじめられたから、友だちをいじめていい（　）。", "options": ["というはずではない", "といったものだ", "ということにはならない", "というわけだ"], "answer": 3, "explanation_uz": "〜ということにはならない = ...degani bo'lmaydi", "tr": "O'zing zo'ravonlikka uchraganing uchun, do'stingni xafa qilsang bo'ladi degani emas."}, {"id": "t12-g1-12", "stem": "これが、みんながずっと探していた宝物に（　）。", "options": ["ほかなります", "ほかなりません", "ほかにあります", "ほかにありません"], "answer": 2, "explanation_uz": "〜にほかならない = aynan ...ning o'zi, boshqa narsa emas", "tr": "Mana shu — hamma uzoq izlagan xazinaning aynan o'zginasi."}, {"id": "t12-g1-13", "stem": "子どものころ、病気で苦しむ私に、母は「（　）代わりたい」と言って泣いていた。", "options": ["代わったならば", "代わりたいけれど", "代わるものでも", "代われるものなら"], "answer": 4, "explanation_uz": "〜ものなら = iloji bo'lsa (amalga oshishi qiyin istak). 代われるものなら", "tr": "Bolaligimda kasallikdan azob chekayotganimda, onam «iloji bo'lsa o'rningga o'tardim» deb yig'lardi."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t12-g2-14", "options": ["一生けん命", "こたえて", "がんばろうと", "期待に"], "answer": 3, "prefix": "みなさまの", "suffix": "思います。", "starPos": 4, "order": [4, 2, 1, 3], "explanation_uz": "To'g'ri tartib: 期待にこたえて一生けん命がんばろうと (〜にこたえる = ...ni oqlamoq)", "tr": "To'g'ri jumla: «Barchangizning umidingizni oqlab, jon-jahdim bilan harakat qilmoqchiman.»"}, {"id": "t12-g2-15", "options": ["でしたら", "めしあがりたい", "お酒を", "の"], "answer": 2, "prefix": "お茶しか用意していませんが、先生がもし", "suffix": "注文します。", "starPos": 2, "order": [3, 2, 4, 1], "explanation_uz": "To'g'ri tartib: お酒をめしあがりたいのでしたら (めしあがる = «yemoq/ichmoq» hurmat shakli)", "tr": "To'g'ri jumla: «Faqat choy tayyorlaganman, lekin agar o'qituvchi ichimlik ichmoqchi bo'lsalar, buyurtma beraman.»"}, {"id": "t12-g2-16", "options": ["からで", "確かめて", "ないと", "なんとも"], "answer": 3, "prefix": "三上「そのことなんですが、担当者に", "suffix": "言えないんですよ。」", "starPos": 3, "order": [2, 1, 3, 4], "explanation_uz": "To'g'ri tartib: 確かめてからでないと (〜てからでないと = ...gandan keyingina)", "tr": "To'g'ri jumla: «Aytmoqchimanki, mas'ul xodimdan tasdiqlamasdan turib, hech narsa deya olmayman.»"}, {"id": "t12-g2-17", "options": ["かねない", "病気が", "なり", "悪く"], "answer": 3, "prefix": "このまま治療をしないと、", "suffix": "と医者に言われました。", "starPos": 3, "order": [2, 4, 3, 1], "explanation_uz": "To'g'ri tartib: 病気が悪くなりかねない (〜かねない = ...ib qolishi mumkin, yomon ehtimol)", "tr": "To'g'ri jumla: «Shu zayilda davolanmasangiz, kasallik kuchayib ketishi mumkin deb shifokor aytdi.»"}, {"id": "t12-g2-18", "options": ["ある事件を", "有名な", "歴史上", "もとに"], "answer": 1, "prefix": "私が今、読んでいる本は、", "suffix": "書かれている。", "starPos": 3, "order": [3, 2, 1, 4], "explanation_uz": "To'g'ri tartib: 歴史上有名なある事件をもとに (〜をもとに = ...ga asoslanib)", "tr": "To'g'ri jumla: «Men hozir o'qiyotgan kitob tarixdagi mashhur bir voqeaga asoslanib yozilgan.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "片づけは必要か", "passage": "「そうじ」「片づけ」「整理」をテーマにした本がたくさん出版されているのを{{19}}。「そうじ名人になるには」「あなたも片づけられる人になろう！」「お部屋の整理術」……書店に行くと、このようなタイトルの本を{{20}}。著者は、有名人のこともあれば一般人のこともある。どちらにしても「片づけ名人」が書いた本であることはまちがいない。また、このような種類の本は、よく売れているようだ。{{21}}、それだけ「片づけられない人」「整理が苦手な人」が世の中にたくさんいるということだろう。\n実は、私自身も「片づけられない人間」の1人である。部屋はいつも汚い。机の引き出しの中も物がたくさんつまっているし、部屋のあちこちに、本や服などいろいろなものが積み重なっている。\nしかし、私自身について言えば、そうであっても{{22a}}身の回りを整理しよう、片づけよう{{22b}}。たぶん、すべてが整理された、とてもきれいな部屋は、逆に気持ちが落ちつかないことと、片づけをする時間が十分にとれないことが理由だろう。私は今のところ、整理や片づけの本を読んでまで部屋を片づけようと{{23}}。", "passage_tr": "«Tozalash», «yig'ishtirish», «tartibga solish» mavzusidagi kitoblar juda ko'p chop etilayotganini BILASIZMI? «Tozalash ustasi bo'lish uchun», «Siz ham yig'ishtira oladigan inson bo'ling!», «Xona tartibi san'ati»… kitob do'koniga borsangiz, shunday sarlavhali kitoblarni KO'RMAY ILOJINGIZ YO'Q (albatta ko'rasiz). Mualliflar goh mashhur, goh oddiy odamlar bo'ladi. Qaysidir bo'lsa-da, «tartib ustasi» yozgan kitob ekani aniq. Bunday kitoblar yaxshi sotilayotganga o'xshaydi. QISQASI, demak dunyoda «yig'ishtira olmaydigan», «tartibga qiynaladigan» odamlar shunchalik ko'p degani. Aslida, men ham «yig'ishtira olmaydigan odam»lardan biriman. Xonam doim kir. Stol tortmasi ham narsaga to'la, xonaning hamma yog'ida kitob, kiyim kabilar uyilib yotadi. Lekin, o'zim haqimda aytsam, shunday bo'lsa ham, ATAYIN atrofni tartibga solay, yig'ishtiray DEGAN FIKR KELMAYDI. Ehtimol, hammasi tartibli, juda toza xona aksincha ko'nglimni g'ash qilishi va yig'ishtirishga vaqt yetarli topa olmasligim sabab bo'lsa kerak. Men hozircha, tartib-tozalik kitobini o'qibgacha xonamni yig'ishtiray deb O'YLAMAYMAN.", "questions": [{"id": "t12-g3-19", "options": ["うかがっただろうか", "おうかがいしただろうか", "存じているだろうか", "ご存じだろうか"], "answer": 4, "blankNo": "19", "explanation_uz": "ご存じだろうか = bilasizmi (知っている ning hurmat shakli)", "tr": "本が…出版されているのを[ご存じだろうか] = …chop etilayotganini BILASIZMI? (o'quvchiga hurmat)."}, {"id": "t12-g3-20", "options": ["見かけたものだ", "見かけることなどない", "見かけないといってよい", "見かけないことはない"], "answer": 4, "blankNo": "20", "explanation_uz": "〜ないことはない = ...masdan iloji yo'q (albatta shunday). Ikki inkor = tasdiq", "tr": "書店で…本を[見かけないことはない] = ...kitoblarni KO'RMAY ILOJING yo'q (albatta ko'rasan)."}, {"id": "t12-g3-21", "options": ["要するに", "それどころか", "とはいうものの", "だからといって"], "answer": 1, "blankNo": "21", "explanation_uz": "要するに = qisqasi, xullas (xulosa)", "tr": "よく売れている。[要するに]、…人がたくさんいる = yaxshi sotiladi. QISQASI, ...odamlar ko'p."}, {"id": "t12-g3-22", "options": ["わざと ／ ということになっている", "わざと ／ という気にならない", "わざわざ ／ ということになっている", "わざわざ ／ という気にならない"], "answer": 4, "blankNo": "22", "explanation_uz": "22-a わざわざ (atayin, ovora bo'lib) + 22-b という気にならない (...gisi kelmaydi)", "tr": "[わざわざ]整理しよう…[という気にならない] = ATAYIN tartibga solay degan FIKR KELMAYDI."}, {"id": "t12-g3-23", "options": ["思わないでもない", "思うことは思う", "思う", "思わない"], "answer": 4, "blankNo": "23", "explanation_uz": "思わない = o'ylamayman (sodda inkor)", "tr": "本を読んでまで…片づけようと[思わない] = ...kitob o'qibgacha yig'ishtiray deb O'YLAMAYMAN."}]}]}]}, "13": {"id": 13, "title_jp": "第13回 模擬テスト", "title_uz": "13-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t13-v1-1", "stem": "プレゼントにリボンが【結んで】ありました。", "options": ["あんで", "たたんで", "はさんで", "むすんで"], "answer": 4, "reading": "むすんで", "explanation_uz": "結ぶ → むすぶ (bog'lamoq)", "tr": "Sovg'aga lenta bog'lab qo'yilgan edi."}, {"id": "t13-v1-2", "stem": "この病院は、【患者】の数が多い。", "options": ["かんしゃ", "がんしゃ", "かんじゃ", "がんじゃ"], "answer": 3, "reading": "かんじゃ", "explanation_uz": "患者 → かんじゃ (bemor, kasal)", "tr": "Bu kasalxonada bemorlar soni ko'p."}, {"id": "t13-v1-3", "stem": "そのやり方で、【効果】がありますか。", "options": ["きょか", "きょうか", "こか", "こうか"], "answer": 4, "reading": "こうか", "explanation_uz": "効果 → こうか (samara, natija)", "tr": "U usul bilan natija bor (samara beradi)mi?"}, {"id": "t13-v1-4", "stem": "苦しいとき、クラスメートに【支えて】もらった。", "options": ["おしえて", "ささえて", "つかえて", "かかえて"], "answer": 2, "reading": "ささえて", "explanation_uz": "支える → ささえる (tayanch bo'lmoq, qo'llab-quvvatlamoq)", "tr": "Qiyin paytda sinfdoshim menga tayanchlik qildi (qo'llab-quvvatladi)."}, {"id": "t13-v1-5", "stem": "この【城】はとても有名です。", "options": ["しろ", "とう", "てら", "もん"], "answer": 1, "reading": "しろ", "explanation_uz": "城 → しろ (qal'a, qo'rg'on)", "tr": "Bu qal'a (shahar) juda mashhur."}, {"id": "t13-v1-6", "stem": "用事があるので、お先に【失礼】します。", "options": ["つごう", "しごと", "ようじ", "しょよう"], "answer": 3, "reading": "ようじ", "explanation_uz": "用事 → ようじ (ish, yumush, vazifa)", "tr": "Ishim bor, men oldin ketaman (uzr)."}, {"id": "t13-v1-7", "stem": "毎日、とても【退屈】だ。", "options": ["さいくつ", "きゅうくつ", "たいくつ", "ていくつ"], "answer": 3, "reading": "たいくつ", "explanation_uz": "退屈 → たいくつ (zerikish, zerikarlilik)", "tr": "Har kuni juda zerikarlim (zerikarli)."}, {"id": "t13-v1-8", "stem": "新しい法案が【成立】した。", "options": ["せいりつ", "ぜいりつ", "しょうりつ", "じょうりつ"], "answer": 1, "reading": "せいりつ", "explanation_uz": "成立 → せいりつ (qabul qilinmoq, kuchga kirmoq — qonun/shartnoma)", "tr": "Yangi qonun loyihasi qabul qilindi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t13-v2-9", "stem": "日程については、メールで【つうち】します。", "options": ["通知", "通告", "報知", "報告"], "answer": 1, "explanation_uz": "つうち → 通知 (xabardor qilish, bildirish)", "tr": "Jadval haqida email orqali xabar beraman."}, {"id": "t13-v2-10", "stem": "彼は、必死に働いて、今の【ちい】についた。", "options": ["時位", "自位", "値位", "地位"], "answer": 4, "explanation_uz": "ちい → 地位 (maqom, lavozim, o'rin)", "tr": "U jon-jahd ishlab, hozirgi maqomiga erishdi."}, {"id": "t13-v2-11", "stem": "カップラーメンにお湯を【そそいで】、3分待った。", "options": ["主いで", "注いで", "往いで", "往いで"], "answer": 2, "explanation_uz": "そそぐ → 注ぐ (quymoq — suyuqlik)", "tr": "Stakan lapmonga qaynoq suv quyib, 3 daqiqa kutdim."}, {"id": "t13-v2-12", "stem": "友だちを家に【まねく】。", "options": ["積く", "届く", "描く", "招く"], "answer": 4, "explanation_uz": "まねく → 招く (taklif qilmoq, chaqirmoq)", "tr": "Do'stimni uyga taklif qilaman."}, {"id": "t13-v2-13", "stem": "見つけたお金を【けいさつ】に持っていった。", "options": ["警官", "警察", "検察", "検事"], "answer": 2, "explanation_uz": "けいさつ → 警察 (politsiya)", "tr": "Topgan pulni politsiyaga olib bordim."}, {"id": "t13-v2-14", "stem": "この国では、石油の【ゆしゅつ】が増えている。", "options": ["移出", "移入", "輸出", "輸入"], "answer": 3, "explanation_uz": "ゆしゅつ → 輸出 (eksport, tashqariga chiqarish)", "tr": "Bu mamlakatda neft eksporti o'sib bormoqda."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t13-v3-15", "stem": "父は、（　）の運転手だったのに、仕事中に事故を起こした。", "options": ["アマチュア", "スマート", "ベテラン", "ピーク"], "answer": 3, "explanation_uz": "ベテラン = tajribali mutaxassis (veteran)", "tr": "Otam tajribali haydovchi bo'la turib, ish paytida avariya qildi."}, {"id": "t13-v3-16", "stem": "英語の本を日本語に（　）した。", "options": ["違約", "要約", "通訳", "翻訳"], "answer": 4, "explanation_uz": "翻訳 = yozma tarjima (翻訳する = tarjima qilmoq)", "tr": "Inglizcha kitobni yaponchaga tarjima qildim."}, {"id": "t13-v3-17", "stem": "運動をしなくなってから、（　）がなくなってきた。", "options": ["人体", "本体", "体格", "体力"], "answer": 4, "explanation_uz": "体力 = jismoniy quvvat, chidamlilik", "tr": "Sport qilishni to'xtatganimdan beri jismoniy quvvatim (kuchim) yo'qoldi."}, {"id": "t13-v3-18", "stem": "洗たくに失敗し、シャツが（　）小さくなってしまった。", "options": ["冷えて", "こげて", "縮んで", "伸びて"], "answer": 3, "explanation_uz": "縮む → 縮んで = kichirayib (qisqarib) qolmoq", "tr": "Kir yuvishda xato qilib, ko'ylak kichirayib qoldi."}, {"id": "t13-v3-19", "stem": "彼女に秘密を（　）された。", "options": ["告白", "宣言", "会話", "通話"], "answer": 3, "explanation_uz": "会話 = suhbat; 秘密を会話された = siri haqida gaplashildi (aytib qo'yildi)", "tr": "U sirini menga aytib berdi (ichini to'kdi)."}, {"id": "t13-v3-20", "stem": "この魚は、私の国では高級（　）です。", "options": ["物", "者", "品", "体"], "answer": 3, "explanation_uz": "高級品 = yuqori sifatli mahsulot (品 = tovar, mahsulot)", "tr": "Bu baliq mening mamlakatimda yuqori sinfli mahsulot."}, {"id": "t13-v3-21", "stem": "ドアを（　）したのに、だれも出て来なかった。", "options": ["ヒット", "ノック", "プレー", "チャイム"], "answer": 2, "explanation_uz": "ノック(する) = taqillatmoq (eshikni)", "tr": "Eshikni taqillatdim, ammo hech kim chiqmadi."}, {"id": "t13-v3-22", "stem": "車をもっと右（　）に止めてください。", "options": ["寄り", "止め", "置き", "並べ"], "answer": 1, "explanation_uz": "右寄り = o'ng tomonga surilgan (寄り = tomonga)", "tr": "Mashinani o'ng tomonga surib to'xtating."}, {"id": "t13-v3-23", "stem": "母は、（　）して私を育ててくれた。", "options": ["緊張", "否定", "苦労", "要求"], "answer": 3, "explanation_uz": "苦労(する) = qiyinchilik chekmoq, mehnat qilmoq", "tr": "Onam qiyinchilik bilan meni tarbiyalab o'stirdi."}, {"id": "t13-v3-24", "stem": "好きな人に顔を見つめられて、（　）した。", "options": ["ほかほか", "ふらふら", "どきどき", "はらはら"], "answer": 3, "explanation_uz": "どきどき(する) = yurak duk-duk urmoq (hayajonlanmoq)", "tr": "Yoqtirgan odamim menga tikilganida, yuragim duk-duk urdi."}, {"id": "t13-v3-25", "stem": "私のペットの犬は、とても（　）だ。", "options": ["快速", "温暖", "急速", "利口"], "answer": 4, "explanation_uz": "利口 = aqlli, ziyrak (hayvon uchun ham ishlatiladi)", "tr": "Uy itim juda aqlli."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t13-v4-26", "stem": "くやしい気持ちを日記に書いた。", "options": ["うれしい", "満足な", "さびしい", "残念な"], "answer": 4, "explanation_uz": "くやしい = afsus, o'kinch → 残念な", "tr": "Afsuslanish hissini kundalikka yozdim."}, {"id": "t13-v4-27", "stem": "進足について、みんなの意見は【ばらばらだ】。", "options": ["全部同じ", "全部ちがう", "二つにわかれた", "賛成でまとまった"], "answer": 2, "explanation_uz": "ばらばら = tarqoq, har xil → 全部ちがう", "tr": "Jadval haqida hammaning fikri turlicha (tarqoq)."}, {"id": "t13-v4-28", "stem": "このセーターは、あなたに【ぴったりです】。", "options": ["大きすぎます", "小さすぎます", "似合います", "似合いません"], "answer": 3, "explanation_uz": "ぴったり = aynan mos, to'g'ri kelmoq → 似合います", "tr": "Bu sviter sizga juda mos."}, {"id": "t13-v4-29", "stem": "意見を必ず【述べて】ください。", "options": ["話して", "聞いて", "出して", "考えて"], "answer": 1, "explanation_uz": "述べる = bayon etmoq, aytmoq → 話して", "tr": "Fikringizni albatta bildiring (aytib bering)."}, {"id": "t13-v4-30", "stem": "山小屋にあったのは、【わずかな】食べ物だった。", "options": ["たくさんの", "少しの", "残りの", "あまりの"], "answer": 2, "explanation_uz": "わずか = juda oz, kamchilik → 少しの", "tr": "Tog' kulbasida oz miqdorda ovqat bor edi."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t13-v5-31", "stem": "飼う", "options": ["私の家では、子どもを2人飼っている。", "花を飼いたいと思って、花屋へ行きました。", "子どものころ、家で牛と馬を飼っていました。", "木の上で、親鳥が子どもの鳥を飼っています。"], "answer": 3, "optsTr": ["Uyimizda 2 ta bola «boqilmoqda» (noto'g'ri — 育てる kerak).", "Gul «boqmoq» istab gulchilikka bordim (noto'g'ri — 買う kerak).", "Bolaligimda uyda sigir va ot boqardik. (to'g'ri) ✓", "Daraxt ustida ota qush bolasini «boqmoqda» (noto'g'ri — 育てる kerak)."], "tr": "飼う(かう) = (hayvon) boqmoq, parvarishlamoq."}, {"id": "t13-v5-32", "stem": "なぐる", "options": ["怒った男性は、もう1人の男性を力いっぱいなぐった。", "そのサッカー選手は、右足で思いきりボールをなぐった。", "交差点で車と自転車がなぐって、大きな事故になった。", "部屋に入る前には、ドアをなぐってください。"], "answer": 1, "optsTr": ["Jahli chiqqan erkak boshqa erkakni bor kuchi bilan urdi. (to'g'ri) ✓", "Futbolchi to'pni musht urdi (noto'g'ri — 蹴る kerak).", "Chorrahada mashina va velosiped musht urib ketdi (noto'g'ri — ぶつかる kerak).", "Xonaga kirish oldidan eshikni musht uring (noto'g'ri — ノックする kerak)."], "tr": "なぐる = musht urmoq, urib yubormoq (odamga)."}, {"id": "t13-v5-33", "stem": "隅", "options": ["授業の隅で、先生が大事なことを言いました。", "部屋の隅に、小さないすが置いてあります。", "もう12月なので、1年も隅ですね。", "髪の毛の隅に、ごみがついていました。"], "answer": 2, "optsTr": ["Darsning «burchagida» o'qituvchi muhim narsa aytdi (noto'g'ri — 隅 = jismoniy burchak).", "Xona burchagida kichkina stul turadi. (to'g'ri) ✓", "Dekabr bo'lgani uchun yil ham «burchag'i»... (noto'g'ri — 終わり kerak).", "Sochning «burchagiga» axlat yopishdi (noto'g'ri — 先端 kerak)."], "tr": "隅(すみ) = burchak (xona, joy)."}, {"id": "t13-v5-34", "stem": "背中", "options": ["あの男の人は、とても背中が高い。", "朝から何も食べていないので、背中がすきました。", "田中さんの家は、私の家の背中にあります。", "ずっとパソコンに向かって座っていたら、背中が痛くなった。"], "answer": 4, "optsTr": ["U erkakning «orqasi» juda baland (noto'g'ri — 背が高い = bo'yi baland).", "Yemadim, «orqam» och bo'ldi (noto'g'ri — おなかがすく kerak).", "Tanakaning uyi mening uyimning «orqasida» (noto'g'ri — 後ろ kerak).", "Uzoq kompyuter oldida o'tirdim, belim og'ridi. (to'g'ri) ✓"], "tr": "背中(せなか) = orqa (tana qismi)."}, {"id": "t13-v5-35", "stem": "単純", "options": ["その事件は、ある単純な夜に起こった。", "この問題は、とても単純なので答えがすぐわかるでしょう。", "地震のときは、単純なものを持って逃げてください。", "すばらしい映画を見て、とても単純な気持ちになった。"], "answer": 2, "optsTr": ["U voqea «oddiy» bir kechada bo'ldi (noto'g'ri — 文脈が不自然).", "Bu masala juda oddiy, javob tez topilsa kerak. (to'g'ri) ✓", "Zilzilada «oddiy» narsalar olib qoching (noto'g'ri — 必要な kerak).", "Ajoyib film ko'rib, juda «oddiy» his-tuyg'uga keldim (noto'g'ri — 感動 kerak)."], "tr": "単純(たんじゅん) = oddiy, sodda."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t13-g1-1", "stem": "では、開会（　）あたり、代表よりあいさつがございます。", "options": ["に", "を", "と", "が"], "answer": 1, "explanation_uz": "〜にあたり/あたって = ...munosabati bilan, ...paytida (rasmiy)", "tr": "Endi, yig'ilishni ochish munosabati bilan, vakil so'z so'zlaydi."}, {"id": "t13-g1-2", "stem": "吉田「よろしくお願いします。」山崎「こちら（　）よろしく。」", "options": ["まで", "ほど", "こそ", "から"], "answer": 3, "explanation_uz": "〜こそ = aynan..., men ham... (ta'kidlash/qaytarish iborasi)", "tr": "Yoshida: «Iltimos, yaxshi munosabatda bo'ling.» Yamazaki: «Men ham sizga minnatdorman.»"}, {"id": "t13-g1-3", "stem": "なんでもできるあの人の（　）、この仕事もちゃんとやってくれると思います。", "options": ["ことに", "ことには", "ことから", "ことだから"], "answer": 4, "explanation_uz": "〜ことだから = ...tabiatini yaxshi bilgandan, ...bo'lgani uchun (shaxsga xos xulq)", "tr": "Hamma narsani qila oladigan u odamning tabiatidan kelib chiqib, bu ishni ham to'g'ri bajaradi deb o'ylayman."}, {"id": "t13-g1-4", "stem": "林さん（　）、ゼミの発表をすることはできない。", "options": ["なく", "抜きで", "いないで", "切りで"], "answer": 2, "explanation_uz": "〜抜きで = ...siz, ...ni istisno qilib (〜がない状態で)", "tr": "Hayashi janobsiz seminar taqdimotini qilish mumkin emas."}, {"id": "t13-g1-5", "stem": "今年の夏は、天気予報がはずれ、暑い（　）とてもすずしい。", "options": ["に反して", "どころか", "にもかかわらず", "にしては"], "answer": 2, "explanation_uz": "〜どころか = ...balki aksincha (kutilgan narsaning teskari ekanligi ta'kidlanadi)", "tr": "Bu yilgi yoz ob-havo bashorati to'g'ri kelmadi: issiq emas, aksincha juda salqin."}, {"id": "t13-g1-6", "stem": "お金がかかる今までのやり方（　）、鈴木君の案なら費用がかからず安くできる。", "options": ["によって", "に対して", "につれて", "にこたえて"], "answer": 2, "explanation_uz": "〜に対して = ...ga nisbatan, ...bilan solishtirganda (qarama-qarshilik)", "tr": "Qimmat bo'lgan avvalgi usulga nisbatan, Suzuki janobning taklifi arzon amalga oshiriladi."}, {"id": "t13-g1-7", "stem": "友だちと別れてつらかったが、時間が（　）につれ、悲しい気持ちも消えていった。", "options": ["たつ", "たって", "たった", "たてば"], "answer": 1, "explanation_uz": "時間がたつにつれ = vaqt o'tgan sari (〜につれ = ...ga qarab, ...ga mos ravishda)", "tr": "Do'stimdan ajralish og'ir bo'ldi, ammo vaqt o'tishi bilan qayg'u ham yo'qoldi."}, {"id": "t13-g1-8", "stem": "客「すみませんが、こちらの電話を（　）いただいてもよろしいですか。」社員「はい、どうぞ。」", "options": ["使われて", "使わせて", "使ったら", "使って"], "answer": 2, "explanation_uz": "〜(さ)せていただいてもよろしいでしょうか = ...qilsam bo'ladimi? (ruxsat so'rashning odobli shakli)", "tr": "Mijoz: «Kechirasiz, bu telefondan foydalansam bo'ladimi?» Xodim: «Ha, marhamat.»"}, {"id": "t13-g1-9", "stem": "ペンがないので先生のものを（　）。", "options": ["貸してもよろしいですか", "返してもよろしいですか", "貸してくださいませんか", "返してくださいませんか"], "answer": 3, "explanation_uz": "〜てくださいませんか = iltimos ...ib bering (〜てくれる ning hurmatli shakli)", "tr": "Qalamim yo'q, shuning uchun o'qituvchimnikini olar edim (bersangiz bo'ladimi)?"}, {"id": "t13-g1-10", "stem": "五木「山下さんがまだ来ていないんですが。」小林「本当ですか？きのう電話で出席すると言っていたので、（　）。」", "options": ["来ないはずですよ", "来ないことですよ", "来ないはずがないですよ", "来ないことがないですよ"], "answer": 3, "explanation_uz": "〜ないはずがない = ...masligi mumkin emas (ishonch ifodalaydi)", "tr": "Itsuki: «Yamashita hali kelmadi.» Kobayashi: «Rostdanmi? Kecha kelaman deb aytgan edi, albatta keladi (kelmasligi mumkin emas).»"}, {"id": "t13-g1-11", "stem": "イベントの準備に時間と費用がかかっているのだから、参加人数が少なくても、最後まで（　）。", "options": ["やるしかありません", "やるわけがありません", "やってはなりません", "やるものではありません"], "answer": 1, "explanation_uz": "〜しかない = ...dan boshqa iloj yo'q (qaror, belgilangan yo'l)", "tr": "Tadbir tayyorgarligiga vaqt va pul sarflangan, shuning uchun ishtirokchilar oz bo'lsa ham, oxirigacha davom ettirishdan boshqa iloj yo'q."}, {"id": "t13-g1-12", "stem": "日本料理ではすしが有名ですが、私はべつに（　）。", "options": ["好きなのです", "好きなようです", "好きなわけです", "好きではありません"], "answer": 4, "explanation_uz": "べつに〜ない = alohida...emas, xususan...emas (inkor)", "tr": "Yapon oshxonasida sushi mashhur, ammo men shaxsan uni yoqtirmayman."}, {"id": "t13-g1-13", "stem": "こんな寒い日には、あたたかいものを（　）。", "options": ["飲まないに限る", "飲むに限る", "飲まないに限らない", "飲むに限らない"], "answer": 2, "explanation_uz": "〜に限る = ...eng yaxshisi, ...dan ustun yo'q", "tr": "Bunday sovuq kunda issiq narsa ichish eng yaxshisi."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t13-g2-14", "options": ["に", "ため", "調査", "かかった"], "answer": 2, "prefix": "この報告書を作る", "suffix": "の期間は四か月だ。", "starPos": 1, "order": [2, 1, 4, 3], "explanation_uz": "To'g'ri tartib: ため→に→かかった→調査 (報告書を作るためにかかった調査)", "tr": "To'g'ri jumla: «Bu hisobotni tuzish uchun sarflangan tadqiqot muddati to'rt oy bo'ldi.»"}, {"id": "t13-g2-15", "options": ["どう", "ご予定", "これから", "なさる"], "answer": 4, "prefix": "今日の予定はこれで終わりましたが、", "suffix": "ですか。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: これから→どう→なさる→ご予定 (なさる = する ning hurmat shakli)", "tr": "To'g'ri jumla: «Bugungi jadval tugadi, bundan keyin nima qilmoqchi edingiz?»"}, {"id": "t13-g2-16", "options": ["なんでも", "ことには", "なにが", "成功させない"], "answer": 4, "prefix": "会社にとって大事なこの仕事を、", "suffix": "会社が倒産してしまう。", "starPos": 3, "order": [3, 1, 4, 2], "explanation_uz": "To'g'ri tartib: なにが→なんでも→成功させない→ことには (〜ないことには = ...masdan bo'lmaydi)", "tr": "To'g'ri jumla: «Kompaniya uchun muhim bo'lgan bu ishni, har qanday holatda ham muvaffaqiyatli yakunlamasak, kompaniya bankrot bo'lib qoladi.»"}, {"id": "t13-g2-17", "options": ["ことに", "いる", "なって", "食事をする"], "answer": 3, "prefix": "明日は家族と", "suffix": "ので、また今度さそってくれるかな。", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "To'g'ri tartib: 食事をする→ことに→なって→いる (〜ことになっている = ...qilinishi belgilangan)", "tr": "To'g'ri jumla: «Ertaga oila bilan ovqatlanish rejalashtirilgan, shuning uchun keyingi gal chaqir.»"}, {"id": "t13-g2-18", "options": ["服を", "ほしかった", "ついでに", "行った"], "answer": 2, "prefix": "ひさしぶりに東京へ遊びに", "suffix": "買ってきた。", "starPos": 3, "order": [4, 3, 2, 1], "explanation_uz": "To'g'ri tartib: 行った→ついでに→ほしかった→服を (〜ついでに = ...bahonasida, ...paytida foydalanib)", "tr": "To'g'ri jumla: «Uzoq vaqt bo'lgach Tokioga o'yingani borganim bahonasida, sotib olmоqchi bo'lgan kiyimni olib keldim.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "英語教育は本当に必要だろうか", "passage": "日本では英語の教育はとても大事だという話を{{19}}。まず学校では、小学校から高校まで英語を学ぶ時間がある。また社会人になってからも、自分から、または会社に言われて英会話教室に通ったり、いろいろな検定試験を受けたりしている人はとても多い。\nまじめに勉強するのは、とてもいいことだと思うが、しかし、私の考えは少し違う。\n{{20}}、インターネットで海外の情報を集めるときや、海外旅行中、日本にいても外国人の観光客から道を聞かれたときなど、英語がわかると便利だと感じるときもある。しかし、目的もなく、「英語は大事だから」という理由で学習する必要があるのか、疑問を感じるのだ。\n{{21a}}、日本で生活し、日本の会社で働いているかぎり、英語を話さなければならない機会はほとんどない{{21b}}。多くの日本人は、英語を話す人とつきあう機会も少ない。それなら、たとえば小学校では日本語を学ぶ時間をもっと増やしたり、会社員ならそれぞれの仕事に本当に必要なことを{{22}}。そうやって日本語の力や、{{23}}技術を身につけたほうが、自分のためになるのではないだろうか。", "passage_tr": "Yaponiyadа ingliz tili ta'limi juda muhim degan gapni KO'P ESHITAMIZ. Avvalo maktablarda, boshlang'ichdan o'rta maktabgacha ingliz tili o'qitiladigan vaqt bor. Shuningdek, ishga kirganidan keyin ham o'zi ixtiyori bilan yoki kompaniya tavsiyasiga ko'ra ingliz tili kurslariga qatnaydiganlar, turli imtihon topshiradiganlar juda ko'p. Jiddiy o'qish yaxshi narsa, ammo mening fikrim biroz boshqacha. ALBATTA, internetdan xorijiy ma'lumot to'plaganda, xorijga sayohatda, Yaponiyada bo'lsada xorijiy sayyohlar yo'l so'raganda inglizcha bilish qulay bo'ladi. Biroq maqsadsiz, «ingliz tili muhim» degan sabab bilan o'rganish kerakmi, shunda shubha paydo bo'ladi. CHUNKI Yaponiyada yashab, yapon kompaniyasida ishlagancha inglizcha gapirish kerak bo'lgan holat deyarli yo'q, chunki shunday. Ko'pchilik yaponlar inglizcha gapiruvchilar bilan muloqot qilish imkoniyati ham kam. Shunday ekan, masalan, boshlang'ich maktabda yapon tili o'rganishga ko'proq vaqt ajratish yoki kompaniya xodimi bo'lsa har bir ishi uchun chinakam kerakli narsalarni O'RGANISH KERAK deb o'ylayman. Shunday qilib yapon tili kuchi va ZUDLIK BILAN FOYDALI bo'lgan ko'nikma egallash o'zi uchun foydali bo'lmaydi, deb o'ylamaysizmi.", "questions": [{"id": "t13-g3-19", "options": ["よく聞かれる", "よく聞かせる", "よく聞かされる", "よく聞くようにさせる"], "answer": 3, "blankNo": "19", "explanation_uz": "よく聞かされる = passiv shaklda ko'p eshitiladigan (〜される = biror narsa qilinadi)", "tr": "英語教育は大事だという話を[よく聞かされる] = ...gapni KO'P ESHITAMIZ (majburiy eshitish — passiv)."}, {"id": "t13-g3-20", "options": ["その後", "確かに", "だから", "すると"], "answer": 2, "blankNo": "20", "explanation_uz": "確かに = albatta, to'g'ri (keyingi gapda «lekin» bilan ziddiyat ifodalanadi)", "tr": "[確かに]、インターネットで… = ALBATTA, internetda... (lekin keyin boshqacha fikr aytiladi)."}, {"id": "t13-g3-21", "options": ["a ところが ／ b にきまっている", "a ところで ／ b わけである", "a なぜなら ／ b からである", "a なぜ ／ b のだろうか"], "answer": 3, "blankNo": "21", "explanation_uz": "なぜなら〜からである = chunki〜, sababi〜 (sabab-natija izohlovchi juft ibora)", "tr": "[なぜなら]…機会はほとんどない[からである] = CHUNKI...imkon deyarli yo'q, CHUNKI shunday."}, {"id": "t13-g3-22", "options": ["学ばないほうがよいと思う", "学ぶほうがよいと思わない", "学ぶべきではないと思う", "学ぶべきだと思う"], "answer": 4, "blankNo": "22", "explanation_uz": "学ぶべきだと思う = o'rganish kerak deb o'ylayman (べき = ...lozim, ...kerak)", "tr": "仕事に必要なことを[学ぶべきだと思う] = ish uchun kerakli narsalarni O'RGANISH KERAK deb o'ylayman."}, {"id": "t13-g3-23", "options": ["いつか役立つ", "すぐに役立つ", "ずっと役立たない", "あまり役立たない"], "answer": 2, "blankNo": "23", "explanation_uz": "すぐに役立つ = darhol foydali bo'ladigan (zudlik bilan qo'l keladigan)", "tr": "日本語の力や[すぐに役立つ]技術を… = yapon tili va ZUDLIK BILAN FOYDALI bo'lgan ko'nikmalar."}]}]}]}, "14": {"id": 14, "title_jp": "第14回 模擬テスト", "title_uz": "14-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t14-v1-1", "stem": "その船は、太平洋に【沈んで】しまった。", "options": ["およんで", "ころんで", "きしんで", "しずんで"], "answer": 4, "reading": "しずんで", "explanation_uz": "沈む → しずむ (cho'kmoq, botmoq)", "tr": "U kema Tinch okeaniga cho'kib ketdi."}, {"id": "t14-v1-2", "stem": "彼はとても【幸運】な人だ。", "options": ["ごうん", "ごううん", "こうん", "こううん"], "answer": 4, "reading": "こううん", "explanation_uz": "幸運 → こううん (baxt, omad)", "tr": "U juda baxtli odam."}, {"id": "t14-v1-3", "stem": "いつもより遅く【昼食】をとった。", "options": ["ちゅうしょく", "ちょうしょく", "ちゅうじょく", "ちょうじょく"], "answer": 1, "reading": "ちゅうしょく", "explanation_uz": "昼食 → ちゅうしょく (tushlik)", "tr": "Odatdagidan kechroq tushlik qildim."}, {"id": "t14-v1-4", "stem": "川にたくさんのごみが【浮いて】いる。", "options": ["おいて", "わいて", "ういて", "ついて"], "answer": 3, "reading": "ういて", "explanation_uz": "浮く → うく (suzmoq, qalqmoq)", "tr": "Daryoda juda ko'p axlat suzib yuradi."}, {"id": "t14-v1-5", "stem": "引き出しの【奥】に会議の資料があります。", "options": ["すみ", "おく", "はし", "なか"], "answer": 2, "reading": "おく", "explanation_uz": "奥 → おく (ichki qism, tub, chuqur)", "tr": "Tortmaning chuqur ichida yig'ilish hujjatlari bor."}, {"id": "t14-v1-6", "stem": "【料金】が安いほうを選ぶ。", "options": ["よきん", "りょきん", "ようきん", "りょうきん"], "answer": 4, "reading": "りょうきん", "explanation_uz": "料金 → りょうきん (to'lov, narx, tarifı)", "tr": "Narxi arzonroq tomonni tanlayman."}, {"id": "t14-v1-7", "stem": "週末、【田舎】へ出かけた。", "options": ["たんぼ", "はたけ", "のはら", "いなか"], "answer": 4, "reading": "いなか", "explanation_uz": "田舎 → いなか (qishloq, periferiya)", "tr": "Dam olish kunlari qishloqqa chiqdim."}, {"id": "t14-v1-8", "stem": "その集会は、午後5時に【閉会】した。", "options": ["かいかい", "かいがい", "へいかい", "へいがい"], "answer": 3, "reading": "へいかい", "explanation_uz": "閉会 → へいかい (yig'ilishni yopish, yig'ilish tugashi)", "tr": "U yig'ilish kechqurun soat 5da yopildi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t14-v2-9", "stem": "【めんどう】な仕事をしなくてはいけない。", "options": ["面頭", "面働", "面倒", "面動"], "answer": 3, "explanation_uz": "めんどう → 面倒 (noqulay, zahmatli, bezovta)", "tr": "Noqulay (zahmatli) ishni qilishim kerak."}, {"id": "t14-v2-10", "stem": "昔の【きろく】を参考にする。", "options": ["紀錄", "紀綠", "記錄", "記録"], "answer": 4, "explanation_uz": "きろく → 記録 (yozuv, qayd, rekord)", "tr": "Qadimgi yozuvlarni (rekordlarni) ko'rib chiqaman."}, {"id": "t14-v2-11", "stem": "その小鳥を【とらえて】、かごの中に入れた。", "options": ["取らえて", "担らえて", "補らえて", "捕らえて"], "answer": 4, "explanation_uz": "とらえる → 捕らえる (ushlash, tutib olmoq)", "tr": "U qushchani ushladi va qafasga solib qo'ydi."}, {"id": "t14-v2-12", "stem": "その新聞と、この新聞の書き方を【くらべて】ください。", "options": ["批べて", "比べて", "調べて", "対べて"], "answer": 2, "explanation_uz": "くらべる → 比べる (solishtimoq, taqqoslamoq)", "tr": "O'sha gazeta va bu gazeta yozilishini solishtiring."}, {"id": "t14-v2-13", "stem": "この電話には、【きのう】がたくさん付いている。", "options": ["性能", "効能", "技能", "機能"], "answer": 4, "explanation_uz": "きのう → 機能 (funksiya, imkoniyat)", "tr": "Bu telefonda juda ko'p funksiya bor."}, {"id": "t14-v2-14", "stem": "新しい【こいびと】ができた。", "options": ["恋人", "好人", "愛人", "来人"], "answer": 1, "explanation_uz": "こいびと → 恋人 (sevgili, yor)", "tr": "Yangi sevgilim paydo bo'ldi."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t14-v3-15", "stem": "この文法は、試験によく出る（　）だ。", "options": ["ポスト", "ポイント", "テンポ", "ポジション"], "answer": 2, "explanation_uz": "ポイント = nuqta, muhim jihat, imtihon bali", "tr": "Bu grammatika imtihonda ko'p chiqadigan nuqta (ball)."}, {"id": "t14-v3-16", "stem": "車の調子が悪いので、（　）してください。", "options": ["修正", "修理", "調子", "調理"], "answer": 2, "explanation_uz": "修理 = ta'mirlash, tuzatish", "tr": "Mashina buzilgan, ta'mirlab bering."}, {"id": "t14-v3-17", "stem": "料理が足りないので、注文を（　）してください。", "options": ["追加", "節約", "合計", "強化"], "answer": 1, "explanation_uz": "追加 = qo'shimcha, qo'shish", "tr": "Taom yetmayapti, buyurtmani qo'shing."}, {"id": "t14-v3-18", "stem": "この病気は人に（　）ので、注意してください。", "options": ["移る", "働く", "渡る", "動く"], "answer": 1, "explanation_uz": "移る = ko'chmoq, yuqmoq (kasallik)", "tr": "Bu kasallik odamga yuqadi, ehtiyot bo'ling."}, {"id": "t14-v3-19", "stem": "どんな職業につくかは（　）の自由だ。", "options": ["別人", "個人", "数人", "何人"], "answer": 2, "explanation_uz": "個人の自由 = shaxsiy erkinlik", "tr": "Qanday kasb tanlash — shaxsiy erkinlik."}, {"id": "t14-v3-20", "stem": "ベランダにふとんを（　）出かけた。", "options": ["ほして", "まいて", "しいて", "つるして"], "answer": 1, "explanation_uz": "ほす = quritmoq, yoymoq (ko'rpa, kiyim)", "tr": "Balkonga ko'rpani yoyib (quritib) chiqib ketdim."}, {"id": "t14-v3-21", "stem": "今月から、新しい生活が（　）した。", "options": ["アップ", "ダウン", "スタート", "ストップ"], "answer": 3, "explanation_uz": "スタート = boshlash, start", "tr": "Bu oydan yangi hayot boshlandi."}, {"id": "t14-v3-22", "stem": "母に（　）のセーターをもらって、うれしかった。", "options": ["手立て", "手ぬい", "手さぐり", "手作り"], "answer": 4, "explanation_uz": "手作り = qo'lda yasalgan, uy ishlab chiqarishi", "tr": "Onamdan qo'lda to'qilgan sviter olganim uchun xursand bo'ldim."}, {"id": "t14-v3-23", "stem": "田中さんは、友人たちに（　）されています。", "options": ["自信", "信頼", "責任", "達成"], "answer": 2, "explanation_uz": "信頼 = ishonch, e'timod", "tr": "Tanaka janob do'stlari tomonidan ishonchga sazovor."}, {"id": "t14-v3-24", "stem": "会社に入って3年、仕事のおもしろさが（　）わかってきました。", "options": ["さっぱり", "べつに", "だんだん", "あんまり"], "answer": 3, "explanation_uz": "だんだん = asta-sekin, sekin-asta", "tr": "Kompaniyaga kirganiga 3 yil, ishning qiziqligini asta-sekin tushuna boshladim."}, {"id": "t14-v3-25", "stem": "クラスのみんなに（　）されて、悲しくなった。", "options": ["無欲", "無味", "無害", "無視"], "answer": 4, "explanation_uz": "無視 = e'tiborsizlik, pisand qilmaslik", "tr": "Sinfdoshlarning hammasi e'tiborsiz qoldirgani uchun xafa bo'ldim."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t14-v4-26", "stem": "午後は町を【ふらふら】していた。", "options": ["話しながら歩いて", "考えながら歩いて", "目的もなく歩いて", "目標に向かって歩いて"], "answer": 3, "explanation_uz": "ふらふらする = laqillab yurmoq, maqsadsiz kezmoq → 目的もなく歩いて", "tr": "Tushdan keyin shaharni maqsadsiz kezib yurdim."}, {"id": "t14-v4-27", "stem": "冬になって、よく【寝坊する】ようになりました。", "options": ["早く起きる", "遅く起きる", "早く寝る", "遅く寝る"], "answer": 2, "explanation_uz": "寝坊する = kech turmoq, uyquni o'tkazib yubormoq → 遅く起きる", "tr": "Qish kelishi bilan kech turadigan bo'ldim."}, {"id": "t14-v4-28", "stem": "野菜を【あげて】、料理を作りました。", "options": ["細かく切って", "よく混ぜて", "生のままで", "油で調理して"], "answer": 4, "explanation_uz": "あげる (揚げる) = yog'da qovurmoq → 油で調理して", "tr": "Sabzavotlarni qovurib (yog'da) taom tayyorladim."}, {"id": "t14-v4-29", "stem": "問題だと思うことを【書き出して】ください。", "options": ["みんなに伝えて", "パソコンで入力して", "大きな字で書いて", "必要な部分をまとめて"], "answer": 4, "explanation_uz": "書き出す = yozib chiqmoq, ro'yxat tuzmoq → 必要な部分をまとめて", "tr": "Muammo deb o'ylaydigan narsalarni yozib chiqing (sanab chiqing)."}, {"id": "t14-v4-30", "stem": "今日は【ついている】1日だった。", "options": ["運がよい", "運が悪い", "体調がよい", "体調が悪い"], "answer": 1, "explanation_uz": "ついている = omidir kelmoq, baxtli → 運がよい", "tr": "Bugun omadli kun bo'ldi."}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t14-v5-31", "stem": "横になる", "options": ["机の上に、ペンが横になっています。", "川のとなりに、小さな家が横になっています。", "ねむくなったので、ふとんに横になった。", "空に白い雲が横になり、きれいだ。"], "answer": 3, "optsTr": ["Stol ustida qalam 'gorizontal'da turibdi (noto'g'ri — 置いてある kerak).", "Daryo yonida kichik uy 'gorizontal' (noto'g'ri — 建っている kerak).", "Uyqum keldi va ko'rpaga yotdim. (to'g'ri)", "Osmonda oq bulut 'gorizontal' bo'lib, chiroyli (noto'g'ri — 横に伸びて kerak)."], "tr": "横になる = yotmoq, gorizontal holatga kelmoq."}, {"id": "t14-v5-32", "stem": "転がる", "options": ["時間がなかったので、家から会社まで転がっていった。", "男の子の投げたボールは、地面に転がった。", "部屋から、空に飛行機が転がっているのが見えます。", "駅から公園まで、バスが転がっているのでとても便利です。"], "answer": 2, "optsTr": ["Vaqt yo'q edi, uydan kompaniyagacha 'dumalab' ketdim (noto'g'ri — 急いで kerak).", "Bola tashlagan to'p yerda dumaladi. (to'g'ri)", "Xonadan osmonda samolyot 'dumalayotganini' ko'rish mumkin (noto'g'ri — 飛んでいる kerak).", "Bekatdan parkgacha avtobus 'dumalayapti' (noto'g'ri — 走っている kerak)."], "tr": "転がる(ころがる) = dumalab yurmoq, ag'anab ketmoq."}, {"id": "t14-v5-33", "stem": "底", "options": ["いすの底に、2匹のねこが寝ています。", "スカートの底が地面につきそうです。", "私の家は、大きな山の底にあります。", "この魚は、深い海の底に住んでいます。"], "answer": 4, "optsTr": ["Stul 'tubida' 2 ta mushuk yotibdi (noto'g'ri — 下 kerak).", "Yubkaning 'tubi' yerga tegay deyapti (noto'g'ri — 裾/すそ kerak).", "Mening uyim katta tog'ning 'tubida' (noto'g'ri — ふもと kerak).", "Bu baliq chuqur dengizning tubida yashaydi. (to'g'ri)"], "tr": "底(そこ) = tub, pastki qism, dib."}, {"id": "t14-v5-34", "stem": "兼ねる", "options": ["あの人は、2つの仕事を兼ねている。", "となりの家に兼ねて、なるべく静かに生活しています。", "きれいな花をたくさん兼ねて、花束を作った。", "家の鍵を兼ねないで、外出してしまった。"], "answer": 1, "optsTr": ["U kishi 2 ta ishni birga olib boryapti. (to'g'ri)", "Qo'shni uyga 'birlashtirib', imkon qadar jim yashamoqdaman (noto'g'ri — 遠慮して kerak).", "Ko'p chiroyli gul 'birlashtirib', guldasta yasadim (noto'g'ri — 集めて kerak).", "Uy kalitini 'birlashtirmasdan' chiqib ketdim (noto'g'ri — 忘れて kerak)."], "tr": "兼ねる(かねる) = bir vaqtda bajarmoq, birlashtirib olib bormoq."}, {"id": "t14-v5-35", "stem": "まずい", "options": ["私は、彼のようなまずいな人間はきらいです。", "今日の天気は、暑いというよりはまずい。", "学生なのだから授業に遅刻をするのはまずい。", "このりんごは高いので、少しまずくしてください。"], "answer": 3, "optsTr": ["Men u kabi 'nosoz' odamni yoqtirmayman (noto'g'ri — ひどい kerak).", "Bugungi ob-havo issiq deysizmi, 'nosoz' (noto'g'ri — むしろ kerak).", "Talaba bo'la turib darsga kech qolish — noo'rin (uyatli). (to'g'ri)", "Bu olma qimmat, biroz 'nosoz' qiling (noto'g'ri — 安く kerak)."], "tr": "まずい = nosoz, noqulay; yomon (ta'm); uyatli, noo'rin."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t14-g1-1", "stem": "となりの人がどろぼうをして逮捕された。悪い人（　）見えなかったけど。", "options": ["より", "では", "でも", "には"], "answer": 4, "explanation_uz": "〜には = ...ga (ko'rinish, baho berish kontekstida — 悪い人には見えない = yomon odam bo'lib ko'rinmaydi)", "tr": "Qo'shni odam o'g'rilik qilib hibsga olindi. Yomon odam kabi ko'rinmasdi-da."}, {"id": "t14-g1-2", "stem": "朝、牛乳を飲んだ（　）、今まで何も食べていません。", "options": ["ところ", "だけで", "さえ", "しか"], "answer": 2, "explanation_uz": "〜だけで = faqat ...ingina bilan (yuklamasi — yetarlilik/cheklov)", "tr": "Ertalab faqat sut ichib, hozirgacha hech narsa yemedim."}, {"id": "t14-g1-3", "stem": "まったく勉強していない佐藤さんが、あの大学に合格できる（　）。", "options": ["もんか", "ことか", "ところか", "はずか"], "answer": 1, "explanation_uz": "〜もんか = aslo ...maslik (qat'iy inkor, retorik). 口語的.", "tr": "Umuman o'qimagan Sato-san o'sha universitetga o'ta oladimi? (aslo mumkin emas!)"}, {"id": "t14-g1-4", "stem": "彼は、彼女と何も話す（　）なく、帰って行った。", "options": ["ほど", "ところ", "もの", "こと"], "answer": 4, "explanation_uz": "何も〜ことなく = ...masdan, ...siz (ことなく = qilmasdan)", "tr": "U u bilan hech narsa gaplashmasdan ortiga qaytdi."}, {"id": "t14-g1-5", "stem": "このゲームは子どもに（　）、大人にも人気がある。", "options": ["限って", "限らず", "すぎて", "すぎず"], "answer": 2, "explanation_uz": "〜に限らず = ...gina emas, ...dan tashqari ham", "tr": "Bu o'yin nafaqat bolalar, balki kattalar orasida ham mashhur."}, {"id": "t14-g1-6", "stem": "大げんかした（　）、彼女と離婚しました。", "options": ["末は", "末までが", "末に", "末から"], "answer": 3, "explanation_uz": "〜末に = ...dan keyin (uzoq/og'ir jarayon natijasida). 〜あげく bilan o'xshash.", "tr": "Katta janjal qilgan natijasida u ayolidan ajrashdi."}, {"id": "t14-g1-7", "stem": "息子「なんだか風邪をひいたみたい。」母「そういうときは、暖かくしてゆっくり（　）よ。」", "options": ["休むわけ", "休むほう", "休むはず", "休むこと"], "answer": 4, "explanation_uz": "〜こと = ...moq kerak (amir shakli — こと/のこと)", "tr": "O'g'il: «Shamolladim shekilli.» Ona: «Bunday paytda iliq kiyinib yaxshilab dam olish kerak.»"}, {"id": "t14-g1-8", "stem": "先生「原子力をテーマにした映画を見て、どう思いましたか。」生徒「はい、これからのエネルギーについて考え（　）ました。」", "options": ["考えて", "考えたまま", "考えさせ", "考えさせられ"], "answer": 4, "explanation_uz": "〜させられる = majburiy bajarish (passiv-majburiy shakl). 考えさせられる = o'ylanishga majbur etilmoq.", "tr": "O'qituvchi: «Atom energiyasi haqidagi filmni ko'rib nima deb o'yladingiz?» O'quvchi: «Ha, kelajakdagi energiya haqida o'ylanib qoldim (o'ylashga majbur bo'ldim).»"}, {"id": "t14-g1-9", "stem": "明日、お宅へ（　）つもりですが、よろしいでしょうか。", "options": ["拝見する", "お目にかかる", "いただく", "うかがう"], "answer": 4, "explanation_uz": "うかがう = «bormoq/so'ramoq» ning kamtarlik shakli (謙譲語). 訪問する → うかがう.", "tr": "Ertaga siznikiga borishni niyat qilgan edim, qulay bo'ladimi?"}, {"id": "t14-g1-10", "stem": "女の学生「この新しいシューズ、歩く（　）、やせるらしいよ。」男の学生「本当かなあ。」", "options": ["歩くだけでも", "歩いたままでも", "歩くばかりで", "歩くことより"], "answer": 1, "explanation_uz": "〜だけでも = faqat ...ingina bilan ham. 歩くだけでやせる = yurishning o'ziyoq ozaytiradi.", "tr": "Qiz talaba: «Bu yangi poyabzal, yurishning o'ziyoq ozaytirarmish.» O'g'il talaba: «Chinmi?»"}, {"id": "t14-g1-11", "stem": "この町の昔と今を比較すると、その違いには驚く（　）。", "options": ["くらいがあります", "ほどがあります", "ものがあります", "のがあります"], "answer": 3, "explanation_uz": "〜ものがある = ...da biror narsa bor (hayrat, his-tuyg'u ifodalash). 驚くものがある = hayratlanarli jihat bor.", "tr": "Bu shaharning ilgari va hozirini solishtirsangiz, farqi hayratga soladi."}, {"id": "t14-g1-12", "stem": "会議が始まると電話に（　）、メールを送って下さい。", "options": ["出ようとしないので", "出られそうにないので", "出るようなので", "出るそうなので"], "answer": 2, "explanation_uz": "〜そうにない = ...olishi dargumon, ...ib bo'lmaydi (ehtimollik yetarli emas)", "tr": "Yig'ilish boshlanganida telefonga chiqolmay qolsam, elektron xat yuboring."}, {"id": "t14-g1-13", "stem": "パク「キムさんって、とてもすてきな人だね。」木村「でも、キムさんは確か（　）。」", "options": ["結婚していそうだよ", "結婚していっこないって", "結婚しているわけだよ", "結婚しているんだって"], "answer": 4, "explanation_uz": "〜んだって = ...deyishadi, ...ekan (eshitish, rivoyat). 確か〜んだって = ishonchim komil emas, lekin eshitishimcha...", "tr": "Pak: «Kim janob juda ajoyib odam ekan.» Kimura: «Lekin Kim janob turmush qurib bo'lgan deyishadi.»"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t14-g2-14", "options": ["あまり", "夢中に", "研究に", "なる"], "answer": 4, "prefix": "科学者の田中さんは、", "suffix": "ときどき食事をするのを忘れてしまう。", "starPos": 3, "order": [3, 2, 4, 1], "explanation_uz": "研究に夢中になるあまり (〜あまり = juda ...ganidan, haddan ziyod ...gani sababli)", "tr": "To'g'ri jumla: «Olim Tanaka janob tadqiqotiga shu qadar berilib ketib, ba'zida ovqatlanishni ham unutib qo'yadi.»"}, {"id": "t14-g2-15", "options": ["よろしければ", "させて", "お手伝いを", "私で"], "answer": 2, "prefix": "大変そうですね。", "suffix": "いただけませんか。", "starPos": 4, "order": [4, 1, 3, 2], "explanation_uz": "私でよろしければお手伝いをさせていただけませんか (させていただく = hurmat bilan ruxsat so'rash)", "tr": "To'g'ri jumla: «Kelin, men yordam berib tursammi?» (Agar kerak bo'lsa, yordam berishga ruxsat bering.)"}, {"id": "t14-g2-16", "options": ["パーティー", "いない", "なんて", "前田さんが"], "answer": 1, "prefix": "後藤「えー、", "suffix": "楽しくありませんよ。」", "starPos": 3, "order": [4, 2, 1, 3], "explanation_uz": "前田さんがいないパーティーなんて楽しくない (〜なんて = ... kabi narsa, mensimaslik yoki hayrat)", "tr": "To'g'ri jumla: «Eh, Maeda-san bo'lmagan ziyofat qiziq bo'lmaydi-ya.»"}, {"id": "t14-g2-17", "options": ["よかった", "して", "明日に", "おけば"], "answer": 2, "prefix": "今日は1日天気が悪かったので、デートは", "suffix": "と後悔した。", "starPos": 2, "order": [3, 2, 4, 1], "explanation_uz": "明日にしておけばよかった (〜ておけばよかった = ...ib qo'yganim maqul edi, afsus)", "tr": "To'g'ri jumla: «Bugun havo yomon edi, shu sababli ko'rishuvni ertaga qoldirganim maqul ekan, afsusdaman.»"}, {"id": "t14-g2-18", "options": ["気をつける", "際に", "べき", "点を"], "answer": 3, "prefix": "外国で仕事をする", "suffix": "教えてください。", "starPos": 3, "order": [2, 1, 3, 4], "explanation_uz": "際に気をつけるべき点を (際に = paytida; 〜べき = ...ish kerak bo'lgan)", "tr": "To'g'ri jumla: «Chet elda ishlayotganingizda e'tibor berish kerak bo'lgan nuqtalarni o'rgating.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "秋の気配", "passage": "8月の終わりごろといえば、まだとても暑い時期だ。太陽はぎらぎらと輝き、都会のアスファルトの上を歩いている人々は暑さで疲れている。毎日暑くて、元気がなくなる人も多いだろう。\n{{19}}、山の森の中に行ってみると、街にいるよりも空気が冷たく、早くも秋の気配が満ちているのに気がつくだろう。山に行き、おいしい空気を吸って、美しい景色を{{20}}、夏の暑さを忘れることができる。\n山まで遠いし、行く時間もない、という人も多いだろう。{{21}}、都会の中の森に出かけてみてはいかがだろうか。都会の中にある大きな公園の森に入ってみれば、街の中と気温が大きく違うことに驚くだろう。大きな公園でなくてもよい。家の近所にある小さな公園の中の森や、住宅地の中の歩道につくられた林でも{{22}}。きれいな色の小さな実がなっていたり、秋になって色が変わった草が、しずかに風に吹かれていたりするのを見つけられるだろう。そして、こんな目立たないところでも花や草はきちんと生きているのだと感じ、人より早く秋の気配を発見した喜びを{{23}}。", "passage_tr": "Avgust oyi oxirlari deyilsa, hali juda issiq davr. Quyosh yaltirab nurini sochadi, shahardagi asfalt ustida yurayotgan odamlar issiqdan holdan toygan. Har kuni issiq bo'lib, kuchsizlanib qolgan odamlar ham ko'p bo'lsa kerak.\nBIROQ, tog'dagi o'rmonga borsangiz, shahardan ko'ra havo sovuqroq va allaqachon kuzning alomatlari to'la ekanini sezasiz. Tog'ga borib, toza havo tutatib, go'zal manzaraga QARAShNING O'ZI ham yozning issig'ini unutishga yetadi.\nTog' uzoq, bora olmayman, deydiganlar ham ko'pdir. BUNDAY PAYTDA shahardagi o'rmonga chiqqan maqul. Shahardagi katta bog'dagi o'rmonga kirsangiz, shahardagidan havo harorati ancha farq qilishiga hayron qolasiz. Katta bog' bo'lishi shart emas. Uy yonidagi kichik bog'dagi o'rmon yoki turar-joy hududidagi yo'lakdagi daraxtlarzor ham YETARLI. Ko'p rangli kichik mevalar yoki kuz kelishi bilan rangi o'zgargan o'tlar sekin shamolda hilpiraganini topasiz. Va, bunday ko'zga tashlanmaydigan joyda ham gullar va o'tlar tirik ekanini his qilib, boshqalardan oldin kuzning alomatlarini topgan sevinchni his qilishingizga shubha yo'q.", "questions": [{"id": "t14-g3-19", "options": ["だから", "けれども", "つまり", "その上"], "answer": 2, "blankNo": "19", "explanation_uz": "けれども = lekin, ammo (qarama-qarshilik bog'lovchisi)", "tr": "[けれども]、山の森の中に行ってみると… = BIROQ, tog'dagi o'rmonga borsangiz..."}, {"id": "t14-g3-20", "options": ["見るからに", "見たままで", "見るだけでも", "見ないまでも"], "answer": 3, "blankNo": "20", "explanation_uz": "〜だけでも = faqat ...ingina ham (yetarlilik)", "tr": "美しい景色を[見るだけでも]、夏の暑さを忘れることができる = go'zal manzaraga QARASHNING O'ZI ham yozni unuttirar."}, {"id": "t14-g3-21", "options": ["そんなときは", "あんなときは", "そちらのときは", "あちらのときは"], "answer": 1, "blankNo": "21", "explanation_uz": "そんなときは = bunday paytda (yaqin kontekstga ishora)", "tr": "という人も多いだろう。[そんなときは]、都会の中の森に… = deydiganlar ko'p. BUNDAY PAYTDA shahardagi o'rmonga..."}, {"id": "t14-g3-22", "options": ["十分だ", "十分ではない", "違っている", "違っていない"], "answer": 1, "blankNo": "22", "explanation_uz": "十分だ = yetarli, kifoya", "tr": "住宅地の中の歩道の林でも[十分だ] = turar-joy yo'lakdagi daraxtlarzor ham YETARLI."}, {"id": "t14-g3-23", "options": ["感じかねない", "感じるほかはない", "感じることができかねる", "感じられるにちがいない"], "answer": 4, "blankNo": "23", "explanation_uz": "〜にちがいない = albatta, shubhasiz (ishonch)", "tr": "秋の気配を発見した喜びを[感じられるにちがいない] = kuzni topgan sevinchni his qilishingizga SHUBHA YO'Q."}]}]}]}, "15": {"id": 15, "title_jp": "第15回 模擬テスト", "title_uz": "15-test", "minutes": 50, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿のことばの読み方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t15-v1-1", "stem": "大事なことなので、【文書】で回答してください。", "options": ["もんしょう", "もんしょ", "ぶんしょう", "ぶんしょ"], "answer": 4, "reading": "ぶんしょ", "explanation_uz": "文書 → ぶんしょ (hujjat, yozma material)", "tr": "Muhim masala bo'lgani uchun yozma ravishda javob bering."}, {"id": "t15-v1-2", "stem": "毎日練習をしたので、【実力】がついた。", "options": ["しつりょく", "じつりょく", "しつりき", "じつりき"], "answer": 2, "reading": "じつりょく", "explanation_uz": "実力 → じつりょく (haqiqiy qobiliyat, mahorat)", "tr": "Har kuni mashq qilganimdan keyin haqiqiy kuch (mahorat) paydo bo'ldi."}, {"id": "t15-v1-3", "stem": "冷蔵庫で氷が【固まる】。", "options": ["つまる", "あまる", "あつまる", "かたまる"], "answer": 4, "reading": "かたまる", "explanation_uz": "固まる → かたまる (qotmoq, qattiqlashmoq)", "tr": "Muzlatgichda muz qotadi (qattiq bo'ladi)."}, {"id": "t15-v1-4", "stem": "風に木の葉が【舞って】いました。", "options": ["おどって", "ちって", "まって", "さって"], "answer": 3, "reading": "まって", "explanation_uz": "舞う → まう (aylanib uchmoq, g'ir aylanmoq)", "tr": "Shamolda daraxt barglari g'ir aylanar edi."}, {"id": "t15-v1-5", "stem": "食べ続けても、体に【害】はありません。", "options": ["かい", "がい", "とく", "どく"], "answer": 2, "reading": "がい", "explanation_uz": "害 → がい (zarar, ziyon)", "tr": "Yeya bersangiz ham tanaga zarari yo'q."}, {"id": "t15-v1-6", "stem": "新しいルールは、わが社にとって【有利】だ。", "options": ["ふり", "ふうり", "ゆり", "ゆうり"], "answer": 4, "reading": "ゆうり", "explanation_uz": "有利 → ゆうり (afzallik, qulay holat)", "tr": "Yangi qoida bizning kompaniya uchun qulay (foydali)."}, {"id": "t15-v1-7", "stem": "この町には、有名な【港】があります。", "options": ["きし", "みなと", "うみ", "はま"], "answer": 2, "reading": "みなと", "explanation_uz": "港 → みなと (port, qayiqxona)", "tr": "Bu shaharda mashhur port bor."}, {"id": "t15-v1-8", "stem": "2人の意見が【対立】している。", "options": ["たいりつ", "だいりつ", "たいりゅう", "だいりゅう"], "answer": 1, "reading": "たいりつ", "explanation_uz": "対立 → たいりつ (qarama-qarshilik, ziddiyat)", "tr": "2 kishining fikri qarama-qarshi turibdi."}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿のことばを漢字で書くとき、最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanji bilan yozganda eng to'g'risini tanlang.", "questions": [{"id": "t15-v2-9", "stem": "【みごと】なポーズで着地した。", "options": ["美事", "味事", "夢事", "見事"], "answer": 4, "explanation_uz": "みごと → 見事 (ajoyib, chiroyli, muvaffaqiyatli)", "tr": "Go'zal poza bilan yerga tushdi."}, {"id": "t15-v2-10", "stem": "【きょうどう】で、新しい仕事をはじめた。", "options": ["強同", "強道", "共同", "共道"], "answer": 3, "explanation_uz": "きょうどう → 共同 (hamkorlik, birgalikda)", "tr": "Hamkorlikda yangi ish boshladik."}, {"id": "t15-v2-11", "stem": "初めて会った人に【めいし】をもらった。", "options": ["名氏", "名札", "名刺", "名紙"], "answer": 3, "explanation_uz": "めいし → 名刺 (vizit kartochka)", "tr": "Birinchi marta uchrashgan odamdan vizit kartochka oldim."}, {"id": "t15-v2-12", "stem": "あなたの行いは、だれかを【すくう】ことができるかもしれない。", "options": ["補う", "助う", "求う", "救う"], "answer": 4, "explanation_uz": "すくう → 救う (qutqarmoq, najot bermoq)", "tr": "Sizning harakatingiz biror kishini qutqarishi mumkin."}, {"id": "t15-v2-13", "stem": "クリスマスの【ていばん】の商品は、このケーキだ。", "options": ["丁番", "定番", "丁版", "定版"], "answer": 2, "explanation_uz": "ていばん → 定番 (an'anaviy, klassik, standarт mahsulot)", "tr": "Rojdestvo uchun eng an'anaviy mahsulot — bu tort."}, {"id": "t15-v2-14", "stem": "夜中に家の外で【あしおと】が聞こえた。", "options": ["足声", "足後", "足音", "足元"], "answer": 3, "explanation_uz": "あしおと → 足音 (oyoq tovushi, qadam tovushi)", "tr": "Yarim tunda uydan tashqarida oyoq tovushi eshitildi."}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "( ) ga qo'yish uchun eng mos so'zni tanlang.", "questions": [{"id": "t15-v3-15", "stem": "毎月たくさん雑誌を買うので、部屋に置く（　）がない。", "options": ["ウェイト", "アウトドア", "インテリア", "スペース"], "answer": 4, "explanation_uz": "スペース = joy, bo'sh joy (space)", "tr": "Har oy juda ko'p jurnal sotib olganimdan xonada qo'yadigan joy yo'q."}, {"id": "t15-v3-16", "stem": "私が動物を好きになったのは、両親の（　）だ。", "options": ["反響", "伝統", "影響", "代表"], "answer": 3, "explanation_uz": "影響 = ta'sir (influence)", "tr": "Men hayvonlarni yaxshi ko'rib qolganim ota-onamning ta'siri."}, {"id": "t15-v3-17", "stem": "旅行者がけんかをしたことがA国とB国の（　）問題になった。", "options": ["海外", "国外", "交通", "外交"], "answer": 4, "explanation_uz": "外交 = diplomatiya, tashqi siyosat", "tr": "Sayyohlarning janjali A va B mamlakatlar o'rtasida diplomatik muammoga aylandi."}, {"id": "t15-v3-18", "stem": "外出するので、アクセサリーを（　）。", "options": ["はいた", "かぶった", "つけた", "せおった"], "answer": 3, "explanation_uz": "つける = taqmoq, kiymoq (aksessuar, bezak)", "tr": "Tashqariga chiqayotganim uchun aksessuarlarni taqdim (kiydim)."}, {"id": "t15-v3-19", "stem": "この生き物は、魚の（　）だ。", "options": ["一派", "一種", "一期", "一流"], "answer": 2, "explanation_uz": "一種 = bir tur, bir xil (kind/species)", "tr": "Bu jonzot baliqning bir turi."}, {"id": "t15-v3-20", "stem": "一か月の生活（　）はどのくらいですか。", "options": ["金", "価", "費", "値"], "answer": 3, "explanation_uz": "費 = xarajat, sarf (生活費 = tirikchilik xarajati)", "tr": "Bir oylik hayot xarajati qancha?"}, {"id": "t15-v3-21", "stem": "彼女を（　）して、この曲を作りました。", "options": ["イコール", "アレンジ", "イメージ", "スケッチ"], "answer": 3, "explanation_uz": "イメージする = tasavvur qilmoq, ko'z o'ngida keltirmoq", "tr": "Uni tasavvur qilib (xayolimga keltirb) bu qo'shiqni yaratdim."}, {"id": "t15-v3-22", "stem": "彼は動物学者なので、動物に（　）。", "options": ["くわしい", "まぶしい", "くやしい", "たのもしい"], "answer": 1, "explanation_uz": "くわしい = yaxshi biladigan, teran biladigan (詳しい)", "tr": "U zoolog bo'lgani uchun hayvonlarga oid narsalarni yaxshi biladi."}, {"id": "t15-v3-23", "stem": "今日は休むと、中田さんに（　）してください。", "options": ["提案", "伝言", "要求", "指摘"], "answer": 2, "explanation_uz": "伝言 = xabar berish, so'z qoldirish", "tr": "Bugun ishga kelmaydi deb Nakata janobga xabar qilib qo'ying."}, {"id": "t15-v3-24", "stem": "休みには温泉に行って、何もしないで旅館で（　）したい。", "options": ["そろそろ", "せっせと", "ぐるぐる", "のんびり"], "answer": 4, "explanation_uz": "のんびり = tashasusiz, xotirjam, dam olib (relaxed)", "tr": "Dam olish kunlari issiq buloqqa borib, mexmonxonada hech narsa qilmasdan dam olmoqchiman."}, {"id": "t15-v3-25", "stem": "エジプトのピラミッドは、とても（　）だ。", "options": ["多大", "最大", "巨大", "盛大"], "answer": 3, "explanation_uz": "巨大 = ulkan, juda katta (gigantic)", "tr": "Misr ehromlari juda ulkan (buyuk)."}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "＿＿に意味が最も近いものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin variantni tanlang.", "questions": [{"id": "t15-v4-26", "stem": "【マニュアル】を見ながら作業をする。", "options": ["地図", "手帳", "時刻表", "説明書"], "answer": 4, "explanation_uz": "マニュアル = qo'llanma, yo'riqnoma → 説明書", "tr": "Qo'llanmani ko'rib ish qilaman."}, {"id": "t15-v4-27", "stem": "そこに【じっと】してください。", "options": ["動いて", "動かないで", "見て", "見ないで"], "answer": 2, "explanation_uz": "じっとする = qimirlamasdan turmoq → 動かないで", "tr": "U yerda jim (harakat qilmay) turing."}, {"id": "t15-v4-28", "stem": "田中さんはとても【顔が広い】。", "options": ["頭が大きい", "心がやさしい", "知り合いが多い", "親せきが多い"], "answer": 3, "explanation_uz": "顔が広い = tanish-bilishi ko'p, nufuzli → 知り合いが多い", "tr": "Tanaka janobing tanish-bilishi ko'p."}, {"id": "t15-v4-29", "stem": "【あわてて】出かける準備をした。", "options": ["時間をかけて", "簡単に", "急いで", "ゆっくり"], "answer": 3, "explanation_uz": "あわてる = shoshmoq, to'lg'onmoq → 急いで", "tr": "Shoshib-poshib chiqishga tayyorlandim."}, {"id": "t15-v4-30", "stem": "妻「料理の味はどうかな。」夫「【割合】おいしいよ。」", "options": ["思っていたよりも", "すばらしく", "今まででいちばん", "少しは"], "answer": 1, "explanation_uz": "割合 = nisbatan, o'ylagandan → 思っていたよりも", "tr": "Xotin: «Taomning ta'mi qalaymikin?» Er: «O'ylagan darajadan ham mazali.»"}]}, {"id": "v5", "type": "usage", "instruction_jp": "次のことばの使い方として最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilishini tanlang.", "questions": [{"id": "t15-v5-31", "stem": "たまたま", "options": ["お正月は、ずっと家族とたまたま一緒にいた。", "彼にたまたま会うのは、5年ぶりです。", "散歩をしていたら、ファンさんとたまたま会った。", "きちんと計画をたてて、たまたま旅行に行った。"], "answer": 3, "optsTr": ["Yangi yilda doim oila bilan 'tasodifan' birga bo'ldim (noto'g'ri — ずっと kerak).", "U bilan 'tasodifan' uchrashish 5 yildan beri (noto'g'ri — ばったり kerak).", "Sayr qilayotganda Fan janob bilan tasodifan uchrab qoldim. (to'g'ri)", "Rejalashtirgan holda 'tasodifan' sayhonga chiqdim (noto'g'ri — zid)."], "tr": "たまたま = tasodifan, kutilmagan holda."}, {"id": "t15-v5-32", "stem": "補う", "options": ["やぶれたシャツを糸で補ってください。", "サッカーの試合中けがをした足を、すぐに補った。", "夫婦げんかをした後は、早く補ったほうがいい。", "私の足りない部分を、中山さんが補ってくれた。"], "answer": 4, "optsTr": ["Yirtilgan ko'ylakni ip bilan 'to'ldiring' (noto'g'ri — 縫う kerak).", "Futbol paytida jarohatlangan oyoqni 'to'ldirdi' (noto'g'ri — 治療した kerak).", "Er-xotin janjalidan keyin tez 'to'ldirgan' maqul (noto'g'ri — 仲直りした kerak).", "Kamchiligimni Nakayama janob to'ldirib berdi. (to'g'ri)"], "tr": "補う(おぎなう) = to'ldirmoq, qoplab bermoq."}, {"id": "t15-v5-33", "stem": "たば", "options": ["明日、机のたばを捨ててください。", "駅前に10人くらいの人のたばが立っています。", "この地方には、めずらしい動物のたばが住んでいます。", "台の上に紙のたばが置いてあります。"], "answer": 4, "optsTr": ["Ertaga stol 'boglamini' tashlab bering (noto'g'ri — 引き出し kerak).", "Bekat oldida 10 kishilik odamlar 'boglamı' turibdi (noto'g'ri — 群れ kerak).", "Bu hududda noyob hayvonlar 'boglamı' yashaydi (noto'g'ri — 群れ kerak).", "Stol ustida qog'oz boglamı qo'yilgan. (to'g'ri)"], "tr": "たば(束) = to'plam, boglam, tutam."}, {"id": "t15-v5-34", "stem": "都合", "options": ["今日は、都合がなくて一緒に遊びに行けません。", "明日、都合がよければ、うちに食事に来てください。", "これから1週間、外国へ旅行に行く都合です。", "悪い都合で会議に出られず、すみませんでした。"], "answer": 2, "optsTr": ["Bugun 'qulay holat' yo'q, birga o'ynagani bormayman (noto'g'ri — 用事 kerak).", "Ertaga qulay bo'lsa, biznikiga ovqatga keling. (to'g'ri)", "Keyingi 1 hafta chet elga safarim bor 'qulay holat' (noto'g'ri — 予定 kerak).", "Yomon 'qulay holat'dan yig'ilishga chiqa olmadim, kechirasiz (noto'g'ri — 事情 kerak)."], "tr": "都合(つごう) = qulay holat, sharoit, ahvol."}, {"id": "t15-v5-35", "stem": "きつい", "options": ["容器のふたをきつく閉めてください。", "林さんは、ほかのどの社員よりも能力がきつい。", "どんなにきつく考えても、新しいアイデアが出てこなかった。", "田中さんなら体がきついので、あの山に登れるでしょう。"], "answer": 1, "optsTr": ["Idishning qopqog'ini mahkam yoping. (to'g'ri)", "Hayashi janob boshqa xodimlardan 'qattiqroq' (noto'g'ri — 優れている kerak).", "Qanchalik 'qattiq' o'ylasam ham yangi g'oya kelmadi (noto'g'ri — 一生懸命 kerak).", "Tanaka janob tana 'qattiq' bo'lgani uchun o'sha tog'ga chiqoladi (noto'g'ri — 丈夫 kerak)."], "tr": "きつい = mahkam, qattiq; og'ir, qiyin; tor."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t15-g1-1", "stem": "彼女と連絡が取れなくなってから、今日（　）5日になります。", "options": ["は", "で", "に", "が"], "answer": 2, "explanation_uz": "今日で〜日になる = bugun ...kunga to'ldi (で = o'tish muddatini ko'rsatish)", "tr": "U bilan aloqa yo'qolganidan bugun 5 kun bo'ldi."}, {"id": "t15-g1-2", "stem": "お金（　）あれば、今よりもっといい生活ができるのに。", "options": ["まで", "しか", "さえ", "ほど"], "answer": 3, "explanation_uz": "〜さえあれば = faqat ...bo'lsa (yetarlilik sharti). お金さえあれば = faqat pul bo'lsa kifoya.", "tr": "Pul bo'lsa, hozirdan yaxshiroq hayot kechirgan bo'lardim."}, {"id": "t15-g1-3", "stem": "一度約束した（　）、絶対に守ってください。", "options": ["からでは", "からには", "からいって", "からといって"], "answer": 2, "explanation_uz": "〜からには = ...ekan, ...dan keyin (mas'uliyat, zaruriyat). 約束したからには = va'da bergan ekanmiz.", "tr": "Bir marta va'da bergan ekanmiz, albatta bajarish kerak."}, {"id": "t15-g1-4", "stem": "今井「今日のセミナー、なんだか出席者が少ないね。」山本「電車の事故（　）、みんなが来るのが遅れているらしいよ。」", "options": ["ので", "のわけで", "のに", "のせいで"], "answer": 4, "explanation_uz": "〜のせいで = ...sababidan (salbiy natija). 事故のせいで = avariya sababli.", "tr": "Imai: «Bugungi seminar, qatnashchilar kamligi bor.» Yamamoto: «Poyezd avariyas sababli hammasining kechikayotgani.»"}, {"id": "t15-g1-5", "stem": "先週は、3日間（　）大雪が降りました。", "options": ["にまで", "にかけて", "にこそ", "にわたって"], "answer": 4, "explanation_uz": "〜にわたって = ...davomida, ...bo'yi (muddatni ko'rsatish). 3日間にわたって = 3 kun mobaynida.", "tr": "O'tgan hafta 3 kun davomida katta qor yog'di."}, {"id": "t15-g1-6", "stem": "2年前の旅行を（　）、彼女と親しくなった。", "options": ["最中に", "限りに", "きっかけに", "ついでに"], "answer": 3, "explanation_uz": "〜をきっかけに = ...ni bahona (sabab) qilib. 旅行をきっかけに = sayohatdan keyin.", "tr": "2 yil oldingi sayohatni bahona qilib u qiz bilan yaqinlashdim."}, {"id": "t15-g1-7", "stem": "なんでこんなに手がよごれているんだ。すぐに（　）しろ。", "options": ["きれいに", "きれいな", "きれい", "きれいで"], "answer": 1, "explanation_uz": "きれいに + する = toza holga keltirmoq (副詞的に使う)", "tr": "Nima uchun qo'ling shunchalik ifloslangan? Darhol tozala."}, {"id": "t15-g1-8", "stem": "テストの答えを聞かれても、（　）わけがありません。", "options": ["教えない", "教えられる", "教えて", "教えた"], "answer": 2, "explanation_uz": "教えられるわけがない = aytishim aslo mumkin emas (できるわけがない = imkoni yo'q)", "tr": "Test javoblarini so'rasalar ham ayta olmayman (aytishim mumkin emas)."}, {"id": "t15-g1-9", "stem": "私が旅行で買ってきたおみやげを、社長に（　）。", "options": ["しました", "くださいました", "やりました", "さしあげました"], "answer": 4, "explanation_uz": "さしあげる = bermoqning kamtarlik shakli (目上の人に物をあげる). やる < あげる < さしあげる.", "tr": "Safardan sotib kelgan sovg'amni direktorga taqdim etdim."}, {"id": "t15-g1-10", "stem": "父「どうして泣いてるんだ?」娘「だって、お母さんが（　）。」", "options": ["いないんだっけ", "いないんだもん", "いなかったっけ", "いないんだそう"], "answer": 2, "explanation_uz": "〜んだもん = ...da-ku (o'zi oqlash, bolalar tili). いないんだもん = yo'q-da, bo'lmasa nima qilay.", "tr": "Ota: «Nima uchun yig'layapsan?» Qiz: «Chunki onam yo'q-da.»"}, {"id": "t15-g1-11", "stem": "子どものころは、この川でよく（　）。", "options": ["泳いだものです", "泳ぎたいものです", "泳いだやらです", "泳ぎたいやらです"], "answer": 1, "explanation_uz": "〜たものだ = ilgari shunday qilardim (nostalgiya, o'tmiш odati). 泳いだものだ = suzar edim.", "tr": "Bolaligimda bu daryoda ko'p suzardim."}, {"id": "t15-g1-12", "stem": "おかげさまで、とても楽しくこの仕事を（　）。またよろしくお願い申し上げます。", "options": ["していただきました", "されていただきました", "なさっていただきました", "させていただきました"], "answer": 4, "explanation_uz": "させていただく = ruxsat so'rab bajarish, kamtarlik (〜させていただきました = qilishga ruxsat berdingiz).", "tr": "Siz tufayli bu ishni juda zavq bilan bajarish imkoniga ega bo'ldim. Yana yordam so'rayman."}, {"id": "t15-g1-13", "stem": "情報は、新聞が伝えているから正しい（　）、自分で正しいかどうか考えることが大切だ。", "options": ["としたことでなく", "としたことで", "というものではなく", "というもので"], "answer": 3, "explanation_uz": "〜というものではない = ...deb bo'lmaydi, ...degani emas (kategorik inkor)", "tr": "Axborot gazetada yozilgan uchun to'g'ri deyish mumkin emas — o'zing ham to'g'ri yoki yo'qligini o'yla."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng mos bo'lakni tanlang.", "questions": [{"id": "t15-g2-14", "options": ["あげく", "どちらに", "なやんだ", "行くか"], "answer": 3, "prefix": "連休に、海か山か", "suffix": "、みんなで海水浴に行った。", "starPos": 3, "order": [2, 4, 3, 1], "explanation_uz": "どちらに行くか なやんだ あげく (〜あげく = uzoq o'ylanganidan keyin, oxir-oqibatda)", "tr": "To'g'ri jumla: «Ta'tilda dengizgami, tog'gami borishni uzoq o'ylab, oxirida hammamiz dengizga cho'mish borishga qaror qildik.»"}, {"id": "t15-g2-15", "options": ["後で", "が", "お休みになった", "その"], "answer": 4, "prefix": "きのうの夜、先生", "suffix": "みんなでお酒を飲みました。", "starPos": 3, "order": [2, 3, 4, 1], "explanation_uz": "先生がお休みになったその後で (お休みになる = «dam olmoq» hurmat shakli; その後で = undan keyin)", "tr": "To'g'ri jumla: «Kecha kechqurun o'qituvchi dam olib bo'lgandan keyin hammamiz spirtli ichimlik ichdik.»"}, {"id": "t15-g2-16", "options": ["けんかでも", "ものなら", "しよう", "友だちと"], "answer": 3, "prefix": "子どものころ、", "suffix": "、母にひどくしかられました。", "starPos": 3, "order": [4, 1, 3, 2], "explanation_uz": "友だちとけんかでもしようものなら (〜ようものなら = ...qilmoqchi bo'lsang, darhol yomon narsa bo'ladi)", "tr": "To'g'ri jumla: «Bolaligimda do'stim bilan janjallashay deb tursamgina, onam qattiq urar edi.»"}, {"id": "t15-g2-17", "options": ["わりに", "小さい", "体が", "ほうだ"], "answer": 2, "prefix": "あの人は、スポーツ選手の", "suffix": "と思います。", "starPos": 3, "order": [3, 1, 2, 4], "explanation_uz": "体がわりに小さいほうだ (〜わりに = ...ga nisbatan, kutilgandan farqli holda)", "tr": "To'g'ri jumla: «U kishi sportchi bo'lishiga qaramay, tanasi nisbatan kichik deb o'ylayman.»"}, {"id": "t15-g2-18", "options": ["ともかく", "なら", "そんな", "今は"], "answer": 1, "prefix": "昔", "suffix": "習慣はありません。", "starPos": 2, "order": [2, 1, 3, 4], "explanation_uz": "昔ならともかく、そんな今は習慣はありません (ならともかく = ilgari bo'lsa mayli, lekin hozir...)", "tr": "To'g'ri jumla: «Ilgari bo'lsa mayli, bunday davrda endi bu odat yo'q.»"}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "つぎの文章を読んで、19から23の中に入る最もよいものを、1・2・3・4から一つえらびなさい。", "instruction_uz": "Matnni o'qib, 19-23 bo'sh joylarga eng mos variantni tanlang.", "passage_title": "美術館めぐりのすすめ", "passage": "この秋、A市の中心エリアでは、美術館めぐりのイベントを行っています。芸術に力を入れているA市には、3つのとても有名な美術館があります。このイベントは、県立美術館、市立美術館、山田太郎記念美術館の3つをまわり、それぞれの美術館に入場するときに、用紙にスタンプをもらうというものです。期間中はどの美術館でも入場料は、{{19}} 500円です。3つの美術館は、駅から電車やバスを使えば10分以内で行ける便利な場所にあります。2館以上スタンプを{{20a}}、絵はがきやポスター、シールなどの景品の中から好きなものを1つ{{20b}}\nイベントの期間中、すべての美術館で、特別展覧会も開かれています。{{21}}展覧会もおすすめです。特に、山田太郎美術館では、いつもは公開されていない、日本の美術の歴史の中でも「名作」とされている山田太郎氏の絵画3枚を公開します。その他の美術館でも、{{22}}知っている有名な絵画がいくつも展示される予定です。\n美術や絵画にあまり関心のない方も、このような機会に美術館めぐりをしながら「芸術の秋」をゆっくりと味わってみては{{23}}", "passage_tr": "Bu kuz, A shahrining markaziy hududida san'at muzeylari aylanish tadbirini o'tkazmoqda. San'atga alohida e'tibor beradigan A shahrida 3 ta juda mashhur muzey bor. Bu tadbir viloyat san'at muzeyi, shahar san'at muzeyi va Yamada Taro yodgorlik muzeyini aylanib, har biriga kirishda varaqqa muhur olish tarzida o'tadi. Tadbir davomida har qanday muzeyga kirish narxi YOSHDAN QATI NAZAR 500 yen. 3 ta muzey ham bekatdan poyezd yoki avtobus bilan 10 daqiqada yetib boradigan qulay joyda. 2 va undan ko'p muzeylarda muhur TO'PLASANGIZ, rasmli kartochka, poster, stiker kabi sovg'alar orasidan 1 ta OLASIZ.\nTadbir davomida barcha muzeylarda maxsus ko'rgazma ham ochiladi. BU ko'rgazma ham tavsiya etiladi. Xususan, Yamada Taro muzeyida odatda namoyish etilmaydigan, yapon san'ati tarixida «durdonа» sanaluvchi Yamada Taro-ning 3 ta rasmini ko'rgazmaga qo'yadi. Boshqa muzeylarda ham HAMMA bilgan mashhur rasmlar ko'rgazmaga qo'yilishi rejalashtirilgan.\nSan'at va rasmlarga ko'p qiziqmaydigan kimsalar ham bunday imkoniyatda muzeylarni aylanib «kuz san'ati»ni xotirjam tatib ko'rsalar QANDAY BO'LARKIN?", "questions": [{"id": "t15-g3-19", "options": ["年齢にもかかわらず", "年齢にかかわらず", "年齢にもかぎらず", "年齢にかぎらず"], "answer": 2, "blankNo": "19", "explanation_uz": "年齢にかかわらず = yoshdan qat'i nazar (〜にかかわらず = ...dan qat'i nazar, ...ga qaramasdan)", "tr": "入場料は[年齢にかかわらず]500円 = kirish narxi YOSHDAN QATI NAZAR 500 yen."}, {"id": "t15-g3-20", "options": ["集めると ／ もらえるようです", "集めると ／ もらえます", "集めるとき ／ もらいます", "集めるとき ／ もらうことができます"], "answer": 2, "blankNo": "20", "explanation_uz": "集めると (shartli: to'plasangiz) + もらえます (olasiz — aniq va'da)", "tr": "2館以上スタンプを[集めると]…景品の中から1つ[もらえます] = to'plasangiz…sovg'a olasiz."}, {"id": "t15-g3-21", "options": ["あの", "ああ", "この", "こう"], "answer": 3, "blankNo": "21", "explanation_uz": "この = bu (yaqin kontekstga ishora — avval aytilgan ko'rgazmaga ishora)", "tr": "すべての美術館で特別展覧会も開かれています。[この]展覧会もおすすめです = ...maxsus ko'rgazma ham bor. BU ko'rgazma ham tavsiya etiladi."}, {"id": "t15-g3-22", "options": ["だれかが", "だれかは", "だれにも", "だれでも"], "answer": 4, "blankNo": "22", "explanation_uz": "だれでも = hamma, istalgan kishi (umumiy qamrov). だれかが ≠ hamma.", "tr": "その他の美術館でも、[だれでも]知っている有名な絵画が… = boshqa muzeylarda ham HAMMA bilgan mashhur rasmlar."}, {"id": "t15-g3-23", "options": ["よかったでしょうか", "よろしいでしょうか", "どうだったでしょうか", "いかがでしょうか"], "answer": 4, "blankNo": "23", "explanation_uz": "いかがでしょうか = qanday bo'lar ekan? (taklif/tavsiya qilishda yumshoq ifodalash). よろしいでしょうか bilan farqi: いかが = taklif, よろしい = ruxsat so'rash.", "tr": "「芸術の秋」をゆっくりと味わってみては[いかがでしょうか] = «kuz san'ati»ni tatib ko'rsalar QANDAY BO'LARKIN?"}]}]}]}};
